window.ETSDATA=window.ETSDATA||{};window.ETSDATA[14]={"lc":{"p1":[{"n":1,"opts":["He's cleaning the floor.","He's setting a plant on a shelf.","He's pouring some liquid into a cup.","He's ironing a shirt."],"vi":["Anh ấy đang lau sàn nhà.","Anh ấy đang đặt một chậu cây lên kệ.","Anh ấy đang rót chất lỏng vào cốc.","Anh ấy đang ủi áo sơ mi."],"ans":"C","xp":"Ảnh một người: người đàn ông đang rót chất lỏng vào cốc (pouring some liquid into a cup) → chọn (C). (A) lau sàn, (B) đặt cây lên kệ, (D) ủi áo đều là hành động không có trong ảnh.","a":"E24-T04-01.mp3","img":"q1.jpg"},{"n":2,"opts":["They're glancing at a monitor.","They're putting pens in a jar.","They're wiping off a desk.","They're examining a document."],"vi":["Họ đang liếc nhìn màn hình.","Họ đang cắm bút vào lọ.","Họ đang lau bàn.","Họ đang xem xét một tài liệu."],"ans":"D","xp":"Ảnh nhiều người: mọi người đang cùng xem xét một tài liệu (examining a document) → chọn (D). (A) họ không nhìn màn hình, (B) không cắm bút vào lọ, (C) không lau bàn → sai động tác.","a":"E24-T04-02.mp3","img":"q2.jpg"},{"n":3,"opts":["Some people are taking a ride on a boat.","A boat is floating under a bridge.","A boat is being loaded with cargo.","Some people are rowing a boat past a lighthouse."],"vi":["Một vài người đang đi thuyền.","Một chiếc thuyền đang trôi dưới cầu.","Một chiếc thuyền đang được chất hàng hóa lên.","Một vài người đang chèo thuyền đi ngang qua ngọn hải đăng."],"ans":"A","xp":"Ảnh có người ngồi trên thuyền → 'taking a ride on a boat' (đi thuyền) → chọn (A). (B) không có cây cầu, (C) không có hàng hóa (cargo), (D) không có ngọn hải đăng (lighthouse) trong ảnh.","a":"E24-T04-03.mp3","img":"q3.jpg"},{"n":4,"opts":["There's a fire burning in a fireplace.","There's a guitar beside a fireplace.","Some cables have been left on the ground in a pile.","A television is being packed into a box."],"vi":["Có lửa đang cháy trong lò sưởi.","Có một cây đàn guitar bên cạnh lò sưởi.","Một vài sợi dây cáp bị bỏ thành đống trên sàn.","Một chiếc tivi đang được đóng vào hộp."],"ans":"B","xp":"Ảnh đồ vật: có cây đàn guitar đặt bên cạnh lò sưởi (beside a fireplace) → chọn (B). (A) không có lửa, (C) dây cáp không bị chất thành đống, (D) không có cái hộp nào.","a":"E24-T04-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some people are riding bicycles through a field.","Some people are moving a picnic table.","There are some mountains in the distance.","A bicycle has fallen over on the ground."],"vi":["Một vài người đang đạp xe băng qua cánh đồng.","Một vài người đang di chuyển một chiếc bàn dã ngoại.","Có vài ngọn núi ở phía xa.","Một chiếc xe đạp bị đổ xuống đất."],"ans":"C","xp":"Phía xa trong ảnh có núi → 'some mountains in the distance' → chọn (C). (A) không ai đang đạp xe, (B) không ai di chuyển bàn, (D) xe đạp không bị đổ (sai trạng thái).","a":"E24-T04-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some couches have been pushed against a wall.","Some lights have been hung from the ceiling.","Some cushions have been stacked on the floor.","Some flowers have been arranged in a vase."],"vi":["Mấy chiếc ghế sofa được kê sát vào tường.","Mấy chiếc đèn được treo từ trần nhà.","Mấy chiếc gối tựa được chất chồng trên sàn.","Một vài bông hoa được cắm trong bình."],"ans":"D","xp":"Ảnh đồ vật: hoa được cắm trong bình (arranged in a vase) → chọn (D). (A) sofa không kê sát tường, (B) đèn không treo trên trần, (C) gối không chất trên sàn → sai vị trí.","a":"E24-T04-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Does the shop open on Sundays?","qvi":"Cửa hàng có mở cửa vào Chủ nhật không?","opts":["Yes, at one o'clock.","Because we drove.","I'd like to return this item, please."],"vi":["Có, lúc một giờ.","Vì chúng tôi lái xe đến.","Tôi muốn trả lại món hàng này."],"ans":"A","xp":"Câu hỏi Yes/No về việc cửa hàng có mở vào Chủ nhật không → (A) 'Có' + nói thêm giờ mở cửa → hợp lý. (B) trả lời cho câu hỏi Why. (C) dùng từ liên tưởng 'return' (shop) để gây bẫy.","a":"E24-T04-07.mp3"},{"n":8,"q":"Where did these oranges come from?","qvi":"Những quả cam này từ đâu tới vậy?","opts":["Here's a basket you can use.","From a supplier in California.","That umbrella is a nice color."],"vi":["Đây là cái giỏ bạn có thể dùng.","Từ một nhà cung cấp ở California.","Cái ô đó màu đẹp đấy."],"ans":"B","xp":"Câu hỏi Where hỏi nguồn gốc cam → (B) 'Từ một nhà cung cấp ở California' → đúng. (A) 'basket' là từ liên tưởng với 'oranges'. (C) 'color' gây nhầm với màu cam (orange).","a":"E24-T04-08.mp3"},{"n":9,"q":"Should I make the dinner reservation for Friday or Saturday?","qvi":"Tôi nên đặt bàn ăn tối vào thứ Sáu hay thứ Bảy?","opts":["The Beachside Bistro.","Saturday is better.","A large plate of pasta."],"vi":["Nhà hàng Beachside Bistro.","Thứ Bảy thì tốt hơn.","Một đĩa mì Ý lớn."],"ans":"B","xp":"Câu hỏi lựa chọn (thứ Sáu hay thứ Bảy) → (B) chọn 'thứ Bảy' → đúng. (A) tên nhà hàng, không trả lời ngày. (C) 'pasta' là từ liên tưởng với 'dinner'.","a":"E24-T04-09.mp3"},{"n":10,"q":"Will Dr. Ivanova be late today?","qvi":"Hôm nay bác sĩ Ivanova có đến muộn không?","opts":["No, you shouldn't have to wait long.","It's just under the desk.","Sure, I can do that for you."],"vi":["Không, bạn sẽ không phải đợi lâu đâu.","Nó ở ngay dưới bàn.","Chắc chắn rồi, tôi có thể làm việc đó giúp bạn."],"ans":"A","xp":"Hỏi bác sĩ có đến muộn không → (A) 'Không, bạn sẽ không phải đợi lâu' → hợp lý. (B) trả lời câu hỏi Where. (C) dùng để đáp lời nhờ vả, không hợp.","a":"E24-T04-10.mp3"},{"n":11,"q":"Aren't there locker rooms at this gym?","qvi":"Phòng tập này không có phòng thay đồ à?","opts":["These socks are quite comfortable.","She teaches an exercise class.","Yes, they're on the lower floor."],"vi":["Đôi tất này khá thoải mái.","Cô ấy dạy một lớp thể dục.","Có, chúng ở tầng dưới."],"ans":"C","xp":"Câu hỏi phủ định hỏi có phòng thay đồ không → (C) 'Có, ở tầng dưới' → đúng. (A) không liên quan. (B) 'She' không chỉ ai trong câu hỏi; 'exercise' liên tưởng với 'gym'.","a":"E24-T04-11.mp3"},{"n":12,"q":"Who needs a copy of my safety training certificate?","qvi":"Ai cần bản sao giấy chứng nhận đào tạo an toàn của tôi?","opts":["Maksim does.","You can hang your vest on that hook.","No, I'm certain about that."],"vi":["Maksim cần.","Bạn có thể treo áo gi-lê lên cái móc đó.","Không, tôi chắc chắn về điều đó."],"ans":"A","xp":"Câu hỏi Who → (A) nêu tên người 'Maksim' → đúng. (B) 'vest' (áo bảo hộ) liên tưởng với 'safety'. (C) câu hỏi Who không trả lời bằng Yes/No; 'certain' gần âm 'certificate'.","a":"E24-T04-12.mp3"},{"n":13,"q":"Could you phone Mr. Feras and let him know we're in the hotel lobby?","qvi":"Bạn có thể gọi điện cho ông Feras và báo rằng chúng ta đang ở sảnh khách sạn không?","opts":["Thank you, it was just renovated.","A free continental breakfast.","Yes, of course."],"vi":["Cảm ơn bạn, nó vừa mới được cải tạo.","Bữa sáng kiểu lục địa miễn phí.","Vâng, tất nhiên rồi."],"ans":"C","xp":"Câu nhờ vả (Could you...?) → (C) 'Vâng, tất nhiên rồi' → đồng ý giúp → đúng. (A) 'renovated' liên tưởng với 'hotel lobby'. (B) 'breakfast' liên tưởng với 'hotel'.","a":"E24-T04-13.mp3"},{"n":14,"q":"Where does she sell her handmade jewelry?","qvi":"Cô ấy bán đồ trang sức thủ công của mình ở đâu?","opts":["They'll give you a discount.","A pair of earrings.","At a store in the city center."],"vi":["Họ sẽ giảm giá cho bạn.","Một đôi bông tai.","Tại một cửa hàng ở trung tâm thành phố."],"ans":"C","xp":"Câu hỏi Where (bán ở đâu) → (C) 'Tại một cửa hàng ở trung tâm thành phố' → đúng. (A) 'discount' liên tưởng với 'sell'. (B) 'earrings' liên tưởng với 'jewelry'.","a":"E24-T04-14.mp3"},{"n":15,"q":"You're taking a business class in the afternoon, aren't you?","qvi":"Bạn học lớp kinh doanh vào buổi chiều, phải không?","opts":["Actually, it's in the morning.","That office is on the corner.","I have the train schedule here."],"vi":["Thật ra là vào buổi sáng.","Văn phòng đó ở góc đường.","Tôi có lịch tàu ở đây."],"ans":"A","xp":"Câu hỏi đuôi xác nhận học lớp kinh doanh buổi chiều → (A) 'Thật ra là buổi sáng' → sửa lại thông tin, hợp lý. (B) 'office' liên tưởng với 'business'. (C) 'train' liên tưởng với 'business class' (hạng thương gia).","a":"E24-T04-15.mp3"},{"n":16,"q":"Could I see some sample floral arrangements before I order?","qvi":"Tôi có thể xem vài mẫu cắm hoa trước khi đặt hàng không?","opts":["It's for an award ceremony.","A charge for expedited delivery.","Certainly, I have some right here."],"vi":["Nó dành cho một buổi lễ trao giải.","Phí giao hàng nhanh.","Tất nhiên, tôi có vài mẫu ngay đây."],"ans":"C","xp":"Câu xin phép/nhờ vả → (C) 'Tất nhiên, tôi có vài mẫu ngay đây' → đúng. (A) 'award ceremony' liên tưởng với 'floral arrangements'. (B) 'delivery' liên tưởng với 'order'.","a":"E24-T04-16.mp3"},{"n":17,"q":"Don't you want to buy the black sofa?","qvi":"Bạn không muốn mua chiếc sofa màu đen à?","opts":["Some customer reviews.","We already have one.","I take my coffee with sugar."],"vi":["Vài đánh giá của khách hàng.","Chúng tôi đã có một cái rồi.","Tôi uống cà phê có đường."],"ans":"B","xp":"Câu hỏi phủ định hỏi có muốn mua sofa đen không → (B) 'Chúng tôi đã có một cái rồi' → từ chối gián tiếp → đúng. (A) 'customer reviews' liên tưởng với 'buy'. (C) 'coffee' liên tưởng với 'black' (cà phê đen).","a":"E24-T04-17.mp3"},{"n":18,"q":"Do you have this jacket in a larger size?","qvi":"Bạn có chiếc áo khoác này cỡ lớn hơn không?","opts":["Oh, I'm not a sales associate.","I've read the information packet.","A very large uniform."],"vi":["Ồ, tôi không phải nhân viên bán hàng.","Tôi đã đọc tập tài liệu thông tin rồi.","Một bộ đồng phục rất rộng."],"ans":"A","xp":"Hỏi có áo cỡ lớn hơn không → (A) 'Tôi không phải nhân viên bán hàng' → ngầm nói mình không biết → hợp lý. (B) 'packet' phát âm gần 'jacket'. (C) 'large' lặp từ 'larger' để gây bẫy.","a":"E24-T04-18.mp3"},{"n":19,"q":"Where did you first learn about the job opening?","qvi":"Lần đầu bạn biết về vị trí tuyển dụng này ở đâu?","opts":["Are there any outdoor tables available?","The door to the building is still open.","I read an online newspaper every morning."],"vi":["Còn bàn ngoài trời nào trống không?","Cửa vào tòa nhà vẫn đang mở.","Sáng nào tôi cũng đọc báo mạng."],"ans":"C","xp":"Hỏi biết tin tuyển dụng ở đâu → (C) 'Sáng nào tôi cũng đọc báo mạng' → ngầm nói biết qua báo mạng → đúng. (A) không liên quan. (B) 'open' gây nhầm với 'opening'.","a":"E24-T04-19.mp3"},{"n":20,"q":"Should I bring anything to the meeting?","qvi":"Tôi có nên mang gì đến cuộc họp không?","opts":["Probably in the conference room.","They were hired by our manager.","Do we have enough handouts?"],"vi":["Có lẽ là ở phòng hội nghị.","Họ được quản lý của chúng ta tuyển.","Chúng ta có đủ tài liệu phát tay chưa?"],"ans":"C","xp":"Hỏi có cần mang gì đến cuộc họp → (C) hỏi lại 'Chúng ta đã đủ tài liệu phát tay chưa?' → gợi ý có thể mang tài liệu → hợp lý. (A) 'conference room' liên tưởng với 'meeting'. (B) 'They' không chỉ ai.","a":"E24-T04-20.mp3"},{"n":21,"q":"What was the total charge for the hotel stay?","qvi":"Tổng chi phí lưu trú khách sạn là bao nhiêu?","opts":["I'd have to look at the receipt.","The fitness center is across from the reception desk.","I'll be eating breakfast in my room."],"vi":["Tôi phải xem lại hóa đơn mới biết.","Phòng tập thể dục ở đối diện quầy lễ tân.","Tôi sẽ ăn sáng trong phòng."],"ans":"A","xp":"Hỏi tổng chi phí → (A) 'Tôi phải xem hóa đơn' → ngầm nói hiện chưa nhớ → hợp lý. (B) 'reception desk' và (C) 'breakfast in my room' đều liên tưởng với 'hotel'.","a":"E24-T04-21.mp3"},{"n":22,"q":"Why did you pursue a career in video game design?","qvi":"Tại sao bạn theo đuổi nghề thiết kế trò chơi điện tử?","opts":["Because I have a talent for it.","This is my new laptop.","It's on the other shelf."],"vi":["Vì tôi có năng khiếu về lĩnh vực đó.","Đây là máy tính xách tay mới của tôi.","Nó ở trên cái kệ kia."],"ans":"A","xp":"Câu hỏi Why → (A) 'Vì tôi có năng khiếu' → nêu lý do → đúng. (B) 'laptop' liên tưởng với 'video game'. (C) trả lời câu hỏi Where.","a":"E24-T04-22.mp3"},{"n":23,"q":"I'd like to attend the job fair next month.","qvi":"Tôi muốn tham dự hội chợ việc làm vào tháng tới.","opts":["The speech was inspiring.","Tunji updated the memo.","Registration closed yesterday."],"vi":["Bài phát biểu rất truyền cảm hứng.","Tunji đã cập nhật bản ghi nhớ.","Việc đăng ký đã đóng hôm qua rồi."],"ans":"C","xp":"Câu trần thuật: muốn dự hội chợ việc làm → (C) 'Đăng ký đã đóng hôm qua' → cho biết lý do không thể tham dự → hợp lý. (A) 'speech' liên tưởng với 'job fair'. (B) không liên quan.","a":"E24-T04-23.mp3"},{"n":24,"q":"Hasn't anyone called you back for the second interview yet?","qvi":"Vẫn chưa có ai gọi lại cho bạn về vòng phỏng vấn thứ hai à?","opts":["A new phone number.","Yes, any available position.","I'm still waiting."],"vi":["Một số điện thoại mới.","Vâng, bất kỳ vị trí nào còn trống.","Tôi vẫn đang chờ."],"ans":"C","xp":"Hỏi đã có ai gọi lại chưa → (C) 'Tôi vẫn đang chờ' → ngầm nói chưa có ai gọi → đúng. (A) 'phone number' liên tưởng với 'called'. (B) 'position' liên tưởng với 'interview'.","a":"E24-T04-24.mp3"},{"n":25,"q":"How many tickets do we need for tonight's concert?","qvi":"Chúng ta cần bao nhiêu vé cho buổi hòa nhạc tối nay?","opts":["The theater is on Johnson Avenue.","At seven thirty sharp.","I'll buy mine at the door."],"vi":["Nhà hát nằm trên đại lộ Johnson.","Đúng 7 giờ 30.","Tôi sẽ tự mua vé của mình ở cửa."],"ans":"C","xp":"Hỏi cần bao nhiêu vé → (C) 'Tôi sẽ tự mua vé ở cửa' → ngầm nói không cần mua vé cho tôi → hợp lý. (A) 'theater' liên tưởng với 'concert'. (B) trả lời câu hỏi When.","a":"E24-T04-25.mp3"},{"n":26,"q":"When are they going to decide who to hire?","qvi":"Khi nào họ sẽ quyết định tuyển ai?","opts":["A much higher salary.","A lot of good résumés have come in.","In the building across the street."],"vi":["Mức lương cao hơn nhiều.","Có rất nhiều hồ sơ xin việc tốt được gửi đến.","Ở tòa nhà bên kia đường."],"ans":"B","xp":"Hỏi khi nào quyết định tuyển → (B) 'Có rất nhiều hồ sơ tốt gửi đến' → ngầm nói sẽ mất thời gian để quyết định → đúng. (A) 'higher' phát âm gần 'hire'. (C) trả lời câu hỏi Where.","a":"E24-T04-26.mp3"},{"n":27,"q":"I had a chance to look over the contract this morning.","qvi":"Sáng nay tôi đã có dịp xem qua bản hợp đồng.","opts":["Their contact information.","Early next week.","What did you think of it?"],"vi":["Thông tin liên lạc của họ.","Đầu tuần sau.","Bạn thấy nó thế nào?"],"ans":"C","xp":"Câu trần thuật: đã xem qua hợp đồng → (C) hỏi lại 'Bạn thấy nó thế nào?' → hỏi ý kiến về hợp đồng → hợp lý. (A) 'contact' phát âm gần 'contract'. (B) 'next week' liên tưởng với 'this morning'.","a":"E24-T04-27.mp3"},{"n":28,"q":"How are the database updates coming along?","qvi":"Việc cập nhật cơ sở dữ liệu đang tiến triển thế nào rồi?","opts":["I've been really busy with the Williams account.","Some customer addresses.","She arrives on Wednesday."],"vi":["Tôi đang rất bận với khách hàng Williams.","Một vài địa chỉ khách hàng.","Cô ấy sẽ đến vào thứ Tư."],"ans":"A","xp":"Hỏi tiến độ cập nhật dữ liệu → (A) 'Tôi đang rất bận với khách hàng Williams' → ngầm nói chưa làm được → đúng. (B) 'customer addresses' liên tưởng với 'database'. (C) 'She' không chỉ ai.","a":"E24-T04-28.mp3"},{"n":29,"q":"When can I bring these boxes into the warehouse?","qvi":"Khi nào tôi có thể mang những thùng này vào nhà kho?","opts":["Ten in a package.","Thanks—I just bought it.","We'll need to clear some space."],"vi":["Mười cái một gói.","Cảm ơn, tôi vừa mua nó.","Chúng ta sẽ cần dọn bớt chỗ trước."],"ans":"C","xp":"Hỏi khi nào mang thùng vào kho → (C) 'Chúng ta cần dọn chỗ trước' → ngầm nói phải đợi dọn xong → hợp lý. (A) 'package' liên tưởng với 'boxes'. (B) không liên quan.","a":"E24-T04-29.mp3"},{"n":30,"q":"The market on Fifth Street is closed for a week.","qvi":"Khu chợ trên đường số Năm đóng cửa một tuần.","opts":["Some new clothes.","Is there another one nearby?","The price has been marked down."],"vi":["Vài bộ quần áo mới.","Gần đây có chợ nào khác không?","Giá đã được giảm."],"ans":"B","xp":"Câu trần thuật: chợ đóng cửa một tuần → (B) hỏi 'Gần đây có chợ nào khác không?' → phản ứng tự nhiên → đúng. (A) 'clothes' phát âm gần 'closed'. (C) 'marked' phát âm gần 'market'.","a":"E24-T04-30.mp3"},{"n":31,"q":"Does the company pay for professional-development courses?","qvi":"Công ty có chi trả cho các khóa học phát triển chuyên môn không?","opts":["Insook helped develop a new product.","We do have a significant budget surplus.","He's always so professional."],"vi":["Insook đã giúp phát triển một sản phẩm mới.","Chúng ta đang dư khá nhiều ngân sách đấy.","Anh ấy lúc nào cũng rất chuyên nghiệp."],"ans":"B","xp":"Hỏi công ty có trả tiền khóa học không → (B) 'Chúng ta dư nhiều ngân sách' → ngầm nói có thể chi trả → đúng. (A) 'develop' lặp gốc từ 'development'. (C) lặp từ 'professional'.","a":"E24-T04-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Excuse me, but wasn't the ferry to Osaka supposed to leave at ten o'clock?","Xin lỗi, chẳng phải chuyến phà đi Osaka lẽ ra khởi hành lúc 10 giờ sao?"],["M","Yes, but the port authority has suspended all marine traffic due to rough water.","Đúng vậy, nhưng cảng vụ đã tạm dừng toàn bộ hoạt động giao thông đường thủy do sóng lớn."],["W","I see. Does that mean ferries are canceled all day?","Tôi hiểu rồi. Vậy có nghĩa là các chuyến phà bị hủy cả ngày à?"],["M","This storm is expected to pass in about three hours. But operations should return to normal after that. Your ticket will be good until midnight.","Cơn bão này dự kiến sẽ qua trong khoảng ba tiếng nữa. Sau đó hoạt động sẽ trở lại bình thường. Vé của chị có giá trị đến nửa đêm."],["W","OK. Then I guess I'll grab some lunch nearby.","Được rồi. Vậy chắc tôi sẽ đi ăn trưa chút gì gần đây."],["M","I highly recommend Mary's Café for sandwiches and soup.","Tôi rất khuyên chị đến Mary's Café để ăn bánh mì kẹp và súp."]],"qs":[{"n":32,"q":"Where most likely are the speakers?","qvi":"Những người nói nhiều khả năng đang ở đâu?","opts":["At a ferry terminal","At a swimming area","At a shopping mall","At a restaurant"],"vi":["Tại bến phà","Tại khu bơi lội","Tại trung tâm mua sắm","Tại nhà hàng"],"ans":"A","xp":"Người phụ nữ hỏi: \"wasn't the ferry to Osaka supposed to leave at ten o'clock?\" (chuyến phà đi Osaka lẽ ra khởi hành lúc 10 giờ) và người đàn ông xác nhận → họ đang ở bến phà (ferry terminal)."},{"n":33,"q":"What problem does the man mention?","qvi":"Người đàn ông đề cập đến vấn đề gì?","opts":["Some repairs are needed.","A business is understaffed.","The weather is bad.","Some tickets are sold out."],"vi":["Cần sửa chữa một số thứ.","Một doanh nghiệp bị thiếu nhân viên.","Thời tiết xấu.","Một số vé đã bán hết."],"ans":"C","xp":"Người đàn ông nói: \"the port authority has suspended all marine traffic due to rough water\" (tạm dừng giao thông đường thủy do sóng lớn) và nhắc đến 'this storm' (cơn bão) → rough water/storm được diễn đạt lại thành 'The weather is bad'."},{"n":34,"q":"What will the woman do next?","qvi":"Người phụ nữ sẽ làm gì tiếp theo?","opts":["Read a book","Get a meal","Watch a movie","Go to a hotel"],"vi":["Đọc sách","Đi ăn","Xem phim","Đến khách sạn"],"ans":"B","xp":"Người phụ nữ nói: \"Then I guess I'll grab some lunch nearby.\" (chắc tôi sẽ đi ăn trưa gần đây) → 'grab some lunch' = 'Get a meal'."}],"a":"E24-T04-32-34.mp3"},{"ns":[35,37],"script":[["W","Good morning. Are you looking for any particular library book, magazine, or newspaper?","Chào buổi sáng. Anh đang tìm cuốn sách, tạp chí hay tờ báo cụ thể nào của thư viện không?"],["M","Actually, no. I'm here because I got an e-mail this morning telling me that I have an overdue book. But I returned it to the after-hours bin last night.","Thật ra là không. Tôi đến đây vì sáng nay tôi nhận được e-mail báo rằng tôi có một cuốn sách quá hạn trả. Nhưng tối qua tôi đã trả nó vào thùng trả sách ngoài giờ rồi."],["W","Sometimes a book gets returned and put back on the shelves without being entered into the system first. I can take a look. Can you tell me the title?","Đôi khi sách được trả và xếp lại lên kệ mà chưa được nhập vào hệ thống trước. Tôi có thể kiểm tra giúp anh. Anh cho tôi biết tên sách được không?"]],"qs":[{"n":35,"q":"Who most likely is the woman?","qvi":"Người phụ nữ nhiều khả năng là ai?","opts":["An author","A librarian","A bookseller","An event organizer"],"vi":["Một tác giả","Một thủ thư","Một người bán sách","Một người tổ chức sự kiện"],"ans":"B","xp":"Người phụ nữ hỏi: \"Are you looking for any particular library book, magazine, or newspaper?\" (anh có đang tìm sách, tạp chí, báo nào của thư viện không) và còn nói về việc nhập sách vào hệ thống → cô ấy là thủ thư (librarian)."},{"n":36,"q":"What does the man say happened this morning?","qvi":"Người đàn ông nói điều gì đã xảy ra sáng nay?","opts":["He received an e-mail notification.","He applied for a job online.","He lost a receipt.","He made a delivery."],"vi":["Anh ấy nhận được một e-mail thông báo.","Anh ấy nộp đơn xin việc trực tuyến.","Anh ấy làm mất hóa đơn.","Anh ấy đã giao một món hàng."],"ans":"A","xp":"Người đàn ông nói: \"I got an e-mail this morning telling me that I have an overdue book\" (sáng nay nhận e-mail báo có sách quá hạn) → 'got an e-mail ... telling me' = 'received an e-mail notification'."},{"n":37,"q":"What does the woman offer to do?","qvi":"Người phụ nữ đề nghị làm gì?","opts":["Attend an event","Fill out an online form","Place an order","Search for an item"],"vi":["Tham dự một sự kiện","Điền một biểu mẫu trực tuyến","Đặt hàng","Tìm kiếm một món đồ"],"ans":"D","xp":"Người phụ nữ nói sách đôi khi được xếp lên kệ mà chưa nhập vào hệ thống và đề nghị: \"I can take a look. Can you tell me the title?\" (tôi có thể kiểm tra, cho tôi biết tên sách) → cô ấy sẽ tìm cuốn sách → 'take a look' = 'Search for an item'."}],"a":"E24-T04-35-37.mp3"},{"ns":[38,40],"script":[["M","Hi. I'm Malik. I talked to you this morning on the phone about a price quote for some painting you want done.","Chào chị. Tôi là Malik. Sáng nay tôi đã nói chuyện điện thoại với chị về báo giá cho công việc sơn mà chị muốn làm."],["W","Oh, hi. Come in. Yes, I want to change the color in the dining room to something lighter.","Ồ, chào anh. Mời vào. Vâng, tôi muốn đổi màu phòng ăn sang màu nào đó sáng hơn."],["M","Not a problem. But I do want to stress that the quote may be higher than you expected because going from a darker color to a lighter one requires more than one coat of paint.","Không vấn đề gì. Nhưng tôi muốn nhấn mạnh rằng báo giá có thể cao hơn chị nghĩ, vì chuyển từ màu tối sang màu sáng cần sơn nhiều hơn một lớp."],["W","I understand. And will you move the table and chairs out of the room before you start?","Tôi hiểu. Vậy anh sẽ chuyển bàn ghế ra khỏi phòng trước khi bắt đầu chứ?"],["M","That shouldn't be necessary. We can cover them with a drop cloth.","Chắc không cần đâu. Chúng tôi có thể phủ chúng bằng tấm vải che."]],"qs":[{"n":38,"q":"What type of business does the man most likely work for?","qvi":"Người đàn ông nhiều khả năng làm việc cho loại hình doanh nghiệp nào?","opts":["A moving company","A furniture manufacturer","A painting company","A catering service"],"vi":["Công ty chuyển nhà","Nhà sản xuất đồ nội thất","Công ty sơn nhà","Dịch vụ cung cấp đồ ăn"],"ans":"C","xp":"Người đàn ông nói: \"I talked to you this morning on the phone about a price quote for some painting you want done\" (báo giá cho công việc sơn) → anh ấy làm cho công ty sơn (painting company)."},{"n":39,"q":"What point does the man emphasize?","qvi":"Người đàn ông nhấn mạnh điểm nào?","opts":["A deposit is required before work can begin.","A price may be higher than expected.","A discount is available for a limited time.","A schedule cannot be changed easily."],"vi":["Cần đặt cọc trước khi bắt đầu công việc.","Giá có thể cao hơn dự kiến.","Có giảm giá trong thời gian giới hạn.","Lịch trình không thể dễ dàng thay đổi."],"ans":"B","xp":"Người đàn ông nói: \"I do want to stress that the quote may be higher than you expected\" → 'stress' = 'emphasize', 'the quote' (báo giá) = 'a price'."},{"n":40,"q":"What does the woman ask about?","qvi":"Người phụ nữ hỏi về điều gì?","opts":["Signing a contract","Purchasing specialized tools","Moving some furniture","Seeing some samples"],"vi":["Ký hợp đồng","Mua dụng cụ chuyên dụng","Di chuyển một số đồ nội thất","Xem vài mẫu"],"ans":"C","xp":"Người phụ nữ hỏi: \"will you move the table and chairs out of the room before you start?\" (anh có chuyển bàn ghế ra ngoài không) → 'the table and chairs' = 'some furniture'."}],"a":"E24-T04-38-40.mp3"},{"ns":[41,43],"script":[["W","Hi. This is my first time in here. Nice place! Looks like you've got lots of state-of-the-art equipment.","Chào anh. Đây là lần đầu tôi đến đây. Chỗ này đẹp quá! Có vẻ các anh có rất nhiều thiết bị hiện đại nhất."],["M","Yes, we just opened this week. All the exercise bikes, treadmills, and workout stations that you see are brand-new.","Vâng, chúng tôi vừa khai trương tuần này. Tất cả xe đạp tập, máy chạy bộ và các khu tập luyện mà chị thấy đều mới tinh."],["W","Great! I'm considering joining. My office is right around the corner.","Tuyệt quá! Tôi đang cân nhắc đăng ký thành viên. Văn phòng tôi ở ngay gần đây."],["M","Well, here's a brochure with a description of our membership levels. I'm happy to answer any questions.","Vậy thì đây là tờ giới thiệu mô tả các hạng thành viên của chúng tôi. Tôi sẵn lòng trả lời mọi câu hỏi."],["W","Thanks. I do like to swim a few times a week. Do you have a pool?","Cảm ơn anh. Tôi rất thích bơi vài lần một tuần. Ở đây có hồ bơi không?"],["M","We do. Why don't we start by walking around so I can show you all of our facilities?","Có chứ. Sao chúng ta không bắt đầu bằng việc đi một vòng để tôi giới thiệu cho chị tất cả cơ sở vật chất nhỉ?"]],"qs":[{"n":41,"q":"Where does the man work?","qvi":"Người đàn ông làm việc ở đâu?","opts":["At a community park","At a fitness center","At a public beach","At a sports equipment store"],"vi":["Tại một công viên cộng đồng","Tại một trung tâm thể dục","Tại một bãi biển công cộng","Tại một cửa hàng dụng cụ thể thao"],"ans":"B","xp":"Người đàn ông nói: \"we just opened this week. All the exercise bikes, treadmills, and workout stations ... are brand-new\" (xe đạp tập, máy chạy bộ, khu tập) và nói về hạng thành viên, hồ bơi → anh ấy làm ở trung tâm thể dục (fitness center)."},{"n":42,"q":"What is the purpose of the woman's visit?","qvi":"Mục đích chuyến ghé thăm của người phụ nữ là gì?","opts":["She is applying for a job.","She has a complaint.","She needs specific directions.","She is interested in a membership."],"vi":["Cô ấy đang xin việc.","Cô ấy có điều phàn nàn.","Cô ấy cần chỉ đường cụ thể.","Cô ấy quan tâm đến việc đăng ký thành viên."],"ans":"D","xp":"Người phụ nữ nói: \"I'm considering joining.\" (tôi đang cân nhắc tham gia) và người đàn ông đưa tờ giới thiệu 'membership levels' → cô ấy quan tâm đến việc làm thành viên."},{"n":43,"q":"What will the woman most likely do next?","qvi":"Người phụ nữ nhiều khả năng sẽ làm gì tiếp theo?","opts":["Join a team","Go on a tour","Make a phone call","Fill out an application"],"vi":["Gia nhập một đội","Đi tham quan một vòng","Gọi điện thoại","Điền đơn đăng ký"],"ans":"B","xp":"Người đàn ông đề nghị: \"Why don't we start by walking around so I can show you all of our facilities?\" (đi một vòng để tôi giới thiệu cơ sở vật chất) → 'walking around ... show you all of our facilities' = 'Go on a tour'."}],"a":"E24-T04-41-43.mp3"},{"ns":[44,46],"script":[["M","Hello. What brings you into our leasing office today?","Xin chào. Hôm nay chị đến văn phòng cho thuê của chúng tôi có việc gì vậy?"],["W","Hi. I currently live in unit 217, but I'm wondering if there are any larger units available to rent in the building.","Chào anh. Hiện tôi đang sống ở căn 217, nhưng tôi muốn hỏi trong tòa nhà còn căn hộ nào rộng hơn để thuê không."],["M","Let me see. Apartment 410 is quite large, and the lease on it ends this November. It's a thousand per month. Does that interest you?","Để tôi xem. Căn hộ 410 khá rộng, và hợp đồng thuê căn đó sẽ hết hạn vào tháng 11 này. Giá là một nghìn đô mỗi tháng. Chị có quan tâm không?"],["W","I did just get promoted at work recently, so I can afford to spend more. So, that won't be a problem.","Tôi vừa mới được thăng chức ở công ty, nên tôi có thể chi nhiều hơn. Vì vậy giá đó không thành vấn đề."],["M","Great. I'll call the current tenant and we can figure out a time for a viewing.","Tuyệt. Tôi sẽ gọi cho người thuê hiện tại và chúng ta có thể sắp xếp thời gian đi xem nhà."]],"qs":[{"n":44,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["A janitor","A property manager","A carpenter","An interior designer"],"vi":["Nhân viên vệ sinh","Người quản lý bất động sản","Thợ mộc","Nhà thiết kế nội thất"],"ans":"B","xp":"Người đàn ông hỏi: \"What brings you into our leasing office today?\" (chị đến văn phòng cho thuê của chúng tôi có việc gì) và giới thiệu căn hộ cho thuê → anh ấy là người quản lý tòa nhà/bất động sản (property manager)."},{"n":45,"q":"What does the woman say recently happened?","qvi":"Người phụ nữ nói gần đây đã xảy ra chuyện gì?","opts":["She earned a degree.","She won an award.","She got a promotion.","She transferred to a new location."],"vi":["Cô ấy nhận được bằng cấp.","Cô ấy giành được giải thưởng.","Cô ấy được thăng chức.","Cô ấy chuyển đến địa điểm làm việc mới."],"ans":"C","xp":"Người phụ nữ nói: \"I did just get promoted at work recently\" (tôi vừa được thăng chức) → 'get promoted' = 'got a promotion'."},{"n":46,"q":"What will the man do next?","qvi":"Người đàn ông sẽ làm gì tiếp theo?","opts":["Make a phone call","Prepare a contract","Drop off a key","Log some work hours"],"vi":["Gọi điện thoại","Chuẩn bị hợp đồng","Mang chìa khóa đến","Ghi lại giờ làm việc"],"ans":"A","xp":"Người đàn ông nói: \"I'll call the current tenant\" (tôi sẽ gọi cho người thuê hiện tại) → 'call' = 'Make a phone call'."}],"a":"E24-T04-44-46.mp3"},{"ns":[47,49],"script":[["M","Hello, Ms. Bajaj. I'm glad we have a chance to meet today to discuss your business. What's your company's main goal?","Xin chào chị Bajaj. Tôi rất vui vì hôm nay chúng ta có dịp gặp nhau để bàn về công việc kinh doanh của chị. Mục tiêu chính của công ty chị là gì?"],["W","Well, recently, my craft supply store has started receiving a lot of online orders. It's important that I get feedback from those customers about the products that I'm selling.","À, gần đây cửa hàng đồ thủ công của tôi bắt đầu nhận được rất nhiều đơn hàng trực tuyến. Điều quan trọng là tôi cần nhận được phản hồi từ những khách hàng đó về các sản phẩm tôi đang bán."],["M","We can design an online survey for you. It's automatically e-mailed out to your customers a week after their order is delivered. We've had a lot of success getting people to respond to those.","Chúng tôi có thể thiết kế một bảng khảo sát trực tuyến cho chị. Nó sẽ được tự động gửi qua e-mail cho khách hàng một tuần sau khi đơn hàng được giao. Chúng tôi đã rất thành công trong việc khiến mọi người trả lời các khảo sát đó."],["W","That's a great idea. Then perhaps I could offer a future discount to any customer who completes the survey.","Ý tưởng hay đấy. Vậy có lẽ tôi có thể tặng một ưu đãi giảm giá cho lần mua sau cho khách hàng nào hoàn thành khảo sát."]],"qs":[{"n":47,"q":"According to the woman, what has recently happened at her business?","qvi":"Theo người phụ nữ, gần đây điều gì đã xảy ra ở cửa hàng của cô ấy?","opts":["Customers have complained.","Inspections have been conducted.","Online orders have increased.","Shipments have been incomplete."],"vi":["Khách hàng đã phàn nàn.","Đã có các cuộc kiểm tra.","Đơn hàng trực tuyến đã tăng lên.","Các lô hàng bị giao thiếu."],"ans":"C","xp":"Người phụ nữ nói: \"recently, my craft supply store has started receiving a lot of online orders\" (bắt đầu nhận rất nhiều đơn hàng online) → 'receiving a lot of online orders' = 'Online orders have increased'."},{"n":48,"q":"What can the man's company do?","qvi":"Công ty của người đàn ông có thể làm gì?","opts":["Provide safety training","Post demonstration videos","Acquire more warehouse space","Create customer surveys"],"vi":["Cung cấp đào tạo an toàn","Đăng video hướng dẫn","Có thêm không gian nhà kho","Tạo khảo sát khách hàng"],"ans":"D","xp":"Người đàn ông nói: \"We can design an online survey for you.\" (chúng tôi có thể thiết kế khảo sát trực tuyến) → 'design an online survey' = 'Create customer surveys'."},{"n":49,"q":"What does the woman say she could offer her customers?","qvi":"Người phụ nữ nói cô ấy có thể tặng khách hàng điều gì?","opts":["A discount","Expedited shipping","Free product samples","A personal consultation"],"vi":["Giảm giá","Giao hàng nhanh","Sản phẩm mẫu miễn phí","Tư vấn cá nhân"],"ans":"A","xp":"Người phụ nữ nói: \"perhaps I could offer a future discount to any customer who completes the survey\" (tặng giảm giá cho lần sau cho khách làm khảo sát) → chọn 'A discount'."}],"a":"E24-T04-47-49.mp3"},{"ns":[50,52],"script":[["M1","Hello. I'm from District Flower Store, and I have your centerpiece order.","Xin chào. Tôi đến từ cửa hàng hoa District, tôi mang đơn hàng hoa trang trí bàn của quý khách đến."],["M2","Let me get the hotel's event manager here; she's the one that ordered. Yuliya? You have a delivery from District Flower Store at reception.","Để tôi gọi quản lý sự kiện của khách sạn ra đây; cô ấy là người đã đặt hàng. Yuliya ơi? Có hàng giao từ cửa hàng hoa District ở quầy lễ tân này."],["W","Hi! I'm glad you're early. The wedding's this evening, but we're already setting up the ballroom.","Chào anh! Rất vui vì anh đến sớm. Đám cưới diễn ra tối nay, nhưng chúng tôi đang bắt đầu chuẩn bị phòng tiệc rồi."],["M1","I'll need you to acknowledge receipt. Could you sign here? And then, where should I unload your calla lily centerpieces?","Tôi cần chị xác nhận đã nhận hàng. Chị ký vào đây được không? Sau đó tôi nên dỡ những lẵng hoa rum trang trí bàn của chị ở đâu?"],["W","Calla lilies? I ordered lilacs for the wedding centerpieces!","Hoa rum ư? Tôi đã đặt hoa tử đinh hương để trang trí bàn cho đám cưới cơ mà!"],["M1","Oh, I wouldn't know. I just deliver.","Ồ, tôi không rõ đâu. Tôi chỉ là người giao hàng."],["W","Well, let me call your boss. We need this sorted out right away.","Vậy để tôi gọi cho sếp của anh. Chúng tôi cần giải quyết chuyện này ngay lập tức."]],"qs":[{"n":50,"q":"Where most likely are the speakers?","qvi":"Những người nói nhiều khả năng đang ở đâu?","opts":["At a farm","At a landscaping company","At a hotel","At a catering firm"],"vi":["Tại một trang trại","Tại một công ty cảnh quan","Tại một khách sạn","Tại một công ty cung cấp đồ ăn"],"ans":"C","xp":"Người đàn ông thứ hai nói: \"Let me get the hotel's event manager here\" (để tôi gọi quản lý sự kiện của khách sạn) và nhắc đến quầy lễ tân (reception) → họ đang ở khách sạn."},{"n":51,"q":"What type of event is going to take place?","qvi":"Sự kiện gì sắp diễn ra?","opts":["A wedding","A flower exposition","A grand opening","A birthday party"],"vi":["Một đám cưới","Một triển lãm hoa","Một lễ khai trương","Một bữa tiệc sinh nhật"],"ans":"A","xp":"Người phụ nữ nói: \"The wedding's this evening\" (đám cưới diễn ra tối nay) → chọn 'A wedding'."},{"n":52,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Sign a receipt","Adjust a schedule","Add items to an order","Call a supervisor"],"vi":["Ký nhận hóa đơn","Điều chỉnh lịch trình","Thêm món vào đơn hàng","Gọi cho cấp trên"],"ans":"D","xp":"Người phụ nữ nói: \"let me call your boss\" (để tôi gọi cho sếp của anh) → 'boss' = 'supervisor'. (A) sai vì cô ấy chưa ký nhận do giao nhầm hoa."}],"a":"E24-T04-50-52.mp3"},{"ns":[53,55],"script":[["M1","Excuse me, Ms. Campbell. My engineer, Adisa, is still on your roof, but I just wanted to let you know we're almost done with the inspection.","Xin lỗi chị Campbell. Kỹ sư của tôi, Adisa, vẫn đang ở trên mái nhà của chị, nhưng tôi chỉ muốn báo để chị biết là chúng tôi sắp kiểm tra xong rồi."],["W","How does everything look?","Mọi thứ trông thế nào?"],["M1","Oh, here's Adisa now. He can answer that.","Ồ, Adisa đến rồi đây. Anh ấy có thể trả lời câu đó."],["M2","I conducted a thorough inspection. There's no structural damage. All of the support beams are intact, but we'll have to replace some of the shingles that were blown away in the storm.","Tôi đã kiểm tra kỹ lưỡng. Không có hư hại nào về kết cấu. Tất cả các dầm đỡ đều nguyên vẹn, nhưng chúng tôi sẽ phải thay một số tấm lợp bị bão thổi bay."],["W","Well that's a relief. I was worried that I'd need major repairs.","Vậy thì nhẹ cả người. Tôi đã lo là sẽ phải sửa chữa lớn."],["M2","I'm afraid you'll have to close your store while we replace the shingles. But we'll be able to finish in one day.","Tôi e là chị sẽ phải đóng cửa hàng trong lúc chúng tôi thay tấm lợp. Nhưng chúng tôi có thể làm xong trong một ngày."],["M1","Does Tuesday work for you?","Thứ Ba có tiện cho chị không?"],["W","That's fine.","Được đấy."]],"qs":[{"n":53,"q":"What kind of business do the men most likely work for?","qvi":"Hai người đàn ông nhiều khả năng làm việc cho loại hình doanh nghiệp nào?","opts":["A fencing company","A landscaping service","A roofing company","An auto repair shop"],"vi":["Công ty làm hàng rào","Dịch vụ cảnh quan sân vườn","Công ty lợp/sửa mái nhà","Tiệm sửa xe ô tô"],"ans":"C","xp":"Người đàn ông thứ nhất nói: \"My engineer, Adisa, is still on your roof ... we're almost done with the inspection\" (kỹ sư đang trên mái nhà kiểm tra) và sau đó họ sẽ thay tấm lợp (shingles) → công ty lợp mái (roofing company)."},{"n":54,"q":"Why is the woman relieved?","qvi":"Tại sao người phụ nữ thấy nhẹ nhõm?","opts":["Some damage is minor.","A delivery arrived early.","Customer reviews are positive.","The weather forecast is good."],"vi":["Hư hại không nghiêm trọng.","Một lô hàng đến sớm.","Đánh giá của khách hàng tích cực.","Dự báo thời tiết tốt."],"ans":"A","xp":"Kỹ sư nói: \"There's no structural damage ... but we'll have to replace some of the shingles\" (không hư hại kết cấu, chỉ cần thay vài tấm lợp), người phụ nữ đáp \"that's a relief. I was worried that I'd need major repairs\" → hư hại chỉ nhỏ (minor)."},{"n":55,"q":"What will the woman do on Tuesday?","qvi":"Người phụ nữ sẽ làm gì vào thứ Ba?","opts":["Wash her car","Close her store","Take some measurements","Look at some material samples"],"vi":["Rửa xe","Đóng cửa hàng","Đo đạc kích thước","Xem vài mẫu vật liệu"],"ans":"B","xp":"Kỹ sư nói: \"I'm afraid you'll have to close your store while we replace the shingles\", rồi người đàn ông hỏi \"Does Tuesday work for you?\" và cô ấy đồng ý \"That's fine.\" → thứ Ba cô ấy sẽ đóng cửa hàng."}],"a":"E24-T04-53-55.mp3"},{"ns":[56,58],"script":[["M","Hi, Erina. I'm sorry about missing the morning meeting! My commute was horrendous.","Chào Erina. Xin lỗi vì tôi đã lỡ cuộc họp sáng nay! Đường đi làm của tôi thật kinh khủng."],["W","No worries. The meeting notes will be sent out. What happened?","Không sao đâu. Biên bản cuộc họp sẽ được gửi đi. Có chuyện gì vậy?"],["M","The Metro system's renovating some station platforms, and it added an extra half hour to my commute. Trains in both directions are only using one track, and the train's my only option!","Hệ thống tàu điện ngầm đang cải tạo một số sân ga, và việc đó làm thời gian đi làm của tôi tăng thêm nửa tiếng. Tàu cả hai chiều chỉ chạy trên một đường ray, mà tàu điện là lựa chọn duy nhất của tôi!"],["W","Well, there is a rapid-transit bus service.","Ừm, có dịch vụ xe buýt nhanh đấy."],["M","I wasn't aware of that. I'm still new to this city. How do I get more information?","Tôi không biết điều đó. Tôi vẫn còn mới ở thành phố này. Làm sao để tôi có thêm thông tin?"],["W","I'll send you links to their Web site and system map.","Tôi sẽ gửi cho anh đường link trang web và bản đồ tuyến của họ."]],"qs":[{"n":56,"q":"Why does the man apologize?","qvi":"Tại sao người đàn ông xin lỗi?","opts":["He missed a meeting.","He has a poor Internet connection.","He failed to complete an assignment.","He lost his employee badge."],"vi":["Anh ấy đã lỡ một cuộc họp.","Kết nối Internet của anh ấy kém.","Anh ấy không hoàn thành nhiệm vụ.","Anh ấy làm mất thẻ nhân viên."],"ans":"A","xp":"Người đàn ông nói: \"I'm sorry about missing the morning meeting!\" (xin lỗi vì lỡ cuộc họp sáng) → chọn (A)."},{"n":57,"q":"Why does the woman say, \"Well, there is a rapid-transit bus service\"?","qvi":"Tại sao người phụ nữ nói: \"Ừm, có dịch vụ xe buýt nhanh đấy\"?","opts":["To praise improvements to a system","To correct a mistaken assumption","To express dissatisfaction","To justify a decision"],"vi":["Để khen ngợi những cải tiến của một hệ thống","Để sửa lại một suy nghĩ sai","Để bày tỏ sự không hài lòng","Để biện minh cho một quyết định"],"ans":"B","xp":"Câu hỏi hàm ý. Người đàn ông nói: \"the train's my only option!\" (tàu điện là lựa chọn duy nhất). Người phụ nữ đáp có xe buýt nhanh → cô ấy muốn chỉ ra rằng anh ấy nghĩ sai, tàu không phải lựa chọn duy nhất → sửa một giả định sai."},{"n":58,"q":"What will the woman do next?","qvi":"Người phụ nữ sẽ làm gì tiếp theo?","opts":["Download a ticket","Pick up some clients","Activate a key card","Forward some Web-site links"],"vi":["Tải vé xuống","Đón vài khách hàng","Kích hoạt thẻ từ","Chuyển tiếp vài đường link trang web"],"ans":"D","xp":"Người phụ nữ nói: \"I'll send you links to their Web site and system map.\" (tôi sẽ gửi anh link trang web) → 'send' = 'Forward', 'links to their Web site' = 'Web-site links'."}],"a":"E24-T04-56-58.mp3"},{"ns":[59,61],"script":[["M","Hello, Silvia. Good to see you again. My consultancy firm has been working hard to help you grow your clothing company.","Chào Silvia. Rất vui được gặp lại chị. Công ty tư vấn của tôi đã làm việc chăm chỉ để giúp chị phát triển công ty thời trang của mình."],["W","Thanks. I never expected so much attention for my clothing designs, but I'm so pleased with the reactions.","Cảm ơn anh. Tôi chưa bao giờ nghĩ các thiết kế quần áo của mình lại được chú ý nhiều như vậy, nhưng tôi rất hài lòng với phản hồi."],["M","OK. What do you think about approaching Regents department stores?","Được rồi. Chị nghĩ sao về việc tiếp cận chuỗi cửa hàng bách hóa Regents?"],["W","They usually market to a younger clientele.","Họ thường hướng đến nhóm khách hàng trẻ tuổi hơn."],["M","I see. Let me get you a list of other stores we also had in mind.","Tôi hiểu rồi. Để tôi gửi chị danh sách các cửa hàng khác mà chúng tôi cũng đã tính đến."]],"qs":[{"n":59,"q":"Who is the woman?","qvi":"Người phụ nữ là ai?","opts":["An architect","A clothing designer","A construction manager","A department store director"],"vi":["Kiến trúc sư","Nhà thiết kế thời trang","Quản lý công trình xây dựng","Giám đốc cửa hàng bách hóa"],"ans":"B","xp":"Người đàn ông nói công ty anh giúp \"grow your clothing company\" và người phụ nữ nói \"I never expected so much attention for my clothing designs\" (các thiết kế quần áo của tôi) → cô ấy là nhà thiết kế thời trang."},{"n":60,"q":"Why does the woman say, \"They usually market to a younger clientele\"?","qvi":"Tại sao người phụ nữ nói: \"Họ thường hướng đến nhóm khách hàng trẻ tuổi hơn\"?","opts":["To reject a suggestion","To justify a decision","To express disappointment","To ask for clarification"],"vi":["Để từ chối một đề xuất","Để biện minh cho một quyết định","Để bày tỏ sự thất vọng","Để yêu cầu làm rõ"],"ans":"A","xp":"Câu hỏi hàm ý. Người đàn ông đề xuất: \"What do you think about approaching Regents department stores?\" Cô ấy đáp họ hướng đến khách trẻ hơn → ngầm ý cửa hàng đó không hợp với sản phẩm của cô → từ chối đề xuất. Người đàn ông hiểu ý và đưa danh sách cửa hàng khác."},{"n":61,"q":"What does the man say he will give the woman?","qvi":"Người đàn ông nói sẽ đưa cho người phụ nữ cái gì?","opts":["An area map","A list of businesses","Some photographs","Some measurements"],"vi":["Bản đồ khu vực","Danh sách các doanh nghiệp","Vài tấm ảnh","Vài số đo"],"ans":"B","xp":"Người đàn ông nói: \"Let me get you a list of other stores we also had in mind.\" → 'a list of other stores' = 'A list of businesses'."}],"a":"E24-T04-59-61.mp3"},{"ns":[62,64],"script":[["W","Luis, I noticed something while I was directing yesterday's rehearsal. I had a problem while I was trying to give some directions to the actors during act three. I wanted to ask you about it since you're in charge of lighting.","Luis này, tôi nhận thấy một chuyện khi đang chỉ đạo buổi tập hôm qua. Tôi gặp vấn đề khi cố hướng dẫn các diễn viên trong màn ba. Tôi muốn hỏi anh vì anh phụ trách ánh sáng."],["M","Sure. What is it?","Được chứ. Chuyện gì vậy?"],["W","One of the footlights at the front of the stage was flickering, which was distracting. It made it hard to see the actors' faces and costumes. Can you do something to fix it?","Một trong những đèn rọi chân ở phía trước sân khấu cứ nhấp nháy, rất gây mất tập trung. Nó khiến khó nhìn rõ khuôn mặt và trang phục của diễn viên. Anh có thể sửa nó được không?"],["M","Actually, I've already ordered a replacement. It should be here tomorrow.","Thật ra tôi đã đặt một cái thay thế rồi. Chắc ngày mai sẽ tới."],["W","Great. Thanks. I can't believe opening night is next week. Everyone has put so much work into the show—it'll be great to have an audience.","Tuyệt. Cảm ơn anh. Thật không thể tin là tuần sau đã đến đêm công diễn đầu tiên. Mọi người đã bỏ rất nhiều công sức cho vở diễn — có khán giả thì sẽ tuyệt lắm."]],"qs":[{"n":62,"q":"Look at the graphic. Who is the woman?","qvi":"Nhìn vào hình. Người phụ nữ là ai?","opts":["Liliana Flores","Svetlana Popova","Lauren Campbell","So-Jin Park"],"vi":["Liliana Flores","Svetlana Popova","Lauren Campbell","So-Jin Park"],"ans":"B","xp":"Người phụ nữ nói: \"I noticed something while I was directing yesterday's rehearsal\" (khi tôi đang chỉ đạo/đạo diễn buổi tập) → cô ấy là đạo diễn (Director). Theo bảng, Director là Svetlana Popova → chọn (B)."},{"n":63,"q":"What problem do the speakers discuss?","qvi":"Những người nói thảo luận vấn đề gì?","opts":["Some equipment is not working.","Some costumes are not ready.","Some music is distracting.","An actor is late."],"vi":["Một thiết bị không hoạt động tốt.","Một số trang phục chưa sẵn sàng.","Một số bản nhạc gây mất tập trung.","Một diễn viên đến muộn."],"ans":"A","xp":"Người phụ nữ nói: \"One of the footlights at the front of the stage was flickering\" (một đèn sân khấu bị nhấp nháy) → đèn là thiết bị bị lỗi → 'Some equipment is not working'."},{"n":64,"q":"What will happen next week?","qvi":"Điều gì sẽ diễn ra vào tuần sau?","opts":["A playwright will attend a show.","Publicity photos will be taken.","A play will open.","A dress rehearsal will be held."],"vi":["Một nhà viết kịch sẽ đến xem buổi diễn.","Ảnh quảng bá sẽ được chụp.","Một vở kịch sẽ ra mắt.","Một buổi tổng duyệt sẽ được tổ chức."],"ans":"C","xp":"Người phụ nữ nói: \"I can't believe opening night is next week.\" (tuần sau là đêm công diễn đầu tiên) → vở kịch ra mắt → 'A play will open'."}],"a":"E24-T04-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Hey, Hiroko. I got the e-mail invite to the company retreat. I'm surprised that it's in June this year, instead of September.","Này Hiroko. Tôi đã nhận được e-mail mời tham gia chuyến dã ngoại của công ty. Tôi ngạc nhiên là năm nay nó được tổ chức vào tháng Sáu thay vì tháng Chín."],["W","Yeah, we changed the dates so we could try out this venue. I toured it last month and was really impressed. The rooms especially are so comfortable. There weren't any openings in September, though.","Ừ, chúng tôi đã đổi ngày để có thể thử địa điểm này. Tháng trước tôi đã đi xem qua và thực sự ấn tượng. Đặc biệt là các phòng rất thoải mái. Nhưng vào tháng Chín thì họ không còn chỗ trống."],["M","I'm sure it'll be worth the change. Your team in Human Resources plans great events.","Tôi chắc là sự thay đổi này sẽ đáng giá. Nhóm Nhân sự của chị luôn lên kế hoạch cho những sự kiện tuyệt vời."],["W","Here, I just pulled up their Web site. Take a look. Staff can choose one of these activities on the second day of the retreat.","Đây, tôi vừa mở trang web của họ. Anh xem đi. Nhân viên có thể chọn một trong những hoạt động này vào ngày thứ hai của chuyến đi."],["M","I've never been kayaking. This looks like a good chance to try it.","Tôi chưa bao giờ chèo thuyền kayak. Đây có vẻ là cơ hội tốt để thử."]],"qs":[{"n":65,"q":"Why is the man surprised?","qvi":"Tại sao người đàn ông ngạc nhiên?","opts":["A new vacation policy was announced.","A group is larger than expected.","A price has increased.","A date has been changed."],"vi":["Một chính sách nghỉ phép mới được công bố.","Một nhóm đông hơn dự kiến.","Giá đã tăng.","Một ngày đã bị thay đổi."],"ans":"D","xp":"Người đàn ông nói: \"I'm surprised that it's in June this year, instead of September.\" (ngạc nhiên vì năm nay vào tháng Sáu thay vì tháng Chín) → thời gian đã thay đổi → 'A date has been changed'."},{"n":66,"q":"What does the woman like about a venue?","qvi":"Người phụ nữ thích điều gì ở địa điểm?","opts":["The comfortable rooms","The food selection","The views","The fitness center"],"vi":["Các phòng thoải mái","Các lựa chọn món ăn","Quang cảnh","Phòng tập thể dục"],"ans":"A","xp":"Người phụ nữ nói: \"I toured it last month and was really impressed. The rooms especially are so comfortable.\" (đặc biệt các phòng rất thoải mái) → chọn (A)."},{"n":67,"q":"Look at the graphic. Who will lead the activity the man is interested in?","qvi":"Nhìn vào hình. Ai sẽ dẫn dắt hoạt động mà người đàn ông quan tâm?","opts":["Ketan Bora","Beatriz Romero","Arnaud Fournier","Brandon Murray"],"vi":["Ketan Bora","Beatriz Romero","Arnaud Fournier","Brandon Murray"],"ans":"A","xp":"Người đàn ông nói: \"I've never been kayaking. This looks like a good chance to try it.\" → anh ấy quan tâm đến chèo kayak. Theo trang web, 'Kayaking led by Ketan Bora' → chọn (A)."}],"a":"E24-T04-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Hi. You must be with the camera crew. I'm Hector, head archaeologist here at the Arnaud Castle dig site.","Xin chào. Chắc chị thuộc đoàn quay phim. Tôi là Hector, trưởng nhóm khảo cổ tại khu khai quật lâu đài Arnaud."],["W","Nice to meet you. I'm Ling. Since it's our first day of filming for our TV documentary special, we're mainly going to capture general footage of your team at work.","Rất vui được gặp anh. Tôi là Ling. Vì hôm nay là ngày quay đầu tiên cho chương trình phim tài liệu truyền hình đặc biệt của chúng tôi, chúng tôi chủ yếu sẽ quay những cảnh tổng quát về đội của anh khi đang làm việc."],["M","Great! We're working in quadrant two today. We've been finding lots of pottery, so you may capture us unearthing more.","Tuyệt! Hôm nay chúng tôi làm việc ở khu vực thứ hai. Chúng tôi đã tìm thấy rất nhiều đồ gốm, nên có thể chị sẽ quay được cảnh chúng tôi đào thêm."],["W","I see. This excavation has been a lengthy process, right?","Tôi hiểu rồi. Cuộc khai quật này đã kéo dài khá lâu, phải không?"],["M","It has. We'd actually hoped to be further along, but there've been lots of thunderstorms lately, which have slowed things down.","Đúng vậy. Thật ra chúng tôi đã hy vọng tiến độ nhanh hơn, nhưng gần đây có nhiều cơn giông bão nên công việc bị chậm lại."]],"qs":[{"n":68,"q":"What is the conversation mostly about?","qvi":"Cuộc hội thoại chủ yếu nói về điều gì?","opts":["Organizing an exhibit","Arranging a public tour","Filming a documentary","Requesting financial support"],"vi":["Tổ chức một cuộc triển lãm","Sắp xếp một chuyến tham quan công cộng","Quay một bộ phim tài liệu","Xin hỗ trợ tài chính"],"ans":"C","xp":"Người đàn ông nói: \"You must be with the camera crew\" và người phụ nữ nói: \"it's our first day of filming for our TV documentary special\" (ngày quay đầu tiên cho phim tài liệu) → chọn (C)."},{"n":69,"q":"Look at the graphic. Which part of the castle is being excavated today?","qvi":"Nhìn vào hình. Phần nào của lâu đài đang được khai quật hôm nay?","opts":["The garden","The kitchen","The tower","The great hall"],"vi":["Khu vườn","Nhà bếp","Tòa tháp","Đại sảnh"],"ans":"B","xp":"Người đàn ông nói: \"We're working in quadrant two today.\" (hôm nay làm ở khu vực 2). Theo bản đồ, Quadrant 2 là Kitchen (nhà bếp) → chọn (B)."},{"n":70,"q":"According to the man, why has some work been delayed?","qvi":"Theo người đàn ông, tại sao một số công việc bị chậm trễ?","opts":["An archaeological team is very small.","Weather conditions have been poor.","A source of funding was unavailable.","New volunteers required special training."],"vi":["Đội khảo cổ rất nhỏ.","Điều kiện thời tiết xấu.","Không có nguồn tài trợ.","Tình nguyện viên mới cần được đào tạo đặc biệt."],"ans":"B","xp":"Người đàn ông nói: \"there've been lots of thunderstorms lately, which have slowed things down\" (gần đây nhiều giông bão làm chậm công việc) → 'lots of thunderstorms' = 'Weather conditions have been poor'."}],"a":"E24-T04-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Hello. You've reached Imperial Electric and Gas, the number one power company in the Northeast region. Please hold for the next available representative. If you're calling about reported electrical outages in Cedar Springs, rest assured that technicians are on-site now and services will be fully restored this afternoon. Or if you've recently moved and are calling to either start or stop services, please visit our Web site to fill out a form to have a work order completed. Thank you.","Xin chào. Quý khách đã gọi đến Imperial Electric and Gas, công ty điện lực số một ở khu vực Đông Bắc. Vui lòng giữ máy để chờ nhân viên tư vấn tiếp theo. Nếu quý khách gọi về sự cố mất điện đã được báo cáo ở Cedar Springs, xin hãy yên tâm rằng các kỹ thuật viên hiện đang có mặt tại hiện trường và dịch vụ sẽ được khôi phục hoàn toàn vào chiều nay. Hoặc nếu quý khách vừa chuyển nhà và gọi để bắt đầu hoặc ngừng sử dụng dịch vụ, vui lòng truy cập trang web của chúng tôi để điền vào biểu mẫu và hoàn tất yêu cầu công việc. Xin cảm ơn."]],"qs":[{"n":71,"q":"What kind of business recorded the message?","qvi":"Loại hình doanh nghiệp nào đã ghi âm tin nhắn này?","opts":["A city planning office","A cybersecurity firm","A utility company","An electronics repair shop"],"vi":["Văn phòng quy hoạch thành phố","Công ty an ninh mạng","Công ty dịch vụ tiện ích (điện, nước, gas)","Tiệm sửa đồ điện tử"],"ans":"C","xp":"Lời nhắn mở đầu: \"You've reached Imperial Electric and Gas, the number one power company in the Northeast region\" → công ty điện và gas = 'utility company' (công ty dịch vụ tiện ích công cộng)."},{"n":72,"q":"What does the speaker say will happen this afternoon?","qvi":"Người nói cho biết điều gì sẽ xảy ra vào chiều nay?","opts":["A problem will be resolved.","A shipment will be delivered.","Some software will be updated.","Some refreshments will be offered."],"vi":["Một vấn đề sẽ được giải quyết.","Một lô hàng sẽ được giao.","Một phần mềm sẽ được cập nhật.","Đồ ăn nhẹ sẽ được phục vụ."],"ans":"A","xp":"Người nói: \"technicians are on-site now and services will be fully restored this afternoon\" (dịch vụ sẽ được khôi phục hoàn toàn vào chiều nay) → sự cố mất điện sẽ được khắc phục → 'A problem will be resolved'."},{"n":73,"q":"What does the speaker say is available on a Web site?","qvi":"Người nói cho biết có gì trên trang web?","opts":["Customer reviews","Work order forms","Business hours","Product manuals"],"vi":["Đánh giá của khách hàng","Mẫu đơn yêu cầu công việc","Giờ làm việc","Sách hướng dẫn sản phẩm"],"ans":"B","xp":"Người nói: \"please visit our Web site to fill out a form to have a work order completed\" (vào trang web điền biểu mẫu để hoàn tất yêu cầu công việc) → trên web có 'Work order forms'."}],"a":"E24-T04-71-73.mp3"},{"ns":[74,76],"script":[["","This weekend, we'll be installing new security software on our internal servers. This is a little more involved than a routine update—we need to have an extra layer of protection on our customers' personal data. So, we're all being asked to help prepare for this event. Before we leave the office on Friday, we'll need to shut down our computers to enable the patch. Marta Fuentes is here to explain how we'll finish the installation on our devices when we come in on Monday.","Cuối tuần này, chúng ta sẽ cài đặt phần mềm bảo mật mới trên các máy chủ nội bộ. Việc này phức tạp hơn một lần cập nhật thông thường một chút — chúng ta cần thêm một lớp bảo vệ cho dữ liệu cá nhân của khách hàng. Vì vậy, tất cả chúng ta đều được yêu cầu giúp chuẩn bị cho việc này. Trước khi rời văn phòng vào thứ Sáu, chúng ta cần tắt máy tính để bản vá có thể được cài đặt. Chị Marta Fuentes có mặt ở đây để giải thích cách chúng ta hoàn tất việc cài đặt trên thiết bị của mình khi đi làm lại vào thứ Hai."]],"qs":[{"n":74,"q":"According to the speaker, why is a change being made?","qvi":"Theo người nói, tại sao có sự thay đổi này?","opts":["To keep track of expenses","To help a business expand","To improve security","To attract job applicants"],"vi":["Để theo dõi chi phí","Để giúp doanh nghiệp mở rộng","Để tăng cường bảo mật","Để thu hút người xin việc"],"ans":"C","xp":"Người nói: \"we'll be installing new security software\" và \"we need to have an extra layer of protection on our customers' personal data\" (cần thêm một lớp bảo vệ dữ liệu khách hàng) → mục đích là 'To improve security'."},{"n":75,"q":"What are the listeners asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Shut down their computers","Reduce their expenses","Consult with their department managers","Create an equipment inventory"],"vi":["Tắt máy tính","Cắt giảm chi phí","Hỏi ý kiến trưởng bộ phận","Lập danh sách kiểm kê thiết bị"],"ans":"A","xp":"Người nói: \"Before we leave the office on Friday, we'll need to shut down our computers to enable the patch.\" (trước khi về thứ Sáu cần tắt máy tính) → chọn (A)."},{"n":76,"q":"What department does Marta Fuentes most likely work in?","qvi":"Marta Fuentes nhiều khả năng làm ở bộ phận nào?","opts":["Legal","Marketing","Human Resources","Information Technology"],"vi":["Pháp chế","Tiếp thị","Nhân sự","Công nghệ thông tin"],"ans":"D","xp":"Người nói: \"Marta Fuentes is here to explain how we'll finish the installation on our devices\" (giải thích cách hoàn tất cài đặt phần mềm trên thiết bị) → cô ấy làm việc về phần mềm, máy tính → bộ phận Công nghệ thông tin (IT)."}],"a":"E24-T04-74-76.mp3"},{"ns":[77,79],"script":[["","Let me remind everyone that starting on Monday, the main entrance to the office building will be inaccessible while the road is being widened and repaved. This also means that our usual parking lot won't be available. But don't worry—there's plenty of space in the parking garage next to the Jay Building. For your convenience, the company will be providing a van service that will run every fifteen minutes until the project is completed. The van will operate between seven and nine A.M., and then again between four and six P.M. We'll be posting project updates on our Web site, so be sure to check it regularly.","Tôi xin nhắc mọi người rằng bắt đầu từ thứ Hai, lối vào chính của tòa nhà văn phòng sẽ không thể sử dụng trong thời gian con đường được mở rộng và trải nhựa lại. Điều này cũng có nghĩa là bãi đỗ xe thường ngày của chúng ta sẽ không dùng được. Nhưng đừng lo — nhà để xe cạnh tòa nhà Jay còn rất nhiều chỗ. Để thuận tiện cho mọi người, công ty sẽ cung cấp dịch vụ xe đưa đón chạy 15 phút một chuyến cho đến khi dự án hoàn thành. Xe sẽ hoạt động từ 7 đến 9 giờ sáng, và sau đó từ 4 đến 6 giờ chiều. Chúng tôi sẽ đăng thông tin cập nhật về dự án trên trang web, vì vậy hãy nhớ kiểm tra thường xuyên."]],"qs":[{"n":77,"q":"According to the speaker, what will begin on Monday?","qvi":"Theo người nói, điều gì sẽ bắt đầu vào thứ Hai?","opts":["A seasonal internship program","Road construction","Landscaping maintenance","An equipment upgrade"],"vi":["Một chương trình thực tập theo mùa","Việc thi công đường","Việc bảo dưỡng cảnh quan","Việc nâng cấp thiết bị"],"ans":"B","xp":"Người nói: \"starting on Monday, the main entrance ... will be inaccessible while the road is being widened and repaved\" (con đường được mở rộng và trải nhựa lại) → 'Road construction'."},{"n":78,"q":"What will the company provide for the listeners?","qvi":"Công ty sẽ cung cấp gì cho người nghe?","opts":["Free lunch","New identification badges","Parking passes","Transportation"],"vi":["Bữa trưa miễn phí","Thẻ nhận dạng mới","Thẻ đỗ xe","Phương tiện đưa đón"],"ans":"D","xp":"Người nói: \"the company will be providing a van service that will run every fifteen minutes\" (công ty cung cấp dịch vụ xe van đưa đón) → 'van service' = 'Transportation'."},{"n":79,"q":"Why should the listeners visit a Web site?","qvi":"Tại sao người nghe nên truy cập trang web?","opts":["To download a map","To post feedback","To fill out a registration form","To read project updates"],"vi":["Để tải bản đồ","Để đăng ý kiến phản hồi","Để điền mẫu đăng ký","Để đọc thông tin cập nhật về dự án"],"ans":"D","xp":"Người nói: \"We'll be posting project updates on our Web site, so be sure to check it regularly.\" (sẽ đăng cập nhật dự án trên web, hãy kiểm tra thường xuyên) → 'check' = 'read' → chọn (D)."}],"a":"E24-T04-77-79.mp3"},{"ns":[80,82],"script":[["","Hi, Asako. I'm following up about the hotel you asked me to book for our client visiting from India next month. You wanted to reserve a room for her at the Maple Lodge, but it's fully booked that week. So I've been looking at other hotels in the area, and there is one on Jefferson Avenue. It's a little farther from our office, but it looks like a nice place. They also have a complimentary shuttle bus that can take our guest back and forth from our office. Call me and let me know what you think.","Chào Asako. Tôi gọi để báo thêm về khách sạn mà chị nhờ tôi đặt cho vị khách hàng từ Ấn Độ đến thăm vào tháng sau. Chị muốn đặt phòng cho cô ấy ở Maple Lodge, nhưng tuần đó họ đã kín phòng. Vì vậy tôi đã tìm các khách sạn khác trong khu vực, và có một khách sạn trên đại lộ Jefferson. Nó hơi xa văn phòng chúng ta một chút, nhưng trông có vẻ là một nơi tốt. Họ còn có xe buýt đưa đón miễn phí có thể chở khách của chúng ta đi về giữa khách sạn và văn phòng. Hãy gọi cho tôi và cho tôi biết chị nghĩ sao nhé."]],"qs":[{"n":80,"q":"What is the speaker preparing for?","qvi":"Người nói đang chuẩn bị cho việc gì?","opts":["A client visit","A branch opening","A job fair","An equipment upgrade"],"vi":["Chuyến thăm của khách hàng","Việc khai trương chi nhánh","Hội chợ việc làm","Việc nâng cấp thiết bị"],"ans":"A","xp":"Người nói: \"the hotel you asked me to book for our client visiting from India next month\" (khách sạn cho khách hàng từ Ấn Độ đến thăm tháng sau) → chuẩn bị cho 'A client visit'."},{"n":81,"q":"Why does the speaker say, \"there is one on Jefferson Avenue\"?","qvi":"Tại sao người nói nói: \"có một khách sạn trên đại lộ Jefferson\"?","opts":["To express surprise","To correct some information","To complain about a decision","To recommend an alternative"],"vi":["Để bày tỏ sự ngạc nhiên","Để sửa lại thông tin","Để phàn nàn về một quyết định","Để đề xuất một phương án thay thế"],"ans":"D","xp":"Câu hỏi hàm ý. Trước đó người nói cho biết Maple Lodge \"is fully booked that week\" (đã kín phòng) nên \"I've been looking at other hotels in the area\" → nhắc đến khách sạn trên đại lộ Jefferson là để đề xuất một lựa chọn thay thế."},{"n":82,"q":"What additional service is mentioned?","qvi":"Dịch vụ bổ sung nào được nhắc đến?","opts":["A catered meal","A shuttle bus","Technical support","Secure storage"],"vi":["Bữa ăn được phục vụ sẵn","Xe buýt đưa đón","Hỗ trợ kỹ thuật","Kho lưu trữ an toàn"],"ans":"B","xp":"Người nói: \"They also have a complimentary shuttle bus that can take our guest back and forth from our office.\" (họ còn có xe buýt đưa đón miễn phí) → chọn 'A shuttle bus'."}],"a":"E24-T04-80-82.mp3"},{"ns":[83,85],"script":[["","I'd like to start by giving everyone an update on our latest project. As you know, in order to stay on top as a leading shipping company, we need to continually make changes to meet our customers' expectations. Since our customers prefer doing almost everything digitally, we're going to introduce a new delivery tracking service. By using a smartphone application, customers will be able to see where their package is in real time. Of course, implementing this will be a major project for us and will take place over the coming year. So next month, we'll begin working with developers from XKP Software on creating this tracking service.","Tôi muốn bắt đầu bằng việc cập nhật cho mọi người về dự án mới nhất của chúng ta. Như mọi người đã biết, để giữ vị trí dẫn đầu với tư cách là một công ty vận chuyển hàng đầu, chúng ta cần liên tục thay đổi để đáp ứng kỳ vọng của khách hàng. Vì khách hàng của chúng ta thích làm hầu hết mọi việc bằng công nghệ số, chúng ta sẽ ra mắt một dịch vụ theo dõi giao hàng mới. Bằng cách sử dụng ứng dụng trên điện thoại thông minh, khách hàng sẽ có thể xem gói hàng của mình đang ở đâu theo thời gian thực. Tất nhiên, việc triển khai sẽ là một dự án lớn đối với chúng ta và sẽ diễn ra trong năm tới. Vì vậy, tháng sau chúng ta sẽ bắt đầu làm việc với các nhà phát triển từ XKP Software để xây dựng dịch vụ theo dõi này."]],"qs":[{"n":83,"q":"According to the speaker, why are some changes needed?","qvi":"Theo người nói, tại sao cần một số thay đổi?","opts":["To retain employees","To attract investors","To satisfy customers","To increase productivity"],"vi":["Để giữ chân nhân viên","Để thu hút nhà đầu tư","Để làm hài lòng khách hàng","Để tăng năng suất"],"ans":"C","xp":"Người nói: \"we need to continually make changes to meet our customers' expectations\" (cần liên tục thay đổi để đáp ứng kỳ vọng của khách hàng) → 'meet our customers' expectations' = 'satisfy customers'."},{"n":84,"q":"What additional service does the company plan to offer?","qvi":"Công ty dự định cung cấp dịch vụ bổ sung nào?","opts":["Free product returns","Expedited bulk shipping","Pickup at self-service kiosks","Real-time package tracking"],"vi":["Trả hàng miễn phí","Vận chuyển số lượng lớn hỏa tốc","Nhận hàng tại ki-ốt tự phục vụ","Theo dõi gói hàng theo thời gian thực"],"ans":"D","xp":"Người nói: \"we're going to introduce a new delivery tracking service ... customers will be able to see where their package is in real time\" (xem gói hàng ở đâu theo thời gian thực) → 'Real-time package tracking'."},{"n":85,"q":"According to the speaker, what will begin next month?","qvi":"Theo người nói, điều gì sẽ bắt đầu vào tháng sau?","opts":["A workshop series","A new corporate policy","A land development project","A business collaboration"],"vi":["Một chuỗi hội thảo","Một chính sách mới của công ty","Một dự án phát triển đất đai","Một sự hợp tác kinh doanh"],"ans":"D","xp":"Người nói: \"next month, we'll begin working with developers from XKP Software on creating this tracking service\" (tháng sau bắt đầu làm việc với các nhà phát triển của XKP Software) → hợp tác với công ty khác = 'A business collaboration'."}],"a":"E24-T04-83-85.mp3"},{"ns":[86,88],"script":[["","I'm so happy we got the exclusive video footage of the mayor's response today. We were able to beat the other networks in getting that interview to the public! I wanted to give you all a heads-up that next month we'll be providing a behind-the-scenes tour for students who are exploring our field as a potential career path. They'll see things like the assignment coordination desk, our studios, and the control room. I'm looking for a few volunteers who can spare an hour of their time to do this. Please e-mail me if you're interested.","Tôi rất vui vì hôm nay chúng ta có được đoạn video độc quyền về phản hồi của thị trưởng. Chúng ta đã vượt qua các đài khác trong việc đưa cuộc phỏng vấn đó đến công chúng! Tôi muốn báo trước với mọi người rằng tháng sau chúng ta sẽ tổ chức một chuyến tham quan hậu trường cho các sinh viên đang tìm hiểu lĩnh vực của chúng ta như một con đường sự nghiệp tiềm năng. Các em sẽ được xem những nơi như bàn điều phối nhiệm vụ, các phòng thu và phòng điều khiển. Tôi đang tìm vài tình nguyện viên có thể dành ra một giờ để làm việc này. Nếu quan tâm, vui lòng gửi e-mail cho tôi."]],"qs":[{"n":86,"q":"What industry does the speaker most likely work in?","qvi":"Người nói nhiều khả năng làm việc trong ngành nào?","opts":["Civil service","Hospitality","Media","Architecture"],"vi":["Công vụ nhà nước","Khách sạn - nhà hàng","Truyền thông","Kiến trúc"],"ans":"C","xp":"Người nói nhắc đến \"exclusive video footage\" (đoạn video độc quyền), \"We were able to beat the other networks in getting that interview to the public\" (vượt các đài khác) và studios, control room → làm trong ngành truyền thông (Media)."},{"n":87,"q":"What is planned for next month?","qvi":"Điều gì được lên kế hoạch cho tháng sau?","opts":["A retirement luncheon","An employee-performance review","A computer-system upgrade","A tour of a facility"],"vi":["Bữa trưa mừng nghỉ hưu","Đánh giá hiệu suất nhân viên","Nâng cấp hệ thống máy tính","Chuyến tham quan cơ sở"],"ans":"D","xp":"Người nói: \"next month we'll be providing a behind-the-scenes tour for students\" (tháng sau tổ chức tham quan hậu trường cho sinh viên) → 'behind-the-scenes tour' = 'A tour of a facility'."},{"n":88,"q":"Who should send the speaker an e-mail?","qvi":"Ai nên gửi e-mail cho người nói?","opts":["Those going on vacation","Those willing to volunteer","Those wishing to provide feedback","Those presenting at a conference"],"vi":["Những người sắp đi nghỉ","Những người sẵn lòng tình nguyện","Những người muốn góp ý","Những người thuyết trình tại hội nghị"],"ans":"B","xp":"Người nói: \"I'm looking for a few volunteers who can spare an hour of their time to do this. Please e-mail me if you're interested.\" → người muốn làm tình nguyện viên hãy gửi e-mail → chọn (B)."}],"a":"E24-T04-86-88.mp3"},{"ns":[89,91],"script":[["","Congratulations on a successful third quarter, everyone! You've all done such a great job selling our ovens and refrigerators that we've already exceeded our sales expectations for the year! To celebrate, we'd like to invite the sales team to join us for a company dinner. The dinner will be held on Thursday, December twentieth at the Canterbury Restaurant. You might want to carpool or take public transportation to the event—the restaurant is near the stadium and there's a sports event that night.","Chúc mừng mọi người đã có một quý ba thành công! Tất cả các bạn đã bán lò nướng và tủ lạnh của chúng ta xuất sắc đến mức chúng ta đã vượt chỉ tiêu doanh số của cả năm! Để ăn mừng, chúng tôi muốn mời đội bán hàng tham dự bữa tối của công ty. Bữa tối sẽ được tổ chức vào thứ Năm, ngày 20 tháng 12, tại nhà hàng Canterbury. Các bạn có thể nên đi chung xe hoặc dùng phương tiện công cộng đến sự kiện — nhà hàng ở gần sân vận động và tối hôm đó có một sự kiện thể thao."]],"qs":[{"n":89,"q":"What does the speaker's company most likely sell?","qvi":"Công ty của người nói nhiều khả năng bán gì?","opts":["Beauty supplies","Kitchen appliances","Books","Sporting goods"],"vi":["Đồ làm đẹp","Thiết bị nhà bếp","Sách","Đồ thể thao"],"ans":"B","xp":"Người nói: \"You've all done such a great job selling our ovens and refrigerators\" (bán lò nướng và tủ lạnh của chúng ta) → 'ovens and refrigerators' = 'Kitchen appliances'."},{"n":90,"q":"What event does the speaker invite the listeners to?","qvi":"Người nói mời người nghe đến sự kiện nào?","opts":["A sales workshop","A product demonstration","A celebratory dinner","A concert"],"vi":["Hội thảo bán hàng","Buổi trình diễn sản phẩm","Bữa tối ăn mừng","Buổi hòa nhạc"],"ans":"C","xp":"Người nói: \"To celebrate, we'd like to invite the sales team to join us for a company dinner.\" (để ăn mừng, mời đội bán hàng dự bữa tối) → 'A celebratory dinner'."},{"n":91,"q":"What does the speaker mean when he says, \"there's a sports event that night\"?","qvi":"Người nói có ý gì khi nói: \"tối hôm đó có một sự kiện thể thao\"?","opts":["The office will be closed.","Parking will be limited.","A meeting will be rescheduled.","The listeners should buy some tickets."],"vi":["Văn phòng sẽ đóng cửa.","Chỗ đỗ xe sẽ bị hạn chế.","Một cuộc họp sẽ được dời lịch.","Người nghe nên mua vé."],"ans":"B","xp":"Câu hỏi hàm ý. Người nói khuyên: \"You might want to carpool or take public transportation to the event—the restaurant is near the stadium\" (nên đi chung xe hoặc đi phương tiện công cộng, nhà hàng gần sân vận động) → tối đó có sự kiện thể thao nên sẽ khó tìm chỗ đỗ xe."}],"a":"E24-T04-89-91.mp3"},{"ns":[92,94],"script":[["","I hope you've enjoyed this tour of historic homes in Salona City. I founded this tour company five years ago, and I'm happy to announce that next month my company's expanding its offerings. We're launching a new walking tour that will focus on the various murals and statues located throughout the city center. We know tourists like you often visit the exhibitions at our art museum, but art isn't only inside the walls of a museum. Here are some brochures with information, including the times and prices.","Tôi hy vọng các bạn đã thích chuyến tham quan những ngôi nhà cổ ở thành phố Salona. Tôi đã thành lập công ty du lịch này năm năm trước, và tôi rất vui được thông báo rằng tháng sau công ty tôi sẽ mở rộng các dịch vụ. Chúng tôi sẽ ra mắt một tour đi bộ mới tập trung vào những bức tranh tường và tượng nằm khắp trung tâm thành phố. Chúng tôi biết những du khách như các bạn thường đến xem triển lãm ở bảo tàng nghệ thuật, nhưng nghệ thuật không chỉ nằm trong bốn bức tường của bảo tàng. Đây là một vài tờ giới thiệu có thông tin, bao gồm cả thời gian và giá cả."]],"qs":[{"n":92,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["An artist","A business owner","A local journalist","A government official"],"vi":["Một nghệ sĩ","Một chủ doanh nghiệp","Một nhà báo địa phương","Một quan chức chính phủ"],"ans":"B","xp":"Người nói: \"I founded this tour company five years ago\" (tôi đã thành lập công ty du lịch này) → cô ấy là chủ doanh nghiệp (business owner)."},{"n":93,"q":"Why does the speaker say, \"art isn't only inside the walls of a museum\"?","qvi":"Tại sao người nói nói: \"nghệ thuật không chỉ nằm trong bốn bức tường của bảo tàng\"?","opts":["To apologize for an exhibit closure","To disagree with an online review","To motivate the listeners to take another tour","To recommend a building renovation"],"vi":["Để xin lỗi vì triển lãm đóng cửa","Để phản đối một bài đánh giá trực tuyến","Để khuyến khích người nghe tham gia một tour khác","Để đề xuất cải tạo một tòa nhà"],"ans":"C","xp":"Câu hỏi hàm ý. Ngay trước đó người nói giới thiệu \"a new walking tour that will focus on the various murals and statues located throughout the city center\" (tour đi bộ mới xem tranh tường, tượng khắp trung tâm) → câu này nhằm khuyến khích người nghe tham gia tour mới đó."},{"n":94,"q":"What does the speaker give to the listeners?","qvi":"Người nói đưa cho người nghe cái gì?","opts":["City maps","Gift cards","Name badges","Informational brochures"],"vi":["Bản đồ thành phố","Thẻ quà tặng","Thẻ tên","Tờ giới thiệu thông tin"],"ans":"D","xp":"Người nói: \"Here are some brochures with information, including the times and prices.\" → 'brochures with information' = 'Informational brochures'."}],"a":"E24-T04-92-94.mp3"},{"ns":[95,97],"script":[["","In local news, the Bayland Transit Agency has announced that construction has begun on the new Alexton train station, which will offer a direct rail connection to the city center. Spokesperson Claudia Schneider explained that the agency initially considered a more elaborate design with a projected cost of 300 million dollars but ultimately decided to go with a more cost-effective and straightforward proposal with a price tag of 250 million dollars. Not only is it more economical, but an earlier completion date is expected. The building will have an adjacent small park for public use, and beginning in May, residents will be invited to vote on ideas for it.","Tin tức địa phương: Cơ quan Giao thông Bayland đã thông báo rằng việc xây dựng nhà ga tàu hỏa Alexton mới đã bắt đầu; nhà ga sẽ có tuyến đường sắt nối thẳng đến trung tâm thành phố. Người phát ngôn Claudia Schneider giải thích rằng ban đầu cơ quan đã cân nhắc một thiết kế cầu kỳ hơn với chi phí dự kiến 300 triệu đô la, nhưng cuối cùng đã quyết định chọn một đề xuất đơn giản và tiết kiệm chi phí hơn với giá 250 triệu đô la. Phương án này không chỉ tiết kiệm hơn mà còn được dự kiến hoàn thành sớm hơn. Tòa nhà sẽ có một công viên nhỏ bên cạnh dành cho công chúng, và bắt đầu từ tháng Năm, người dân sẽ được mời bỏ phiếu cho các ý tưởng về công viên này."]],"qs":[{"n":95,"q":"What is the broadcast mainly about?","qvi":"Bản tin chủ yếu nói về điều gì?","opts":["A renovated airport terminal","A redesigned city hall","A new train station","A new bridge"],"vi":["Một nhà ga sân bay được cải tạo","Một tòa thị chính được thiết kế lại","Một nhà ga tàu hỏa mới","Một cây cầu mới"],"ans":"C","xp":"Người nói: \"construction has begun on the new Alexton train station\" (đã bắt đầu xây nhà ga tàu Alexton mới) → chủ đề là 'A new train station'."},{"n":96,"q":"Look at the graphic. Which proposal was chosen?","qvi":"Nhìn vào bảng. Đề xuất nào đã được chọn?","opts":["Plan A","Plan B","Plan C","Plan D"],"vi":["Phương án A","Phương án B","Phương án C","Phương án D"],"ans":"D","xp":"Người nói: \"ultimately decided to go with a more cost-effective and straightforward proposal with a price tag of 250 million dollars\" (cuối cùng chọn đề xuất giá 250 triệu đô). Theo bảng, $250 million là Plan D → chọn (D). Lưu ý: 300 triệu (Plan C) là thiết kế ban đầu bị loại."},{"n":97,"q":"According to the speaker, what will residents be able to vote on?","qvi":"Theo người nói, người dân sẽ được bỏ phiếu về điều gì?","opts":["Parking options","Food vendors","Public artwork","Park ideas"],"vi":["Các lựa chọn đỗ xe","Các quầy bán đồ ăn","Tác phẩm nghệ thuật công cộng","Ý tưởng cho công viên"],"ans":"D","xp":"Người nói: \"The building will have an adjacent small park ... residents will be invited to vote on ideas for it\" (người dân được mời bỏ phiếu cho ý tưởng về công viên) → 'Park ideas'."}],"a":"E24-T04-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Welcome, everyone, to the grand opening of the Wilton Business Center. As the mayor, I'm pleased to see this kind of growth in our city. And the environmentally friendly elements incorporated into the design make this building special. In particular, this building is equipped with a water recycling system and insulation made from repurposed cloth. While today is the grand opening, one part of the building—the recreation center—will not be available for use until next month, as final touches are still being added to that floor.","Chào mừng tất cả mọi người đến với lễ khai trương Trung tâm Thương mại Wilton. Với tư cách là thị trưởng, tôi rất vui khi thấy thành phố chúng ta phát triển như thế này. Và những yếu tố thân thiện với môi trường được đưa vào thiết kế khiến tòa nhà này trở nên đặc biệt. Cụ thể, tòa nhà được trang bị hệ thống tái chế nước và vật liệu cách nhiệt làm từ vải tái sử dụng. Dù hôm nay là ngày khai trương, một phần của tòa nhà — trung tâm giải trí — sẽ chưa thể sử dụng cho đến tháng sau, vì tầng đó vẫn đang được hoàn thiện những khâu cuối cùng."]],"qs":[{"n":98,"q":"Who is the speaker?","qvi":"Người nói là ai?","opts":["A structural engineer","A journalist","A tour guide","A city official"],"vi":["Kỹ sư kết cấu","Nhà báo","Hướng dẫn viên du lịch","Quan chức thành phố"],"ans":"D","xp":"Người nói: \"As the mayor, I'm pleased to see this kind of growth in our city.\" (với tư cách là thị trưởng) → 'the mayor' = 'A city official'."},{"n":99,"q":"Why is a building special?","qvi":"Tại sao tòa nhà đặc biệt?","opts":["It was constructed in a short time.","It has a technologically advanced security system.","It has environmentally friendly features.","It was designed by a famous architect."],"vi":["Nó được xây dựng trong thời gian ngắn.","Nó có hệ thống an ninh công nghệ tiên tiến.","Nó có những đặc điểm thân thiện với môi trường.","Nó được một kiến trúc sư nổi tiếng thiết kế."],"ans":"C","xp":"Người nói: \"the environmentally friendly elements incorporated into the design make this building special\" (các yếu tố thân thiện môi trường khiến tòa nhà đặc biệt) → 'elements' = 'features' → chọn (C)."},{"n":100,"q":"Look at the graphic. Which floor of the building is not open yet?","qvi":"Nhìn vào hình. Tầng nào của tòa nhà chưa mở cửa?","opts":["Floor 4","Floor 3","Floor 2","Floor 1"],"vi":["Tầng 4","Tầng 3","Tầng 2","Tầng 1"],"ans":"C","xp":"Người nói: \"the recreation center—will not be available for use until next month\" (trung tâm giải trí chưa dùng được đến tháng sau). Theo hình, Recreation Center ở Floor 2 → chọn (C)."}],"a":"E24-T04-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Mr. Barrientos has worked at the company ------- six years.","opts":["for","since","with","lately"],"ans":"A","xp":"Giới từ chỉ thời gian với thì hiện tại hoàn thành. Sau chỗ trống là khoảng thời gian 'six years' → dùng 'for' (trong khoảng). (B) since + mốc thời gian (since 2020), (C) with 'với', (D) lately là trạng từ 'gần đây', không đứng trước danh từ.\nDịch: Ông Barrientos đã làm việc ở công ty được sáu năm."},{"n":102,"q":"The staff cafeteria stops ------- lunch at 2:00 P.M.","opts":["taking","buying","serving","working"],"ans":"C","xp":"Từ vựng (động từ đi với 'lunch'). Căng tin ngừng 'phục vụ' bữa trưa lúc 2 giờ → serving. (A) taking 'lấy, dùng', (B) buying 'mua', (D) working 'làm việc' (nội động từ, không đi với tân ngữ 'lunch').\nDịch: Căng tin nhân viên ngừng phục vụ bữa trưa lúc 2 giờ chiều."},{"n":103,"q":"The annual report will be ready after ------- make the necessary revisions.","opts":["I","me","myself","my"],"ans":"A","xp":"Đại từ. 'after' ở đây là liên từ, sau nó là một mệnh đề, chỗ trống đứng trước động từ 'make' → cần đại từ chủ ngữ 'I'. (B) me là tân ngữ, (C) myself là đại từ phản thân, (D) my là tính từ sở hữu (phải có danh từ theo sau).\nDịch: Bản báo cáo thường niên sẽ sẵn sàng sau khi tôi thực hiện những chỉnh sửa cần thiết."},{"n":104,"q":"Mr. Louden was offered a full-time position at Fortelio Corporation ------- a division manager.","opts":["about","as","after","around"],"ans":"B","xp":"Giới từ. 'as' + chức danh = 'với vai trò/ở vị trí là'. Được mời làm việc toàn thời gian với vị trí trưởng bộ phận → as. (A) about 'về', (C) after 'sau', (D) around 'xung quanh' đều không hợp nghĩa.\nDịch: Ông Louden được mời nhận một vị trí toàn thời gian tại Tập đoàn Fortelio với vai trò trưởng bộ phận."},{"n":105,"q":"Kennedy Sports will ------- its end-of-season sale through the month of January.","opts":["continuing","continued","continues","continue"],"ans":"D","xp":"Dạng động từ. Sau động từ khuyết thiếu 'will' phải là động từ nguyên mẫu không 'to' → continue. (A) V-ing, (B) quá khứ/quá khứ phân từ, (C) chia ngôi thứ ba số ít đều sai sau 'will'.\nDịch: Kennedy Sports sẽ tiếp tục đợt giảm giá cuối mùa suốt tháng Một."},{"n":106,"q":"Ms. Najjar is going to give a presentation ------- workplace regulations at noon.","opts":["near","to","past","on"],"ans":"D","xp":"Giới từ. 'a presentation on + chủ đề' = bài thuyết trình về... → on. (A) near 'gần', (B) to 'đến', (C) past 'qua' không diễn tả chủ đề.\nDịch: Cô Najjar sẽ có một bài thuyết trình về các quy định nơi làm việc vào buổi trưa."},{"n":107,"q":"Mr. Telguld submitted the ------- surveys before the monthly board meeting.","opts":["completely","completed","completing","completes"],"ans":"B","xp":"Từ loại. Giữa mạo từ 'the' và danh từ 'surveys' cần một tính từ. 'completed' (quá khứ phân từ dùng như tính từ) = 'đã được hoàn thành/điền xong' – các bản khảo sát được điền xong (nghĩa bị động) → chọn (B). (A) completely là trạng từ, (C) completing mang nghĩa chủ động 'đang hoàn thành', không hợp, (D) completes là động từ.\nDịch: Ông Telguld đã nộp các bản khảo sát đã hoàn thành trước cuộc họp hội đồng quản trị hằng tháng."},{"n":108,"q":"Travel funds are available to student presenters coming to the conference from a significant -------.","opts":["location","amount","reason","distance"],"ans":"D","xp":"Từ vựng. 'from a significant distance' = từ một khoảng cách xa đáng kể – hợp với ý hỗ trợ chi phí đi lại → distance. (A) location 'địa điểm' (không đi với 'significant' theo nghĩa này), (B) amount 'số lượng', (C) reason 'lý do'.\nDịch: Quỹ hỗ trợ đi lại dành cho các sinh viên thuyết trình đến hội nghị từ những nơi xa xôi."},{"n":109,"q":"Ms. Okada is ------- a new social media campaign at the request of our office manager.","opts":["organize","organized","organizing","organization"],"ans":"C","xp":"Dạng động từ (thì). Sau 'is' và trước tân ngữ 'a new social media campaign' → cần V-ing để tạo thì hiện tại tiếp diễn (is organizing) mang nghĩa chủ động. (A) nguyên mẫu không đứng sau 'is', (B) 'is organized' là bị động nhưng phía sau còn tân ngữ nên sai, (D) organization là danh từ.\nDịch: Cô Okada đang tổ chức một chiến dịch truyền thông mạng xã hội mới theo yêu cầu của quản lý văn phòng chúng tôi."},{"n":110,"q":"The speaker will offer five tips for making wise purchasing -------.","opts":["items","decisions","values","remedies"],"ans":"B","xp":"Từ vựng / cụm từ cố định. 'make a decision' = đưa ra quyết định; 'purchasing decisions' = quyết định mua hàng; 'wise' (sáng suốt) hợp với 'decisions'. (A) items 'món hàng', (C) values 'giá trị', (D) remedies 'biện pháp khắc phục' không đi với 'make ... wise'.\nDịch: Diễn giả sẽ đưa ra năm lời khuyên để đưa ra những quyết định mua hàng sáng suốt."},{"n":111,"q":"Please log on to your online checking account ------- the next 30 days in order to keep it active.","opts":["within","how","whether","and"],"ans":"A","xp":"Giới từ. Trước cụm danh từ chỉ thời gian 'the next 30 days' → within 'trong vòng'. (B) how, (C) whether là từ nối mệnh đề, (D) and nối các thành phần cùng loại – đều không hợp.\nDịch: Vui lòng đăng nhập vào tài khoản thanh toán trực tuyến của bạn trong vòng 30 ngày tới để duy trì trạng thái hoạt động."},{"n":112,"q":"The Bradyville Inn ------- live jazz music in the dining area on Friday evenings.","opts":["features","marks","sounds","collects"],"ans":"A","xp":"Từ vựng. 'feature' = có/giới thiệu (một điểm nổi bật) – nhà nghỉ có nhạc jazz sống ở khu ăn uống → features. (B) marks 'đánh dấu', (C) sounds 'nghe có vẻ/phát ra âm thanh', (D) collects 'thu thập'.\nDịch: Nhà nghỉ Bradyville có nhạc jazz biểu diễn trực tiếp ở khu vực ăn uống vào các tối thứ Sáu."},{"n":113,"q":"Leeann's Organic Fruit Spreads can be purchased ------- from the company's Web site.","opts":["direction","directly","directness","directed"],"ans":"B","xp":"Từ loại. Sau động từ bị động 'can be purchased' cần trạng từ để bổ nghĩa → directly 'trực tiếp'. (A) direction, (C) directness là danh từ, (D) directed là động từ/phân từ.\nDịch: Mứt trái cây hữu cơ Leeann's có thể được mua trực tiếp từ trang web của công ty."},{"n":114,"q":"------- the event organizers' best efforts, they have been unable to attract enough volunteers this spring.","opts":["Behind","Versus","Among","Despite"],"ans":"D","xp":"Giới từ chỉ sự nhượng bộ. Hai vế trái ngược: đã cố gắng hết sức nhưng vẫn không thu hút đủ tình nguyện viên → Despite 'mặc dù'. (A) Behind 'đằng sau', (B) Versus 'đối đầu với', (C) Among 'trong số'.\nDịch: Mặc dù các nhà tổ chức sự kiện đã nỗ lực hết sức, họ vẫn không thể thu hút đủ tình nguyện viên trong mùa xuân này."},{"n":115,"q":"Mr. Perez ------- as an industrial engineer at Gaberly Logistics for almost twenty years.","opts":["employs","to be employed","is employing","has been employed"],"ans":"D","xp":"Thì + thể bị động. 'for almost twenty years' → thì hiện tại hoàn thành; ông Perez 'được thuê/làm việc' → bị động: has been employed. (A) employs và (C) is employing là chủ động, cần tân ngữ; (B) to be employed không phải động từ chính.\nDịch: Ông Perez đã làm kỹ sư công nghiệp tại Gaberly Logistics được gần hai mươi năm."},{"n":116,"q":"Soon after Ms. Manilla was hired, the sales department's productivity began to increase -------.","opts":["mainly","respectively","noticeably","closely"],"ans":"C","xp":"Từ vựng (trạng từ). Năng suất bắt đầu tăng 'một cách rõ rệt' → noticeably. (A) mainly 'chủ yếu', (B) respectively 'lần lượt, tương ứng', (D) closely 'chặt chẽ, sát sao' không hợp với 'increase'.\nDịch: Ngay sau khi cô Manilla được tuyển dụng, năng suất của phòng kinh doanh bắt đầu tăng lên rõ rệt."},{"n":117,"q":"Small businesses ------- participate in the Get Ahead program will receive marketing tools to help them attract customers.","opts":["that","they","what","whoever"],"ans":"A","xp":"Đại từ quan hệ. Chỗ trống nối danh từ 'Small businesses' với mệnh đề thiếu chủ ngữ 'participate in...' → đại từ quan hệ 'that' (= which). (B) they là đại từ nhân xưng, không nối mệnh đề; (C) what và (D) whoever không đứng sau danh từ để bổ nghĩa.\nDịch: Các doanh nghiệp nhỏ tham gia chương trình Get Ahead sẽ nhận được các công cụ tiếp thị giúp họ thu hút khách hàng."},{"n":118,"q":"Our copy editors will review the manuscript ------- will not return it until the end of next week.","opts":["or","once","either","but"],"ans":"D","xp":"Liên từ. Hai mệnh đề có chung chủ ngữ, ý tương phản: sẽ xem xét bản thảo NHƯNG sẽ không gửi lại cho đến cuối tuần sau → but. (A) or 'hoặc' không hợp nghĩa, (B) once 'một khi' cần chủ ngữ riêng, (C) either phải đi với 'or'.\nDịch: Các biên tập viên của chúng tôi sẽ xem xét bản thảo nhưng sẽ không gửi lại cho đến cuối tuần sau."},{"n":119,"q":"Mira Kumar was probably the ------- of all the interns at Kolbry Media last summer.","opts":["ambitious","most ambitious","ambitiously","more ambitiously"],"ans":"B","xp":"So sánh nhất. Có 'the ... of all the interns' (trong số tất cả thực tập sinh) → dùng so sánh nhất 'the most ambitious' (người tham vọng nhất). (A) tính từ nguyên dạng, (C), (D) là trạng từ.\nDịch: Mira Kumar có lẽ là người tham vọng nhất trong số tất cả các thực tập sinh tại Kolbry Media mùa hè năm ngoái."},{"n":120,"q":"Orbin's Fish Company expanded to a total of 26 stores ------- its takeover of a rival chain.","opts":["whenever","toward","following","usually"],"ans":"C","xp":"Giới từ. Trước cụm danh từ 'its takeover of a rival chain' cần giới từ; 'following' = 'sau, tiếp theo sau' → mở rộng lên 26 cửa hàng sau khi thâu tóm chuỗi đối thủ. (A) whenever là liên từ (cần mệnh đề), (B) toward 'về phía', (D) usually là trạng từ.\nDịch: Công ty Cá Orbin's đã mở rộng lên tổng cộng 26 cửa hàng sau khi tiếp quản một chuỗi đối thủ."},{"n":121,"q":"Ms. Cartwright told her team members that she wanted ------- to streamline the company's assembly process.","opts":["theirs","they","them","themselves"],"ans":"C","xp":"Đại từ. Cấu trúc 'want + tân ngữ + to V' (muốn ai làm gì) → cần đại từ tân ngữ 'them' (chỉ các thành viên nhóm). (A) theirs là đại từ sở hữu, (B) they là chủ ngữ, (D) themselves là phản thân (chủ ngữ 'she' khác 'them').\nDịch: Cô Cartwright nói với các thành viên trong nhóm rằng cô muốn họ tinh giản quy trình lắp ráp của công ty."},{"n":122,"q":"Rupert's Food Service uses ------- technology to track all of its shipments.","opts":["strict","numerous","advanced","crowded"],"ans":"C","xp":"Từ vựng (tính từ). 'advanced technology' = công nghệ tiên tiến – cụm rất phổ biến. (A) strict 'nghiêm ngặt', (B) numerous 'nhiều' (đi với danh từ số nhiều đếm được, 'technology' ở đây không đếm được), (D) crowded 'đông đúc'.\nDịch: Dịch vụ Thực phẩm Rupert's sử dụng công nghệ tiên tiến để theo dõi tất cả các lô hàng của mình."},{"n":123,"q":"Our app includes a ------- so that users can determine whether they are within their budget goals.","opts":["calculator","calculated","calculating","calculations"],"ans":"A","xp":"Từ loại. Sau mạo từ 'a' cần danh từ số ít đếm được → calculator 'máy tính, công cụ tính toán'. (D) calculations là danh từ số nhiều, không đi với 'a'; (B), (C) là dạng động từ.\nDịch: Ứng dụng của chúng tôi có một công cụ tính toán để người dùng có thể xác định xem họ có đang nằm trong mục tiêu ngân sách hay không."},{"n":124,"q":"To ------- that its facilities are cleaned every day, the Selboa Company has hired more janitors.","opts":["ensure","affect","provide","secure"],"ans":"A","xp":"Từ vựng. 'ensure that + mệnh đề' = đảm bảo rằng... → hợp nghĩa: để đảm bảo cơ sở được dọn dẹp mỗi ngày. (B) affect 'ảnh hưởng', (C) provide 'cung cấp', (D) secure 'giành được, bảo đảm an toàn' thường không đi với mệnh đề 'that' theo nghĩa này.\nDịch: Để đảm bảo các cơ sở của mình được dọn dẹp mỗi ngày, Công ty Selboa đã thuê thêm nhân viên vệ sinh."},{"n":125,"q":"During his term as a legislator, Jeremy Moran ------- promoted public awareness of the need for infrastructure improvements.","opts":["act","action","active","actively"],"ans":"D","xp":"Từ loại. Chỗ trống đứng giữa chủ ngữ 'Jeremy Moran' và động từ 'promoted' → cần trạng từ bổ nghĩa cho động từ: actively 'một cách tích cực'. (A) act động từ, (B) action danh từ, (C) active tính từ.\nDịch: Trong nhiệm kỳ làm nhà lập pháp, Jeremy Moran đã tích cực nâng cao nhận thức của công chúng về nhu cầu cải thiện cơ sở hạ tầng."},{"n":126,"q":"Pyxie Print's business is so new that we need to explain the full range of our services to ------- clients.","opts":["trained","potential","elected","paid"],"ans":"B","xp":"Từ vựng (tính từ). Công ty còn quá mới nên cần giải thích dịch vụ cho khách hàng 'tiềm năng' → potential clients. (A) trained 'được đào tạo', (C) elected 'được bầu', (D) paid 'được trả tiền' không hợp.\nDịch: Doanh nghiệp của Pyxie Print còn quá mới nên chúng tôi cần giải thích toàn bộ các dịch vụ của mình cho khách hàng tiềm năng."},{"n":127,"q":"Phone orders that are ------- to local stores by 11:00 A.M. are eligible for same-day pickup.","opts":["submitted","submission","submitting","submits"],"ans":"A","xp":"Thể bị động. 'Phone orders' (đơn hàng) được gửi đi → bị động 'are submitted'. (C) submitting tạo thì tiếp diễn chủ động (đơn hàng không tự gửi), (B) danh từ, (D) động từ chia không đứng sau 'are'.\nDịch: Các đơn đặt hàng qua điện thoại được gửi đến cửa hàng địa phương trước 11 giờ sáng sẽ đủ điều kiện nhận hàng trong ngày."},{"n":128,"q":"An Oswald Hardware associate will ------- place an order for customers who need larger quantities than what is in stock.","opts":["slightly","wholly","busily","gladly"],"ans":"D","xp":"Từ vựng (trạng từ). Nhân viên sẽ 'sẵn lòng/vui vẻ' đặt hàng cho khách → gladly. (A) slightly 'hơi, một chút', (B) wholly 'hoàn toàn', (C) busily 'bận rộn' không hợp nghĩa.\nDịch: Nhân viên của Oswald Hardware sẽ sẵn lòng đặt hàng cho những khách hàng cần số lượng lớn hơn lượng hàng có sẵn."},{"n":129,"q":"Mia Daushvili performed with the Bayhead Orchestra on Monday evening, ------- her virtuosic skills on the piccolo.","opts":["displays","had displayed","displaying","was displayed"],"ans":"C","xp":"Rút gọn mệnh đề (phân từ). Câu đã có động từ chính 'performed'; sau dấu phẩy là cụm bổ sung, chủ ngữ chung là Mia (chủ động, có tân ngữ 'her virtuosic skills') → V-ing: displaying. (A), (B), (D) là động từ chia, không thể đứng sau dấu phẩy mà không có liên từ; (D) còn là bị động.\nDịch: Mia Daushvili đã biểu diễn cùng Dàn nhạc Bayhead vào tối thứ Hai, thể hiện kỹ năng điêu luyện của mình với cây sáo piccolo."},{"n":130,"q":"When reviewing applicants for the clerk position, Ms. Ng will consider both education and ------- experience.","opts":["prior","quick","lean","calm"],"ans":"A","xp":"Từ vựng (tính từ). 'prior experience' = kinh nghiệm trước đây – cụm thường gặp khi tuyển dụng. (B) quick 'nhanh', (C) lean 'gầy, tinh gọn', (D) calm 'bình tĩnh' không hợp.\nDịch: Khi xem xét các ứng viên cho vị trí thư ký, cô Ng sẽ cân nhắc cả trình độ học vấn lẫn kinh nghiệm trước đây."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following notice.","passage":"<h3>D-Zine Pop</h3><p>D-Zine Pop is your source for information about the latest <span class=\"blank\" data-n=\"131\">-------</span> in the world of fashion. What started as a social media experiment <span class=\"blank\" data-n=\"132\">-------</span> into a content platform with subscribers in seventeen countries worldwide. We are constantly adding features to improve our user experience and share what apparel and clothing accessories are popular right now. We also make periodic updates to our terms of service. Subscribers' <span class=\"blank\" data-n=\"133\">-------</span> access to content is contingent upon consenting to these terms; therefore, we encourage you to review and accept them at dzinepop.com/privacy. Contact our customer service team at support@dzinepop.com if you have any questions. <span class=\"blank\" data-n=\"134\">-------</span>.</p>","vi":"D-Zine Pop\n\nD-Zine Pop là nguồn thông tin của bạn về những xu hướng mới nhất trong thế giới thời trang. Khởi đầu là một thử nghiệm trên mạng xã hội, chúng tôi đã phát triển thành một nền tảng nội dung với người đăng ký ở mười bảy quốc gia trên toàn thế giới. Chúng tôi liên tục bổ sung các tính năng để cải thiện trải nghiệm người dùng và chia sẻ những trang phục, phụ kiện thời trang đang được ưa chuộng hiện nay. Chúng tôi cũng cập nhật định kỳ các điều khoản dịch vụ. Việc người đăng ký tiếp tục được truy cập nội dung phụ thuộc vào việc đồng ý với các điều khoản này; vì vậy, chúng tôi khuyến khích bạn xem lại và chấp nhận chúng tại dzinepop.com/privacy. Hãy liên hệ đội ngũ chăm sóc khách hàng của chúng tôi tại support@dzinepop.com nếu bạn có bất kỳ câu hỏi nào. Nhân viên luôn sẵn sàng hỗ trợ bạn 24 giờ mỗi ngày.","qs":[{"n":131,"opts":["controversies","consumers","trends","versions"],"ans":"C","xp":"Từ vựng. 'the latest trends in the world of fashion' = những xu hướng mới nhất trong giới thời trang; câu sau cũng nhắc 'what apparel ... are popular right now' (cái gì đang thịnh hành) → trends. (A) controversies 'tranh cãi', (B) consumers 'người tiêu dùng', (D) versions 'phiên bản'.\nDịch: D-Zine Pop là nguồn thông tin của bạn về những xu hướng mới nhất trong thế giới thời trang."},{"n":132,"opts":["evolving","evolution","will be evolving","has evolved"],"ans":"D","xp":"Thì của động từ. Chủ ngữ là mệnh đề 'What started as a social media experiment', câu cần động từ chính. Sự việc bắt đầu trong quá khứ và kết quả kéo dài đến hiện tại (hiện có người đăng ký ở 17 nước) → hiện tại hoàn thành 'has evolved'. (A) V-ing và (B) danh từ không làm động từ chính; (C) tương lai không hợp vì việc đã xảy ra.\nDịch: Khởi đầu là một thử nghiệm trên mạng xã hội, (nó) đã phát triển thành một nền tảng nội dung với người đăng ký ở mười bảy quốc gia."},{"n":133,"opts":["continue","continued","continuation","continues"],"ans":"B","xp":"Từ loại. Giữa sở hữu cách 'Subscribers'' và danh từ 'access' cần tính từ → continued 'tiếp tục, liên tục' (continued access = việc tiếp tục được truy cập). (A), (D) là động từ, (C) continuation là danh từ.\nDịch: Việc người đăng ký tiếp tục được truy cập nội dung phụ thuộc vào việc đồng ý với các điều khoản này."},{"n":134,"opts":["Representatives are available 24 hours a day to assist you.","The changes made to our user privacy policy are no longer effective.","Fresh content is accessible through phone and desktop apps.","We are no longer offering a discounted rate if you renew your subscription."],"ans":"A","xp":"Điền câu. Câu ngay trước: 'Contact our customer service team ... if you have any questions.' (liên hệ đội chăm sóc khách hàng nếu có câu hỏi). Câu (A) nói nhân viên ('Representatives' = người của đội chăm sóc khách hàng) sẵn sàng hỗ trợ 24/7 → nối tiếp tự nhiên. (B) mâu thuẫn với việc đang yêu cầu chấp nhận điều khoản mới; (C) và (D) không liên quan đến việc liên hệ hỗ trợ.\n(A) Nhân viên luôn sẵn sàng hỗ trợ bạn 24 giờ mỗi ngày.\n(B) Những thay đổi đối với chính sách quyền riêng tư không còn hiệu lực.\n(C) Nội dung mới có thể truy cập qua ứng dụng điện thoại và máy tính.\n(D) Chúng tôi không còn giảm giá nếu bạn gia hạn đăng ký."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following advertisement.","passage":"<h3>Rescue your device with Phone Tune-Up</h3><p>Is your smartphone screen scratched or cracked? <span class=\"blank\" data-n=\"135\">-------</span>? Do your apps freeze or crash? The experts at Phone Tune-Up can help! We use nothing but the best quality parts to <span class=\"blank\" data-n=\"136\">-------</span> your mobile phone. Let our certified technicians save you the time and expense involved in replacing your phone with a new one. When we are <span class=\"blank\" data-n=\"137\">-------</span>, you will think your old phone is brand new. To make an appointment, call 604-555-0198 or visit www.phonetuneup.com. Same-day service is often available <span class=\"blank\" data-n=\"138\">-------</span> needed parts are in stock.</p>","vi":"Cứu chiếc điện thoại của bạn với Phone Tune-Up\n\nMàn hình điện thoại thông minh của bạn bị trầy xước hay nứt vỡ? Pin của bạn mất cả ngày mới sạc đầy? Các ứng dụng bị treo hay tự thoát? Các chuyên gia tại Phone Tune-Up có thể giúp bạn! Chúng tôi chỉ sử dụng những linh kiện chất lượng tốt nhất để sửa chữa điện thoại di động của bạn. Hãy để các kỹ thuật viên được chứng nhận của chúng tôi giúp bạn tiết kiệm thời gian và chi phí thay điện thoại mới. Khi chúng tôi làm xong, bạn sẽ nghĩ chiếc điện thoại cũ của mình là hàng mới tinh. Để đặt lịch hẹn, hãy gọi 604-555-0198 hoặc truy cập www.phonetuneup.com. Dịch vụ trong ngày thường có sẵn nếu các linh kiện cần thiết còn trong kho.","qs":[{"n":135,"opts":["Does your printer need frequent ink refills?","Does it take all day for your battery to recharge?","Do you want to complete a short survey?","Do you pay too much for your data plan?"],"ans":"B","xp":"Điền câu. Câu trước và sau đều là câu hỏi về các lỗi của điện thoại cần sửa: màn hình trầy/nứt, ứng dụng bị treo. Câu (B) về pin sạc lâu cũng là một lỗi phần cứng của điện thoại → hợp mạch. (A) nói về máy in, (C) khảo sát, (D) gói cước dữ liệu – không phải lỗi mà tiệm sửa điện thoại khắc phục.\n(A) Máy in của bạn có cần đổ mực thường xuyên không?\n(B) Pin của bạn có mất cả ngày mới sạc đầy không?\n(C) Bạn có muốn hoàn thành một khảo sát ngắn không?\n(D) Bạn có đang trả quá nhiều tiền cho gói dữ liệu không?"},{"n":136,"opts":["remove","borrow","examine","repair"],"ans":"D","xp":"Từ vựng. Dùng linh kiện chất lượng tốt nhất để 'sửa chữa' điện thoại; câu sau cũng nói giúp bạn khỏi phải thay điện thoại mới → repair. (A) remove 'tháo bỏ', (B) borrow 'mượn', (C) examine 'kiểm tra' (không cần linh kiện để kiểm tra).\nDịch: Chúng tôi chỉ sử dụng những linh kiện chất lượng tốt nhất để sửa chữa điện thoại di động của bạn."},{"n":137,"opts":["trained","available","done","dismissed"],"ans":"C","xp":"Từ vựng. 'When we are done' = khi chúng tôi làm xong; kết quả là 'bạn sẽ nghĩ điện thoại cũ là hàng mới' → done. (A) trained 'được đào tạo', (B) available 'rảnh, có sẵn', (D) dismissed 'bị cho nghỉ việc' không hợp nghĩa.\nDịch: Khi chúng tôi làm xong, bạn sẽ nghĩ chiếc điện thoại cũ của mình là hàng mới tinh."},{"n":138,"opts":["whose","must","if","of"],"ans":"C","xp":"Liên từ. Sau chỗ trống là một mệnh đề đầy đủ 'needed parts are in stock' → cần liên từ nối hai mệnh đề; 'if' (nếu) nêu điều kiện: dịch vụ trong ngày có sẵn nếu còn linh kiện. (A) whose là đại từ quan hệ sở hữu (phải đứng sau danh từ), (B) must là động từ khuyết thiếu, (D) of là giới từ.\nDịch: Dịch vụ trong ngày thường có sẵn nếu các linh kiện cần thiết còn trong kho."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following press release.","passage":"<h3>FOR IMMEDIATE RELEASE</h3><p>SACRAMENTO (July 28)—The Sacramento-based supermarket chain Hsing Market announced today that it is opening a branch <span class=\"blank\" data-n=\"139\">-------</span> in San Jose in October. It will occupy the building that once housed the Watson Office Superstore located at 1539 West Oak Street, which closed last year.</p><p>Hsing Market CEO Alice Tran said, \"We are very excited to <span class=\"blank\" data-n=\"140\">-------</span> open a store in San Jose. <span class=\"blank\" data-n=\"141\">-------</span>. When the Watson building became available, we jumped on the opportunity to move in.\"</p><p>As a neighborhood grocery store, Hsing Market prides itself on hiring applicants from the local community. Approximately 75 percent of all employees live within two miles of the store where they <span class=\"blank\" data-n=\"142\">-------</span>.</p>","vi":"THÔNG CÁO PHÁT HÀNH NGAY\n\nSACRAMENTO (28 tháng 7) – Chuỗi siêu thị Hsing Market có trụ sở tại Sacramento hôm nay thông báo sẽ mở một chi nhánh tại San Jose vào tháng Mười. Chi nhánh này sẽ sử dụng tòa nhà trước đây là Siêu thị Văn phòng phẩm Watson ở số 1539 phố West Oak, nơi đã đóng cửa vào năm ngoái.\n\nGiám đốc điều hành Hsing Market, bà Alice Tran, cho biết: \"Chúng tôi rất hào hứng vì cuối cùng cũng mở được một cửa hàng ở San Jose. Chúng tôi đã để mắt đến thành phố này từ khá lâu rồi. Khi tòa nhà Watson trống, chúng tôi đã nhanh chóng nắm lấy cơ hội để chuyển đến.\"\n\nLà một cửa hàng tạp hóa của khu dân cư, Hsing Market tự hào về việc tuyển dụng ứng viên từ cộng đồng địa phương. Khoảng 75% nhân viên sống trong phạm vi hai dặm tính từ cửa hàng nơi họ làm việc.","qs":[{"n":139,"opts":["location","locate","to locate","locating"],"ans":"A","xp":"Từ loại (danh từ ghép). Sau mạo từ 'a' và danh từ 'branch' cần danh từ để tạo danh từ ghép 'a branch location' (một địa điểm chi nhánh) làm tân ngữ của 'opening'. (B), (C), (D) là các dạng động từ, không hợp ở vị trí này.\nDịch: Hsing Market hôm nay thông báo sẽ mở một chi nhánh tại San Jose vào tháng Mười."},{"n":140,"opts":["finally","instead","likewise","suddenly"],"ans":"A","xp":"Từ vựng (trạng từ). Câu 141 và câu sau cho thấy họ đã mong muốn mở cửa hàng ở đây từ lâu → 'finally' (cuối cùng thì) thể hiện điều mong đợi đã thành hiện thực. (B) instead 'thay vào đó', (C) likewise 'tương tự', (D) suddenly 'đột ngột' không hợp.\nDịch: Chúng tôi rất hào hứng vì cuối cùng cũng mở được một cửa hàng ở San Jose."},{"n":141,"opts":["The store features a variety of fresh and prepared foods.","We hope that you will be able to join us at our grand-opening celebration.","We have had our eyes on the city for quite some time.","Our corporate headquarters will be renovated soon."],"ans":"C","xp":"Điền câu. Trước đó: rất vui vì 'cuối cùng' cũng mở cửa hàng ở San Jose; sau đó: khi tòa nhà Watson trống, 'we jumped on the opportunity' (chớp lấy cơ hội). Câu (C) 'đã để mắt tới thành phố này từ lâu' giải thích vì sao họ chớp ngay cơ hội → mạch lạc. (A) nói về sản phẩm, (B) mời dự khai trương, (D) nói về trụ sở – đều không nối với câu sau.\n(A) Cửa hàng có nhiều loại thực phẩm tươi sống và chế biến sẵn.\n(B) Chúng tôi hy vọng bạn có thể tham gia lễ khai trương cùng chúng tôi.\n(C) Chúng tôi đã để mắt đến thành phố này từ khá lâu rồi.\n(D) Trụ sở công ty của chúng tôi sắp được cải tạo."},{"n":142,"opts":["save","work","shop","register"],"ans":"B","xp":"Từ vựng. Đoạn văn nói về việc tuyển nhân viên từ cộng đồng địa phương: 75% nhân viên sống trong vòng hai dặm từ cửa hàng nơi họ 'làm việc' → work. (A) save 'tiết kiệm', (C) shop 'mua sắm' (là việc của khách hàng), (D) register 'đăng ký'.\nDịch: Khoảng 75% nhân viên sống trong phạm vi hai dặm tính từ cửa hàng nơi họ làm việc."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following Web page information.","passage":"<h3>About Leafi Cloth</h3><p>Tropick Textiles recently expanded the <span class=\"blank\" data-n=\"143\">-------</span> of fabrics available on the market. In its quest to introduce environmentally friendly alternatives to cotton and other traditional fibers, the company <span class=\"blank\" data-n=\"144\">-------</span> a new fiber made from materials that are typically discarded. Tropick Textiles takes banana and pineapple leaves and combines them with bamboo fibers to create Leafi Cloth. The plants' leaves are ordinarily disposed of <span class=\"blank\" data-n=\"145\">-------</span> the fruit is harvested. Tropick Textiles' process prevents many leaves from entering a landfill, converting them instead into usable material. <span class=\"blank\" data-n=\"146\">-------</span>.</p>","vi":"Giới thiệu về vải Leafi\n\nTropick Textiles gần đây đã mở rộng chủng loại vải có mặt trên thị trường. Trong nỗ lực giới thiệu những lựa chọn thân thiện với môi trường thay thế cho bông và các loại sợi truyền thống khác, công ty đã phát triển một loại sợi mới làm từ những vật liệu thường bị vứt bỏ. Tropick Textiles lấy lá chuối và lá dứa rồi kết hợp với sợi tre để tạo ra vải Leafi. Lá của những cây này thường bị vứt bỏ một khi trái đã được thu hoạch. Quy trình của Tropick Textiles giúp nhiều lá cây không bị đưa vào bãi rác, mà thay vào đó biến chúng thành vật liệu có thể sử dụng. Loại vải bền thu được là một sự thay thế phù hợp cho vải cotton.","qs":[{"n":143,"opts":["range","expense","strength","appearance"],"ans":"A","xp":"Từ vựng. 'expand the range of fabrics' = mở rộng chủng loại/phạm vi các loại vải; đoạn sau nói công ty tạo ra một loại sợi mới → thêm lựa chọn trên thị trường → range. (B) expense 'chi phí', (C) strength 'độ bền', (D) appearance 'vẻ ngoài' không hợp với 'of fabrics available on the market'.\nDịch: Tropick Textiles gần đây đã mở rộng chủng loại vải có mặt trên thị trường."},{"n":144,"opts":["are developed","has developed","will develop","to develop"],"ans":"B","xp":"Thì + chủ động/bị động + hòa hợp chủ ngữ. Chủ ngữ 'the company' số ít, có tân ngữ 'a new fiber' → chủ động. Câu trước nói 'recently expanded' và câu sau mô tả quy trình đang diễn ra → việc phát triển đã xảy ra: has developed. (A) bị động, số nhiều; (C) tương lai mâu thuẫn với việc vải đã có; (D) to V không làm động từ chính.\nDịch: Công ty đã phát triển một loại sợi mới làm từ những vật liệu thường bị vứt bỏ."},{"n":145,"opts":["now","thus","even","once"],"ans":"D","xp":"Liên từ. Sau chỗ trống là mệnh đề 'the fruit is harvested' → cần liên từ; 'once' = 'một khi, sau khi' → lá bị vứt bỏ sau khi trái được thu hoạch. (A) now, (B) thus 'do đó', (C) even 'thậm chí' là trạng từ, không nối hai mệnh đề.\nDịch: Lá của những cây này thường bị vứt bỏ một khi trái đã được thu hoạch."},{"n":146,"opts":["The resulting durable fabric is a suitable substitute for cotton cloth.","Inquiries regarding Leafi Cloth were directed to the sales department.","Tropick Textiles will celebrate its one-hundredth anniversary this year.","Manufacturing costs have been increasing for Tropick Textiles lately."],"ans":"A","xp":"Điền câu. Câu trước: quy trình biến lá thành 'usable material' (vật liệu dùng được). Câu (A) nói về loại vải 'thu được' (resulting) bền và thay thế được cho cotton → khép lại đoạn văn, đồng thời nối với ý đầu bài 'alternatives to cotton'. (B), (C), (D) không liên quan đến nội dung về sản phẩm.\n(A) Loại vải bền thu được là một sự thay thế phù hợp cho vải cotton.\n(B) Các câu hỏi về vải Leafi đã được chuyển đến phòng kinh doanh.\n(C) Tropick Textiles sẽ kỷ niệm 100 năm thành lập trong năm nay.\n(D) Chi phí sản xuất của Tropick Textiles gần đây đang tăng."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following receipt.","passages":["<h3>Zippy Petrol Mart</h3><p>M64 Motorway<br>Leicester<br>0113 4960423<br>23 May</p>\n<table><tr><td>Biscuits</td><td>£2.00</td></tr><tr><td>Fruit cup</td><td>£0.95</td></tr><tr><td>Crisps</td><td>£1.10</td></tr><tr><td><b>VAT Inclusive</b></td><td><b>£0.81</b></td></tr><tr><td>Total</td><td><b>£4.86</b></td></tr></table>\n<h4>Sign up for our Zippy Club rewards card.</h4><p>You could have earned 4 Zippy Club points on this transaction. Points can be used for discounted merchandise, car products, phone accessories, and more!</p>"],"vi":"Zippy Petrol Mart (Cửa hàng xăng dầu Zippy)\nĐường cao tốc M64\nLeicester\n0113 4960423\nNgày 23 tháng 5\n\nBánh quy: £2.00\nCốc trái cây: £0.95\nKhoai tây chiên lát: £1.10\nĐã bao gồm thuế VAT: £0.81\nTổng cộng: £4.86\n\nHãy đăng ký thẻ thành viên tích điểm Zippy Club của chúng tôi.\nBạn đã có thể tích được 4 điểm Zippy Club cho giao dịch này. Điểm có thể dùng để mua hàng hóa giảm giá, sản phẩm cho xe hơi, phụ kiện điện thoại và nhiều thứ khác!","qs":[{"n":147,"q":"What was purchased on May 23 ?","qvi":"Đã mua gì vào ngày 23 tháng 5?","opts":["Fuel","Snacks","Auto parts","Phone accessories"],"ans":"B","xp":"Câu hỏi chi tiết. Hóa đơn ngày \"23 May\" liệt kê: \"Biscuits\" (bánh quy), \"Fruit cup\" (cốc trái cây), \"Crisps\" (khoai tây chiên lát) → đều là đồ ăn vặt = Snacks → chọn (B).\n(A) không có xăng trong hóa đơn dù đây là cửa hàng xăng. (C), (D): phụ tùng xe và phụ kiện điện thoại chỉ được nhắc như thứ có thể đổi bằng điểm, không phải đã mua.\n(A) Nhiên liệu\n(B) Đồ ăn vặt\n(C) Phụ tùng ô tô\n(D) Phụ kiện điện thoại"},{"n":148,"q":"What does the receipt indicate about Zippy Petrol Mart?","qvi":"Hóa đơn cho biết điều gì về Zippy Petrol Mart?","opts":["It has multiple locations.","It accepts most major credit cards.","It has a customer rewards program.","It reduced the prices of all its merchandise."],"ans":"C","xp":"Câu hỏi chi tiết. Cuối hóa đơn: \"Sign up for our Zippy Club rewards card. You could have earned 4 Zippy Club points on this transaction.\" → cửa hàng có chương trình tích điểm cho khách hàng (rewards card = customer rewards program) → chọn (C).\nCác ý còn lại (nhiều chi nhánh, nhận thẻ tín dụng, giảm giá mọi mặt hàng) không được nhắc đến.\n(A) Nó có nhiều địa điểm.\n(B) Nó chấp nhận hầu hết các loại thẻ tín dụng lớn.\n(C) Nó có chương trình tích điểm cho khách hàng.\n(D) Nó đã giảm giá tất cả hàng hóa."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following notice.","passages":["<h3>Coming Soon: The Best of PBQ Radio</h3>\n<p>During the week of April 21–27, PBQ Radio will be hosting a best-of-the-decade program. The most popular tunes by recording artists from the past decade will be played all day long. Both well-known and lesser-known recording artists will be featured. We plan to showcase each artist's top works.</p>\n<p>In addition to featuring the best music of the decade, we would like to highlight our region's businesses. Advertising time is available for purchase. Let our listeners know that your business is one of the best in the community! You can request a shout-out for your company from a program host, or our professional marketing team can write and record a 30-second advertisement.</p>\n<p>Visit www.pbqradio.com/advertise for details and pricing.</p>"],"vi":"Sắp ra mắt: Những điều hay nhất của Đài PBQ\n\nTrong tuần từ 21–27 tháng 4, Đài PBQ sẽ tổ chức chương trình \"hay nhất thập kỷ\". Những bài hát được yêu thích nhất của các nghệ sĩ thu âm trong thập kỷ qua sẽ được phát suốt cả ngày. Cả những nghệ sĩ nổi tiếng lẫn ít tên tuổi hơn đều sẽ được giới thiệu. Chúng tôi dự định giới thiệu những tác phẩm hàng đầu của từng nghệ sĩ.\n\nNgoài việc giới thiệu những bản nhạc hay nhất thập kỷ, chúng tôi cũng muốn quảng bá các doanh nghiệp trong khu vực. Thời lượng quảng cáo đang được bán. Hãy cho thính giả của chúng tôi biết rằng doanh nghiệp của bạn là một trong những doanh nghiệp tốt nhất trong cộng đồng! Bạn có thể yêu cầu người dẫn chương trình nhắc tên (shout-out) công ty mình, hoặc đội ngũ tiếp thị chuyên nghiệp của chúng tôi có thể viết và thu âm một đoạn quảng cáo 30 giây.\n\nHãy truy cập www.pbqradio.com/advertise để biết chi tiết và giá cả.","qs":[{"n":149,"q":"For whom most likely was the notice written?","qvi":"Thông báo này nhiều khả năng được viết cho ai?","opts":["Radio-show hosts","New recording artists","Business owners","Sound technicians"],"ans":"C","xp":"Câu hỏi suy luận (đối tượng đọc). Đoạn 2: \"we would like to highlight our region's businesses. Advertising time is available for purchase. Let our listeners know that your business is one of the best...\" → thông báo mời mua thời lượng quảng cáo cho \"your business\" → người đọc là chủ doanh nghiệp → chọn (C).\n(A) Người dẫn chương trình radio\n(B) Nghệ sĩ thu âm mới\n(C) Chủ doanh nghiệp\n(D) Kỹ thuật viên âm thanh"},{"n":150,"q":"What is true about PBQ Radio?","qvi":"Điều gì đúng về Đài PBQ?","opts":["It has been in business for ten years.","It is looking for experienced musicians.","It was voted the best station in the community.","It has its own marketing department."],"ans":"D","xp":"Câu hỏi chi tiết (True). \"...or our professional marketing team can write and record a 30-second advertisement.\" → đài có đội ngũ tiếp thị riêng (our professional marketing team = its own marketing department) → chọn (D).\n(A) Sai: \"best-of-the-decade\" nói về nhạc của thập kỷ qua, không nói đài đã hoạt động 10 năm. (B) Không tuyển nhạc sĩ. (C) \"one of the best in the community\" nói về doanh nghiệp của người quảng cáo, không phải đài.\n(A) Nó đã hoạt động được mười năm.\n(B) Nó đang tìm nhạc sĩ có kinh nghiệm.\n(C) Nó được bình chọn là đài tốt nhất trong cộng đồng.\n(D) Nó có bộ phận tiếp thị riêng."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Frank Jabati [11:12 A.M.]</b></p><p>Hi, Maxine. I'm running late with this delivery today. Could you contact Ms. Dibello to let her know?</p></div>\n<div class=\"msg\"><p><b>Maxine Larsen [11:13 A.M.]</b></p><p>Sure! I know that she is eager to get those new items. She says she needs to set up her kitchen properly so that she can prepare a special meal tonight. What time do you think you will arrive there?</p></div>\n<div class=\"msg\"><p><b>Frank Jabati [11:15 A.M.]</b></p><p>I'm not sure—the road I was taking was closed for repairs. The detour road has heavy traffic.</p></div>\n<div class=\"msg\"><p><b>Maxine Larsen [11:17 A.M.]</b></p><p>Sorry to hear that. What's your estimate?</p></div>\n<div class=\"msg\"><p><b>Frank Jabati [11:19 A.M.]</b></p><p>Maybe around 1 P.M.</p></div>\n<div class=\"msg\"><p><b>Maxine Larsen [11:20 A.M.]</b></p><p>OK, great. I will get in touch with Ms. Dibello to confirm that she will be home at that time. Then I'll get back to you.</p></div>\n<div class=\"msg\"><p><b>Frank Jabati [11:22 A.M.]</b></p><p>Thanks!</p></div>"],"vi":"Frank Jabati [11:12 sáng]: Chào Maxine. Hôm nay tôi bị trễ với chuyến giao hàng này. Chị có thể liên lạc với cô Dibello để báo cho cô ấy biết không?\n\nMaxine Larsen [11:13 sáng]: Được chứ! Tôi biết cô ấy rất mong nhận được những món đồ mới đó. Cô ấy nói cần lắp đặt nhà bếp cho đàng hoàng để có thể nấu một bữa ăn đặc biệt tối nay. Anh nghĩ mấy giờ anh sẽ đến đó?\n\nFrank Jabati [11:15 sáng]: Tôi không chắc — con đường tôi đang đi bị đóng để sửa chữa. Đường vòng thì kẹt xe nặng.\n\nMaxine Larsen [11:17 sáng]: Tiếc quá. Anh ước tính khoảng mấy giờ?\n\nFrank Jabati [11:19 sáng]: Có lẽ khoảng 1 giờ chiều.\n\nMaxine Larsen [11:20 sáng]: OK, tốt. Tôi sẽ liên lạc với cô Dibello để xác nhận cô ấy có ở nhà vào giờ đó. Rồi tôi sẽ báo lại cho anh.\n\nFrank Jabati [11:22 sáng]: Cảm ơn!","qs":[{"n":151,"q":"What most likely has Ms. Dibello purchased?","qvi":"Cô Dibello nhiều khả năng đã mua gì?","opts":["Linens","Bookshelves","Gardening tools","Appliances"],"ans":"D","xp":"Câu hỏi suy luận. \"She says she needs to set up her kitchen properly so that she can prepare a special meal tonight.\" → cô ấy cần những món đồ mới để lắp đặt nhà bếp và nấu ăn → nhiều khả năng là thiết bị gia dụng (appliances: lò, tủ lạnh, bếp...) → chọn (D).\n(A) Khăn trải, ga giường\n(B) Giá sách\n(C) Dụng cụ làm vườn\n(D) Thiết bị gia dụng"},{"n":152,"q":"At 11:17 A.M., what does Ms. Larsen most likely mean when she writes, \"What's your estimate\"?","qvi":"Lúc 11:17 sáng, cô Larsen nhiều khả năng có ý gì khi viết \"What's your estimate\" (Anh ước tính thế nào)?","opts":["She must verify the distance of a route.","She wants to know how much traffic there is.","She wants to know a delivery time.","She has to calculate a delivery charge."],"ans":"C","xp":"Câu hỏi hàm ý. Trước đó Maxine hỏi \"What time do you think you will arrive there?\", Frank trả lời không chắc vì kẹt đường. Maxine hỏi lại \"What's your estimate?\" và Frank đáp \"Maybe around 1 P.M.\" → cô muốn biết giờ giao hàng dự kiến → chọn (C).\n(A) Cô ấy phải xác minh khoảng cách của một tuyến đường.\n(B) Cô ấy muốn biết giao thông đông đến mức nào.\n(C) Cô ấy muốn biết thời gian giao hàng.\n(D) Cô ấy phải tính phí giao hàng."}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Janet Hubschmann</p><p><b>From:</b> customerservice@readymadeofficesupplies.net</p><p><b>Date:</b> September 3</p><p><b>Subject:</b> Thank you</p></div>\n<p>Dear Ms. Hubschmann,</p>\n<p>We here at Readymade Office Supplies are excited to welcome you to our Customers Count rewards program. Your account number 41120 is now registered.</p>\n<p>Be sure to enter your account number to earn points on all your purchases from our Web site. You will earn one point for every dollar you spend on qualifying purchases. Redeem your points on your account page for rewards, including free two-day expedited shipping, special discounts, and more. You can still order via mail from our print catalog, over the telephone from one of our helpful representatives, or by visiting our retail locations across the United States and Canada. However, those purchases do not currently qualify for the rewards program.</p>\n<p>Have questions? Please visit https://www.readymadeofficesupplies.net/customerservice.</p>"],"vi":"Người nhận: Janet Hubschmann\nNgười gửi: customerservice@readymadeofficesupplies.net\nNgày: 3 tháng 9\nTiêu đề: Cảm ơn\n\nKính gửi cô Hubschmann,\n\nChúng tôi tại Readymade Office Supplies rất vui mừng chào đón cô tham gia chương trình tích điểm Customers Count. Tài khoản số 41120 của cô hiện đã được đăng ký.\n\nHãy nhớ nhập số tài khoản để tích điểm cho mọi đơn hàng mua trên trang web của chúng tôi. Cô sẽ nhận được một điểm cho mỗi đô la chi tiêu cho các đơn hàng đủ điều kiện. Hãy đổi điểm trên trang tài khoản để nhận phần thưởng, bao gồm giao hàng nhanh hai ngày miễn phí, các ưu đãi giảm giá đặc biệt và nhiều hơn nữa. Cô vẫn có thể đặt hàng qua thư từ danh mục in, qua điện thoại với một trong những nhân viên nhiệt tình của chúng tôi, hoặc đến các cửa hàng bán lẻ của chúng tôi trên khắp Hoa Kỳ và Canada. Tuy nhiên, những đơn hàng đó hiện chưa đủ điều kiện tham gia chương trình tích điểm.\n\nCó thắc mắc? Vui lòng truy cập https://www.readymadeofficesupplies.net/customerservice.","qs":[{"n":153,"q":"What types of purchases earn reward points?","qvi":"Loại đơn hàng nào được tích điểm thưởng?","opts":["Those made online","Those made by mail","Those made by phone","Those made in a store"],"ans":"A","xp":"Câu hỏi chi tiết. \"Be sure to enter your account number to earn points on all your purchases from our Web site.\" → chỉ mua trên web mới được tích điểm (from our Web site = online) → chọn (A).\n(B), (C), (D): đặt qua thư, điện thoại, tại cửa hàng \"do not currently qualify for the rewards program\".\n(A) Đơn mua trực tuyến\n(B) Đơn mua qua thư\n(C) Đơn mua qua điện thoại\n(D) Đơn mua tại cửa hàng"},{"n":154,"q":"What is a benefit of the program?","qvi":"Một lợi ích của chương trình là gì?","opts":["Invitations to retail events","Free samples","Faster shipping","Extended product warranties"],"ans":"C","xp":"Câu hỏi chi tiết. \"Redeem your points ... for rewards, including free two-day expedited shipping, special discounts, and more.\" → expedited shipping (giao hàng nhanh) = Faster shipping → chọn (C).\n(A) Lời mời tham dự sự kiện bán lẻ\n(B) Hàng mẫu miễn phí\n(C) Giao hàng nhanh hơn\n(D) Bảo hành sản phẩm kéo dài"}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following letter.","passages":["<p>Native Plant Society Headquarters<br>161 Sussex Street<br>Sydney, NSW 2001</p>\n<p>15 April</p>\n<p>Yasmine Harabi<br>247 Kooljak Road<br>Perth, Western Australia 6280</p>\n<p>Membership number 4290</p>\n<p>Dear Ms. Harabi,</p>\n<p>Thank you for your continued support as a society member. Given your recent move, your membership has been transferred to the chapter located in the city of Perth. We will be mailing a replacement member identification card within a few days.</p>\n<p>Unlike the chapter in the city of Canberra, the Perth branch meets the first Saturday of every month, so your next meeting will be in three weeks. If you have any questions, please contact us weekdays between 8:00 a.m. and 4:00 p.m. at (08) 5555 0145.</p>\n<p>Sincerely,</p>\n<p><i>Leticia Davis</i><br>Leticia Davis<br>Membership Department</p>"],"vi":"Trụ sở Hội Thực vật Bản địa\n161 Sussex Street\nSydney, NSW 2001\n\nNgày 15 tháng 4\n\nYasmine Harabi\n247 Kooljak Road\nPerth, Tây Úc 6280\n\nMã số hội viên 4290\n\nKính gửi cô Harabi,\n\nCảm ơn cô đã tiếp tục ủng hộ với tư cách là hội viên. Do cô mới chuyển nhà, tư cách hội viên của cô đã được chuyển sang chi hội ở thành phố Perth. Chúng tôi sẽ gửi qua bưu điện thẻ hội viên thay thế trong vòng vài ngày.\n\nKhác với chi hội ở thành phố Canberra, chi nhánh Perth họp vào thứ Bảy đầu tiên của mỗi tháng, vì vậy buổi họp tiếp theo của cô sẽ diễn ra sau ba tuần nữa. Nếu có bất kỳ thắc mắc nào, vui lòng liên hệ chúng tôi vào các ngày trong tuần từ 8 giờ sáng đến 4 giờ chiều theo số (08) 5555 0145.\n\nTrân trọng,\nLeticia Davis\nPhòng Hội viên","qs":[{"n":155,"q":"What is the purpose of the letter?","qvi":"Mục đích của lá thư là gì?","opts":["To announce a special event","To explain changes based on a relocation","To propose a new meeting time","To request updated contact information"],"ans":"B","xp":"Câu hỏi mục đích. \"Given your recent move, your membership has been transferred to the chapter located in the city of Perth. We will be mailing a replacement member identification card...\" → thư giải thích những thay đổi (chuyển chi hội, thẻ mới, lịch họp mới) do cô Harabi chuyển nhà (recent move = relocation) → chọn (B).\n(C) Sai: lịch họp được thông báo, không phải đề xuất.\n(A) Thông báo một sự kiện đặc biệt\n(B) Giải thích những thay đổi do việc chuyển chỗ ở\n(C) Đề xuất thời gian họp mới\n(D) Yêu cầu cập nhật thông tin liên lạc"},{"n":156,"q":"What is suggested about the city of Canberra?","qvi":"Điều gì được ngụ ý về thành phố Canberra?","opts":["It is famous for its many gardens.","It houses the headquarters of Ms. Davis' organization.","It is where Ms. Harabi previously lived.","It is home to some of Australia's rarest plants."],"ans":"C","xp":"Câu hỏi suy luận. Cô Harabi vừa chuyển nhà và được chuyển sang chi hội Perth; thư so sánh: \"Unlike the chapter in the city of Canberra, the Perth branch meets the first Saturday of every month\" → việc so sánh với Canberra cho thấy đó là chi hội cũ của cô, tức nơi cô sống trước đây → chọn (C).\n(B) Sai: trụ sở ở Sydney (\"Native Plant Society Headquarters ... Sydney\").\n(A) Nó nổi tiếng với nhiều khu vườn.\n(B) Nó là nơi đặt trụ sở của tổ chức của cô Davis.\n(C) Đó là nơi cô Harabi từng sống.\n(D) Đó là nơi có một số loài thực vật quý hiếm nhất nước Úc."},{"n":157,"q":"What can be concluded about the Native Plant Society?","qvi":"Có thể kết luận gì về Hội Thực vật Bản địa?","opts":["It is under new leadership.","Its membership is growing.","It is raising membership dues.","Its chapters hold monthly meetings."],"ans":"D","xp":"Câu hỏi suy luận. \"the Perth branch meets the first Saturday of every month, so your next meeting will be in three weeks\" → các chi hội của hội có tổ chức họp hằng tháng (every month = monthly) → chọn (D). Câu \"Unlike the chapter in ... Canberra\" chỉ cho thấy ngày họp khác nhau giữa các chi hội.\n(A), (B), (C): ban lãnh đạo mới, số hội viên tăng, tăng hội phí đều không được nhắc đến.\n(A) Nó có ban lãnh đạo mới.\n(B) Số hội viên của nó đang tăng.\n(C) Nó đang tăng hội phí.\n(D) Các chi hội của nó họp hằng tháng."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following Web page.","passages":["<p>https://www.greenroofplus.com</p>\n<table><tr><th>Basics</th><th>Photos</th><th>Resources</th><th>News</th></tr></table>\n<h4>What Are Green Roofs?</h4>\n<p>Green roofs are an energy-saving option for office buildings and homes. A green roof is one that's covered with grasses, flowers, or other plants. It lowers heating and cooling costs while increasing a structure's aesthetic appeal. This Web site is designed for sharing ideas, photos, and resources to create and maintain a green roof.</p>\n<p>Planting a rooftop garden is a rewarding do-it-yourself project, but special waterproofing and other preparations require the services of an experienced contractor. Costs vary widely by region, roof size, and complexity of the garden you want to create. Be sure to get estimates from at least two contractors.</p>\n<p>If your contractor determines that your roof can handle the extra weight of soil, plants, and irrigation, ask about the project's timeline. Small, simple rooftop gardens may take only one week to complete.</p>"],"vi":"https://www.greenroofplus.com\nCơ bản | Hình ảnh | Tài nguyên | Tin tức\n\nMái nhà xanh là gì?\n\nMái nhà xanh là một lựa chọn tiết kiệm năng lượng cho các tòa nhà văn phòng và nhà ở. Mái nhà xanh là mái được phủ cỏ, hoa hoặc các loại cây khác. Nó giúp giảm chi phí sưởi ấm và làm mát, đồng thời làm tăng vẻ đẹp thẩm mỹ của công trình. Trang web này được thiết kế để chia sẻ ý tưởng, hình ảnh và tài nguyên nhằm tạo ra và duy trì một mái nhà xanh.\n\nTrồng một khu vườn trên mái là một dự án tự làm đầy thú vị, nhưng việc chống thấm đặc biệt và các khâu chuẩn bị khác cần đến dịch vụ của một nhà thầu có kinh nghiệm. Chi phí dao động rất nhiều tùy theo khu vực, kích thước mái và độ phức tạp của khu vườn bạn muốn tạo. Hãy nhớ lấy báo giá từ ít nhất hai nhà thầu.\n\nNếu nhà thầu xác định rằng mái nhà của bạn có thể chịu được trọng lượng tăng thêm của đất, cây và hệ thống tưới, hãy hỏi về tiến độ của dự án. Những khu vườn trên mái nhỏ và đơn giản có thể chỉ mất một tuần để hoàn thành.","qs":[{"n":158,"q":"According to the Web page, what can visitors to the Web site do?","qvi":"Theo trang web, người truy cập trang web có thể làm gì?","opts":["Discuss how to create a garden","Learn how to maximize vegetable production","Seek advice about landscaping problems","Help contractors calculate costs"],"ans":"A","xp":"Câu hỏi chi tiết. \"This Web site is designed for sharing ideas, photos, and resources to create and maintain a green roof.\" → người dùng chia sẻ ý tưởng về cách tạo mái nhà xanh (một khu vườn trên mái) → \"Discuss how to create a garden\" → chọn (A).\n(A) Thảo luận cách tạo một khu vườn\n(B) Học cách tối đa hóa sản lượng rau\n(C) Tìm lời khuyên về các vấn đề cảnh quan\n(D) Giúp nhà thầu tính toán chi phí"},{"n":159,"q":"What is NOT mentioned about green roofs?","qvi":"Điều gì KHÔNG được nhắc đến về mái nhà xanh?","opts":["They decrease energy bills.","They remove pollution from the air.","They make a structure more beautiful.","They can be installed on commercial and residential buildings."],"ans":"B","xp":"Câu hỏi NOT. (A) có: \"energy-saving option\", \"lowers heating and cooling costs\". (C) có: \"increasing a structure's aesthetic appeal\". (D) có: \"for office buildings and homes\" (văn phòng = thương mại, nhà ở = dân cư). Việc lọc ô nhiễm không khí không được nhắc → chọn (B).\n(A) Chúng giảm hóa đơn năng lượng.\n(B) Chúng loại bỏ ô nhiễm khỏi không khí.\n(C) Chúng làm công trình đẹp hơn.\n(D) Chúng có thể được lắp đặt trên các tòa nhà thương mại và nhà ở."},{"n":160,"q":"In paragraph 3, line 1, the word \"handle\" is closest in meaning to","qvi":"Ở đoạn 3, dòng 1, từ \"handle\" gần nghĩa nhất với","opts":["touch","control","deliver","support"],"ans":"D","xp":"Câu hỏi đồng nghĩa. \"your roof can handle the extra weight of soil, plants, and irrigation\" → mái nhà có thể chịu được (đỡ được) trọng lượng tăng thêm → handle = support (chịu, đỡ) → chọn (D).\n(A) chạm vào\n(B) kiểm soát\n(C) giao, chuyển\n(D) chịu đựng, nâng đỡ"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following advertisement.","passages":["<p>Martino Technical has been providing live sound-mixing services for more than 30 years. We use the latest technology to produce the best sound.</p>\n<p>The majority of our clients are heavy-metal and classic-rock musicians. Before they go on tour, we rehearse with them to ensure that the sounds are perfectly blended and balanced. In addition, we create recordings for them that they can post on social media to promote their shows.</p>\n<p>Our sound-mixing engineers are known for their experience and professionalism and have an impressive track record working on tours worldwide. They have worked with many popular music groups, including The Peakes, Firebrand, and Cellar Cats, and make bands sound just as good during live performances as they do on their records.</p>\n<p>Contact us by e-mailing information@martinotechnical.ie.</p>"],"vi":"Martino Technical đã cung cấp dịch vụ phối âm trực tiếp (live) hơn 30 năm. Chúng tôi sử dụng công nghệ mới nhất để tạo ra âm thanh tốt nhất.\n\nPhần lớn khách hàng của chúng tôi là các nhạc sĩ heavy-metal và rock cổ điển. Trước khi họ đi lưu diễn, chúng tôi tập dượt cùng họ để đảm bảo âm thanh được hòa trộn và cân bằng hoàn hảo. Ngoài ra, chúng tôi còn thực hiện các bản thu âm để họ đăng lên mạng xã hội nhằm quảng bá cho các buổi diễn của mình.\n\nCác kỹ sư phối âm của chúng tôi nổi tiếng về kinh nghiệm và sự chuyên nghiệp, đồng thời có thành tích ấn tượng khi làm việc cho các chuyến lưu diễn khắp thế giới. Họ đã làm việc với nhiều nhóm nhạc nổi tiếng, bao gồm The Peakes, Firebrand và Cellar Cats, và giúp các ban nhạc nghe hay khi biểu diễn trực tiếp không kém gì trong đĩa thu âm.\n\nHãy liên hệ với chúng tôi qua e-mail information@martinotechnical.ie.","qs":[{"n":161,"q":"What is indicated about Martino Technical?","qvi":"Điều gì được nêu về Martino Technical?","opts":["It acquires most clients through social media.","It was founded over 30 years ago.","It has received many industry awards.","It has offices throughout the world."],"ans":"B","xp":"Câu hỏi chi tiết. \"Martino Technical has been providing live sound-mixing services for more than 30 years.\" → công ty đã hoạt động hơn 30 năm, tức được thành lập cách đây hơn 30 năm → chọn (B).\n(A) Mạng xã hội chỉ dùng để quảng bá buổi diễn của khách. (D) \"tours worldwide\" là các chuyến lưu diễn, không phải văn phòng. (C) không nhắc giải thưởng.\n(A) Nó có được hầu hết khách hàng qua mạng xã hội.\n(B) Nó được thành lập hơn 30 năm trước.\n(C) Nó đã nhận nhiều giải thưởng trong ngành.\n(D) Nó có văn phòng khắp thế giới."},{"n":162,"q":"The word \"promote\" in paragraph 2, line 4, is closest in meaning to","qvi":"Từ \"promote\" ở đoạn 2, dòng 4, gần nghĩa nhất với","opts":["encourage","schedule","publicize","advance"],"ans":"C","xp":"Câu hỏi đồng nghĩa. \"recordings for them that they can post on social media to promote their shows\" → đăng lên mạng xã hội để quảng bá buổi diễn → promote = publicize (quảng bá, làm cho nhiều người biết) → chọn (C).\n(D) advance cũng có nghĩa \"thăng tiến\" như promote trong \"promote an employee\", không hợp ngữ cảnh này.\n(A) khuyến khích\n(B) lên lịch\n(C) quảng bá\n(D) thúc đẩy, tiến lên"},{"n":163,"q":"What is NOT stated about the live sound-mixing engineers?","qvi":"Điều gì KHÔNG được nêu về các kỹ sư phối âm trực tiếp?","opts":["They create promotional materials.","They have considerable expertise.","They travel abroad frequently.","They have degrees in music."],"ans":"D","xp":"Câu hỏi NOT. (A) có: \"we create recordings for them that they can post on social media to promote their shows\" (tài liệu quảng bá). (B) có: \"known for their experience and professionalism\". (C) có: \"an impressive track record working on tours worldwide\". Bằng cấp âm nhạc không được nhắc → chọn (D).\n(A) Họ tạo tài liệu quảng bá.\n(B) Họ có chuyên môn đáng kể.\n(C) Họ thường xuyên ra nước ngoài.\n(D) Họ có bằng cấp về âm nhạc."}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Employees &lt;employees@bonahoomenterprises.com&gt;</p><p><b>From:</b> Marcia Noh &lt;mnoh@bonahoomenterprises.com&gt;</p><p><b>Date:</b> November 14</p><p><b>Subject:</b> November 28 event</p></div>\n<p>Dear all,</p>\n<p>On the evening of November 28, there will be a formal dinner to honor our company president and founder, Mr. Bonahoom. At the dinner, we will express our appreciation for his leadership over these past twenty years in making Bonahoom Enterprises a successful company and a great place to work. — <span class=\"pos\">[1]</span> —.</p>\n<p>This event will be held in the private banquet room at Chez Bistro and is intended to be a surprise, so please avoid mentioning it to him. Those few who are involved with the setup will arrive at 5 P.M. All other attendees should come no later than 6:15 P.M. in anticipation of Mr. Bonahoom's arrival at 6:30 P.M. We expect the celebration to wrap up no later than 8 P.M. — <span class=\"pos\">[2]</span> —.</p>\n<p>There is no need to bring a gift. — <span class=\"pos\">[3]</span> —. We do ask, though, that you find time this week to sign a card for him. It can be found at Ms. Mueller's desk, inside an envelope marked \"November 28.\"</p>\n<p>Finally, you are welcome to bring one guest with you to the event if you wish. — <span class=\"pos\">[4]</span> —. Kindly RSVP to this e-mail so we can get a complete count of the number of attendees.</p>\n<p>All the best,</p>\n<p>Marcia Noh</p>"],"vi":"Người nhận: Nhân viên <employees@bonahoomenterprises.com>\nNgười gửi: Marcia Noh <mnoh@bonahoomenterprises.com>\nNgày: 14 tháng 11\nTiêu đề: Sự kiện ngày 28 tháng 11\n\nGửi mọi người,\n\nVào tối ngày 28 tháng 11 sẽ có một bữa tiệc tối trang trọng để vinh danh chủ tịch kiêm nhà sáng lập công ty, ông Bonahoom. Tại bữa tiệc, chúng ta sẽ bày tỏ lòng biết ơn đối với sự lãnh đạo của ông trong hai mươi năm qua, giúp Bonahoom Enterprises trở thành một công ty thành công và là nơi làm việc tuyệt vời. — [1] —.\n\nSự kiện sẽ được tổ chức tại phòng tiệc riêng của Chez Bistro và dự định là một bất ngờ, vì vậy xin đừng nhắc đến nó với ông ấy. Một số ít người tham gia khâu chuẩn bị sẽ đến lúc 5 giờ chiều. Tất cả những người tham dự khác nên đến không muộn hơn 6 giờ 15 chiều để đón ông Bonahoom đến lúc 6 giờ 30. Chúng tôi dự kiến buổi tiệc sẽ kết thúc không muộn hơn 8 giờ tối. — [2] —.\n\nKhông cần mang quà. — [3] —. Tuy nhiên, chúng tôi đề nghị mọi người dành thời gian trong tuần này để ký vào một tấm thiệp gửi ông ấy. Tấm thiệp được để ở bàn của cô Mueller, trong một phong bì ghi \"November 28\".\n\nCuối cùng, mọi người có thể dẫn theo một khách mời đến sự kiện nếu muốn. — [4] —. Vui lòng phản hồi (RSVP) e-mail này để chúng tôi nắm được tổng số người tham dự.\n\nThân ái,\nMarcia Noh","qs":[{"n":164,"q":"What is the main purpose of the e-mail?","qvi":"Mục đích chính của e-mail là gì?","opts":["To ask staff to sign up to give speeches at a celebration","To find people willing to bring various items to a dinner","To invite workers to a surprise party","To look for volunteers to help plan an event"],"ans":"C","xp":"Câu hỏi mục đích. E-mail gửi toàn thể nhân viên: \"there will be a formal dinner to honor ... Mr. Bonahoom\", \"is intended to be a surprise\", kèm giờ đến và yêu cầu RSVP → mời nhân viên dự một bữa tiệc bất ngờ → chọn (C).\n(B) Sai: \"There is no need to bring a gift.\" (A), (D) không nhắc đến phát biểu hay tìm tình nguyện viên.\n(A) Đề nghị nhân viên đăng ký phát biểu tại buổi lễ\n(B) Tìm người sẵn lòng mang nhiều món đồ đến bữa tiệc\n(C) Mời nhân viên đến một bữa tiệc bất ngờ\n(D) Tìm tình nguyện viên giúp lên kế hoạch sự kiện"},{"n":165,"q":"According to the e-mail, when are most people expected to arrive?","qvi":"Theo e-mail, hầu hết mọi người được dự kiến đến lúc mấy giờ?","opts":["At 5:00 P.M.","At 6:15 P.M.","At 6:30 P.M.","At 8:00 P.M."],"ans":"B","xp":"Câu hỏi chi tiết. \"Those few who are involved with the setup will arrive at 5 P.M. All other attendees should come no later than 6:15 P.M.\" → chỉ vài người đến lúc 5 giờ, còn tất cả những người khác (đa số) đến trước 6:15 → chọn (B).\n(C) 6:30 là giờ ông Bonahoom đến; (D) 8:00 là giờ kết thúc.\n(A) Lúc 5 giờ chiều\n(B) Lúc 6 giờ 15 chiều\n(C) Lúc 6 giờ 30 chiều\n(D) Lúc 8 giờ tối"},{"n":166,"q":"What should people do if they want to sign a card?","qvi":"Mọi người nên làm gì nếu muốn ký thiệp?","opts":["They should request it from Mr. Bonahoom.","They should e-mail Ms. Noh.","They should wait for it to be passed around the office.","They should go to Ms. Mueller's desk."],"ans":"D","xp":"Câu hỏi chi tiết. \"sign a card for him. It can be found at Ms. Mueller's desk, inside an envelope marked 'November 28.'\" → đến bàn cô Mueller để ký → chọn (D).\n(A) Họ nên xin nó từ ông Bonahoom.\n(B) Họ nên gửi e-mail cho cô Noh.\n(C) Họ nên đợi nó được chuyền quanh văn phòng.\n(D) Họ nên đến bàn của cô Mueller."},{"n":167,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"The senior staff will be presenting a commemorative plaque on behalf of the whole office.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào trong [1], [2], [3], [4]?\n\"Ban lãnh đạo cấp cao sẽ trao một tấm bảng kỷ niệm thay mặt cho toàn thể văn phòng.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Câu hỏi điền câu. Vị trí [3] đứng ngay sau \"There is no need to bring a gift.\" → câu chèn giải thích lý do không cần mang quà: lãnh đạo cấp cao sẽ trao bảng kỷ niệm \"on behalf of the whole office\" (thay mặt mọi người) rồi. Câu sau \"We do ask, though, that you ... sign a card\" (Tuy nhiên hãy ký thiệp) cũng nối mạch tự nhiên → chọn (C).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Colin Wikander (10:23 A.M.)</b></p><p>I have reviewed the draft of the new client questionnaire, and it looks great overall. I would make the question about bookkeeping strategies more open-ended, though. As written, it may lead respondents to give simple yes or no answers.</p></div>\n<div class=\"msg\"><p><b>Midori Sakai (10:24 A.M.)</b></p><p>That's a good point. We'll need to fix that. I also want to add a couple of questions about how financial and tax reports have been handled in the past.</p></div>\n<div class=\"msg\"><p><b>Ela Hamidah (10:24 A.M.)</b></p><p>I could look at the bookkeeping question to see what I can come up with.</p></div>\n<div class=\"msg\"><p><b>Colin Wikander (10:25 A.M.)</b></p><p>Well, it's four pages already.</p></div>\n<div class=\"msg\"><p><b>Midori Sakai (10:27 A.M.)</b></p><p>That's true. I'll just wait for Ela's revision of the third question. Then Jack Neligan can put a draft of the form up on our Web site.</p></div>\n<div class=\"msg\"><p><b>Colin Wikander (10:28 A.M.)</b></p><p>Is it true that we are not planning to collect any paper forms?</p></div>\n<div class=\"msg\"><p><b>Midori Sakai (10:30 A.M.)</b></p><p>We might do that, but digital collection is preferable to avoid the lag time of waiting for our clients to print, fill out, and scan the forms to send them back.</p></div>"],"vi":"Colin Wikander (10:23 sáng): Tôi đã xem bản nháp bảng câu hỏi mới dành cho khách hàng, nhìn chung trông rất tốt. Tuy nhiên, tôi sẽ sửa câu hỏi về chiến lược ghi sổ kế toán cho mở hơn. Như cách viết hiện tại, nó có thể khiến người trả lời chỉ đưa ra câu trả lời đơn giản là có hoặc không.\n\nMidori Sakai (10:24 sáng): Ý hay đấy. Chúng ta sẽ cần sửa chỗ đó. Tôi cũng muốn thêm vài câu hỏi về việc các báo cáo tài chính và thuế đã được xử lý như thế nào trước đây.\n\nEla Hamidah (10:24 sáng): Tôi có thể xem câu hỏi về ghi sổ kế toán để xem mình nghĩ ra được gì.\n\nColin Wikander (10:25 sáng): Chà, nó đã dài bốn trang rồi.\n\nMidori Sakai (10:27 sáng): Đúng thật. Vậy tôi sẽ chỉ chờ bản sửa câu hỏi thứ ba của Ela. Sau đó Jack Neligan có thể đăng bản nháp của mẫu đơn lên trang web của chúng ta.\n\nColin Wikander (10:28 sáng): Có đúng là chúng ta không định thu mẫu đơn giấy nào không?\n\nMidori Sakai (10:30 sáng): Có thể chúng ta sẽ thu, nhưng thu bản kỹ thuật số thì tốt hơn để tránh mất thời gian chờ khách hàng in ra, điền, rồi quét lại để gửi về.","qs":[{"n":168,"q":"What type of company do the writers most likely work for?","qvi":"Những người viết nhiều khả năng làm việc cho loại công ty nào?","opts":["Publishing","Accounting","Retail","Design"],"ans":"B","xp":"Câu hỏi suy luận. Bảng câu hỏi khách hàng hỏi về \"bookkeeping strategies\" (chiến lược ghi sổ kế toán) và \"how financial and tax reports have been handled\" (báo cáo tài chính và thuế) → công ty kế toán → chọn (B).\n(A) Xuất bản\n(B) Kế toán\n(C) Bán lẻ\n(D) Thiết kế"},{"n":169,"q":"What does Mr. Wikander suggest about a question?","qvi":"Ông Wikander gợi ý điều gì về một câu hỏi?","opts":["It is mislabeled.","It is difficult to read.","It should be reworded.","It should be made optional."],"ans":"C","xp":"Câu hỏi chi tiết. \"I would make the question about bookkeeping strategies more open-ended, though. As written, it may lead respondents to give simple yes or no answers.\" → ông muốn viết lại câu hỏi theo dạng mở hơn → reworded (diễn đạt lại) → chọn (C).\n(A) Nó bị gắn nhãn sai.\n(B) Nó khó đọc.\n(C) Nó nên được diễn đạt lại.\n(D) Nó nên được chuyển thành không bắt buộc."},{"n":170,"q":"At 10:25 A.M., what does Mr. Wikander most likely mean when he writes, \"Well, it's four pages already\"?","qvi":"Lúc 10:25 sáng, ông Wikander nhiều khả năng có ý gì khi viết \"Well, it's four pages already\" (Chà, nó đã dài bốn trang rồi)?","opts":["He is surprised by the long answers clients gave.","He is impressed with how quickly the questionnaire is coming along.","He thinks information in the first four pages should be cut out.","He thinks the questionnaire should not be any longer."],"ans":"D","xp":"Câu hỏi hàm ý. Ngay trước đó Midori nói \"I also want to add a couple of questions...\". Colin đáp \"it's four pages already\" → ngụ ý bảng câu hỏi đã dài rồi, không nên thêm nữa. Midori đồng ý \"That's true. I'll just wait for Ela's revision\" (tức bỏ ý định thêm câu hỏi) → chọn (D).\n(A) Ông ấy ngạc nhiên vì khách hàng trả lời dài.\n(B) Ông ấy ấn tượng vì bảng câu hỏi tiến triển nhanh.\n(C) Ông ấy nghĩ nên cắt bỏ thông tin ở bốn trang đầu.\n(D) Ông ấy nghĩ bảng câu hỏi không nên dài thêm nữa."},{"n":171,"q":"Why does Ms. Sakai think that paperless forms will be preferable?","qvi":"Tại sao cô Sakai cho rằng mẫu đơn không dùng giấy sẽ tốt hơn?","opts":["They allow for faster data collection.","They reduce the number of errors.","They are good for the environment.","They do not take up space in an office."],"ans":"A","xp":"Câu hỏi chi tiết. \"digital collection is preferable to avoid the lag time of waiting for our clients to print, fill out, and scan the forms to send them back\" → tránh thời gian chờ đợi = thu thập dữ liệu nhanh hơn → chọn (A).\n(A) Chúng giúp thu thập dữ liệu nhanh hơn.\n(B) Chúng giảm số lỗi.\n(C) Chúng tốt cho môi trường.\n(D) Chúng không chiếm chỗ trong văn phòng."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following post on a Web site.","passages":["<p>https://www.trehospitalityassociation.com/discussion/tunisia</p>\n<p>I have been a member of the TRE Hospitality Association for many years, but until now, I have posted messages only on the Greece and Egypt forums. — <span class=\"pos\">[1]</span> —. This is my first post on the Tunisia forum.</p>\n<p>I am looking for recommendations for a janitorial service on the island of Djerba. My company is opening a hotel there. Our hotel will offer 80 rooms with two restaurants on-site. — <span class=\"pos\">[2]</span> —. I would like to contract with a company that can provide about four full-time custodial workers and housekeepers, plus an additional five workers on an as-needed basis for large events on our property. — <span class=\"pos\">[3]</span> —.</p>\n<p>I may have met some of you previously at one of our hospitality conferences. If so, please remind me. In fact, I attended the most recent one in Rabat. — <span class=\"pos\">[4]</span> —. I would like to reconnect!</p>\n<p>John Karikas, Director of Development</p>\n<p>Synecdoche Hotel Group</p>"],"vi":"https://www.trehospitalityassociation.com/discussion/tunisia\n\nTôi đã là thành viên của Hiệp hội Khách sạn – Nhà hàng TRE trong nhiều năm, nhưng cho đến nay tôi chỉ đăng bài trên diễn đàn Hy Lạp và Ai Cập. — [1] —. Đây là bài đăng đầu tiên của tôi trên diễn đàn Tunisia.\n\nTôi đang tìm lời giới thiệu về một dịch vụ vệ sinh trên đảo Djerba. Công ty tôi sắp khai trương một khách sạn ở đó. Khách sạn của chúng tôi sẽ có 80 phòng cùng hai nhà hàng ngay trong khuôn viên. — [2] —. Tôi muốn ký hợp đồng với một công ty có thể cung cấp khoảng bốn nhân viên vệ sinh và dọn phòng toàn thời gian, cộng thêm năm nhân viên làm theo nhu cầu cho các sự kiện lớn tại khách sạn. — [3] —.\n\nCó thể trước đây tôi đã gặp một số bạn tại một trong các hội nghị ngành khách sạn của chúng ta. Nếu vậy, xin hãy nhắc tôi nhớ. Thật ra, tôi đã tham dự hội nghị gần đây nhất ở Rabat. — [4] —. Tôi rất muốn kết nối lại!\n\nJohn Karikas, Giám đốc Phát triển\nTập đoàn Khách sạn Synecdoche","qs":[{"n":172,"q":"Why did Mr. Karikas write the post?","qvi":"Tại sao ông Karikas viết bài đăng này?","opts":["To promote a job fair","To request referrals to a service provider","To recommend a tourist destination","To invite colleagues to a grand opening"],"ans":"B","xp":"Câu hỏi mục đích. \"I am looking for recommendations for a janitorial service on the island of Djerba.\" → ông nhờ mọi người giới thiệu một công ty dịch vụ vệ sinh (recommendations = referrals; janitorial service = a service provider) → chọn (B).\n(D) Sai: có nhắc khách sạn sắp mở nhưng không mời dự lễ khai trương.\n(A) Quảng bá một hội chợ việc làm\n(B) Nhờ giới thiệu một nhà cung cấp dịch vụ\n(C) Giới thiệu một điểm du lịch\n(D) Mời đồng nghiệp dự lễ khai trương"},{"n":173,"q":"What is suggested about the TRE Hospitality Association?","qvi":"Điều gì được ngụ ý về Hiệp hội Khách sạn – Nhà hàng TRE?","opts":["It is based in Egypt.","It was recently expanded to include hotel owners.","It is an international organization.","It offers janitorial services."],"ans":"C","xp":"Câu hỏi suy luận. Hiệp hội có các diễn đàn cho nhiều quốc gia: \"the Greece and Egypt forums\", \"the Tunisia forum\", và hội nghị được tổ chức ở Rabat (Ma-rốc) → đây là tổ chức quốc tế → chọn (C).\n(A) Có diễn đàn Ai Cập nhưng không nói trụ sở ở đó. (D) Ông đang tìm dịch vụ vệ sinh, hiệp hội không cung cấp.\n(A) Nó có trụ sở ở Ai Cập.\n(B) Gần đây nó đã mở rộng để kết nạp các chủ khách sạn.\n(C) Nó là một tổ chức quốc tế.\n(D) Nó cung cấp dịch vụ vệ sinh."},{"n":174,"q":"What is indicated about Mr. Karikas?","qvi":"Điều gì được nêu về ông Karikas?","opts":["He teaches a hospitality course.","He lives in Rabat.","He is a former restaurant owner.","He attended at least one hospitality conference."],"ans":"D","xp":"Câu hỏi chi tiết. \"In fact, I attended the most recent one in Rabat.\" (one = one of our hospitality conferences) → ông đã dự ít nhất một hội nghị ngành khách sạn → chọn (D).\n(B) Sai: ông chỉ dự hội nghị ở Rabat, không nói sống ở đó.\n(A) Ông ấy dạy một khóa học về ngành khách sạn.\n(B) Ông ấy sống ở Rabat.\n(C) Ông ấy từng là chủ nhà hàng.\n(D) Ông ấy đã tham dự ít nhất một hội nghị ngành khách sạn."},{"n":175,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"It will also have a large meeting room.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào trong [1], [2], [3], [4]?\n\"Nó cũng sẽ có một phòng họp lớn.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu hỏi điền câu. Câu chèn có \"It\" và \"also\" → phải đứng sau câu mô tả cơ sở vật chất của khách sạn. Vị trí [2] ngay sau \"Our hotel will offer 80 rooms with two restaurants on-site.\" → \"It\" = our hotel, \"also\" bổ sung thêm phòng họp lớn. Phòng họp lớn cũng giải thích vì sao sau đó cần thêm nhân viên \"for large events\" → chọn (B).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mails.","passages":["<div class=\"hdr\"><p><b>To:</b> Manuel Torres &lt;m.torres@opalmail.co.uk&gt;</p><p><b>From:</b> Anya Patel &lt;a.patel@support.harlund.co.uk&gt;</p><p><b>Date:</b> 3 May</p><p><b>Subject:</b> Auto insurance</p></div><p>Dear Mr. Torres,</p><p>Welcome to Harlund Ltd. We are pleased to provide you with comprehensive automobile insurance for your new vehicle. We have received your first payment of £36.00, and your coverage is now in effect. Your policy number is M413927.</p><p>Your billing schedule is based on an annual premium of £432.00. The remaining payments of £36.00 per month are due on the fifteenth day of each month starting in June.</p><p>You can visit us online at www.harlund.co.uk to pay bills and manage your policy. Our Web site offers easy options for managing your account information and for making payments with scheduled transfers directly from your bank.</p><p>Should you have any questions or wish to change your policy, call the customer support centre at 020 7946 0516. In the event of a vehicle incident, please contact an agent as soon as possible at 020 7946 0520. Be sure to have your policy number at hand. Thank you for trusting Harlund Ltd. We look forward to providing you with superior service.</p><p>Best regards,</p><p>Anya Patel, Harlund Ltd. Customer Support Agent</p>","<div class=\"hdr\"><p><b>To:</b> Anya Patel &lt;a.patel@support.harlund.co.uk&gt;</p><p><b>From:</b> Manuel Torres &lt;m.torres@opalmail.co.uk&gt;</p><p><b>Date:</b> 4 May</p><p><b>Subject:</b> RE: Auto insurance</p></div><p>Dear Ms. Patel,</p><p>Thank you for the confirmation. I'm happy to have insurance from a trustworthy company. For your reference, the new car is now registered in my name.</p><p>Although I made the initial payment to you by credit card, I plan to follow the process outlined in your e-mail for future payments.</p><p>I also wanted to let you know that I have not yet received the insurance certificate. I looked for one that I could download from your Web site, but I could not find anything. Could you please send me a copy of the certificate?</p><p>Sincerely,</p><p>Manuel Torres</p>"],"vi":"Người nhận: Manuel Torres <m.torres@opalmail.co.uk>\nNgười gửi: Anya Patel <a.patel@support.harlund.co.uk>\nNgày: 3 tháng 5\nTiêu đề: Bảo hiểm ô tô\n\nKính gửi ông Torres,\n\nChào mừng ông đến với Harlund Ltd. Chúng tôi rất vui được cung cấp cho ông bảo hiểm ô tô toàn diện cho chiếc xe mới của ông. Chúng tôi đã nhận được khoản thanh toán đầu tiên 36,00 bảng Anh của ông, và phạm vi bảo hiểm của ông hiện đã có hiệu lực. Số hợp đồng bảo hiểm của ông là M413927.\n\nLịch thanh toán của ông dựa trên phí bảo hiểm hằng năm là 432,00 bảng. Các khoản thanh toán còn lại 36,00 bảng mỗi tháng đến hạn vào ngày 15 hằng tháng, bắt đầu từ tháng Sáu.\n\nÔng có thể truy cập trực tuyến tại www.harlund.co.uk để thanh toán hóa đơn và quản lý hợp đồng. Trang web của chúng tôi có các lựa chọn dễ dàng để quản lý thông tin tài khoản và thanh toán bằng chuyển khoản định kỳ trực tiếp từ ngân hàng của ông.\n\nNếu ông có bất kỳ câu hỏi nào hoặc muốn thay đổi hợp đồng, hãy gọi trung tâm hỗ trợ khách hàng theo số 020 7946 0516. Trong trường hợp xảy ra sự cố xe, vui lòng liên hệ nhân viên đại lý càng sớm càng tốt theo số 020 7946 0520. Hãy chuẩn bị sẵn số hợp đồng. Cảm ơn ông đã tin tưởng Harlund Ltd. Chúng tôi mong được mang đến cho ông dịch vụ vượt trội.\n\nTrân trọng,\n\nAnya Patel, Nhân viên hỗ trợ khách hàng Harlund Ltd.\n\n---\n\nNgười nhận: Anya Patel\nNgười gửi: Manuel Torres\nNgày: 4 tháng 5\nTiêu đề: Trả lời: Bảo hiểm ô tô\n\nKính gửi bà Patel,\n\nCảm ơn bà đã xác nhận. Tôi rất vui khi có bảo hiểm từ một công ty đáng tin cậy. Xin thông báo để bà tham khảo, chiếc xe mới hiện đã được đăng ký đứng tên tôi.\n\nMặc dù tôi đã thanh toán khoản đầu tiên bằng thẻ tín dụng, tôi dự định sẽ làm theo quy trình nêu trong e-mail của bà cho các lần thanh toán sau.\n\nTôi cũng muốn báo bà biết rằng tôi vẫn chưa nhận được giấy chứng nhận bảo hiểm. Tôi đã tìm một bản có thể tải về từ trang web của quý công ty nhưng không tìm thấy gì. Bà có thể vui lòng gửi cho tôi một bản sao giấy chứng nhận được không?\n\nTrân trọng,\n\nManuel Torres","qs":[{"n":176,"q":"What can be inferred about Mr. Torres?","qvi":"Có thể suy ra điều gì về ông Torres?","opts":["He is moving to a new home.","He recently bought a car.","He will be retiring soon.","He recently opened a bank account."],"ans":"B","xp":"Câu hỏi suy luận. E-mail 1: \"comprehensive automobile insurance for your new vehicle\" (bảo hiểm cho chiếc xe mới của ông) và e-mail 2: \"the new car is now registered in my name\" (xe mới vừa đăng ký đứng tên tôi) → ông Torres vừa mua xe → (B). Các ý về nhà mới, nghỉ hưu, mở tài khoản ngân hàng không được nhắc tới.\n(A) Ông ấy đang chuyển đến nhà mới.\n(B) Ông ấy vừa mua một chiếc ô tô.\n(C) Ông ấy sắp nghỉ hưu.\n(D) Ông ấy vừa mở tài khoản ngân hàng."},{"n":177,"q":"In the first e-mail, the word \"coverage\" in paragraph 1, line 3, is closest in meaning to","qvi":"Trong e-mail thứ nhất, từ \"coverage\" ở đoạn 1, dòng 3 gần nghĩa nhất với","opts":["measurement","information","commentary","protection"],"ans":"D","xp":"Câu hỏi đồng nghĩa. \"your coverage is now in effect\" – trong ngữ cảnh bảo hiểm, coverage là 'phạm vi bảo hiểm / sự bảo vệ' mà hợp đồng mang lại → gần nghĩa nhất với protection (sự bảo vệ) → (D). (Coverage còn có nghĩa 'tin tức đưa tin' – gần với commentary/information – nhưng không hợp ngữ cảnh này.)\n(A) sự đo lường\n(B) thông tin\n(C) bình luận\n(D) sự bảo vệ"},{"n":178,"q":"What does Ms. Patel recommend that Mr. Torres do?","qvi":"Bà Patel khuyên ông Torres làm gì?","opts":["Call an agent if needed","Register at a local office","Place an order promptly","Revise an agreement"],"ans":"A","xp":"Câu hỏi chi tiết. E-mail 1: \"In the event of a vehicle incident, please contact an agent as soon as possible at 020 7946 0520.\" → khi có sự cố (khi cần) thì gọi cho nhân viên đại lý → (A). 'contact an agent' = 'Call an agent'; 'in the event of a vehicle incident' được diễn đạt lại thành 'if needed'.\n(A) Gọi cho nhân viên đại lý nếu cần\n(B) Đăng ký tại văn phòng địa phương\n(C) Đặt hàng ngay\n(D) Sửa đổi một thỏa thuận"},{"n":179,"q":"How does Mr. Torres intend to make future payments?","qvi":"Ông Torres định thanh toán các lần sau bằng cách nào?","opts":["By cash","By credit card","By electronic transfer","By personal check"],"ans":"C","xp":"Câu hỏi liên kết 2 bài. E-mail 2: \"I plan to follow the process outlined in your e-mail for future payments.\" Quy trình trong e-mail 1: \"making payments with scheduled transfers directly from your bank\" qua trang web → thanh toán bằng chuyển khoản điện tử → (C). (B) sai vì thẻ tín dụng chỉ dùng cho lần đầu (\"Although I made the initial payment ... by credit card\").\n(A) Bằng tiền mặt\n(B) Bằng thẻ tín dụng\n(C) Bằng chuyển khoản điện tử\n(D) Bằng séc cá nhân"},{"n":180,"q":"What does Mr. Torres state that he looked for?","qvi":"Ông Torres nói rằng ông đã tìm kiếm cái gì?","opts":["Directions to an office","A document to download","Reviews from customers","Contact information"],"ans":"B","xp":"Câu hỏi chi tiết. E-mail 2: \"I looked for one that I could download from your Web site\" – 'one' ở đây là giấy chứng nhận bảo hiểm (insurance certificate) → một tài liệu để tải về → (B).\n(A) Chỉ đường đến văn phòng\n(B) Một tài liệu để tải về\n(C) Đánh giá từ khách hàng\n(D) Thông tin liên hệ"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following schedule and review.","passages":["<h3>Tour Schedule for Book Launch by Andrew Darr</h3><p>At each appearance, Mr. Darr will read an excerpt from his new novel, <i>Down the Mountainside</i>, followed by a question-and-answer session. Afterward, Mr. Darr will be available to autograph copies of his books.</p><table><tr><th>Venue</th><th>City</th><th>Date</th><th>Time</th></tr><tr><td>Neighbourhood Books</td><td>Toronto, Ontario</td><td>18 May</td><td>6:00 P.M.</td></tr><tr><td>Weinstock Books and Stationery</td><td>Ottawa, Ontario</td><td>27 May</td><td>7:00 P.M.</td></tr><tr><td>Portage Avenue Books</td><td>Winnipeg, Manitoba</td><td>6 June</td><td>6:30 P.M.</td></tr><tr><td>Downtown Books and Café</td><td>Regina, Saskatchewan</td><td>15 June</td><td>7:00 P.M.</td></tr></table>","<p><b>Book Review:</b> <i>Down the Mountainside</i></p><p><b>Reviewer:</b> Camile Lin<br><b>Date:</b> 15 May</p><p>Andrew Darr, the author of the best-selling series about detective Charles Martin, will be visiting our city this week, appearing at Neighbourhood Books to promote his new novel, <i>Down the Mountainside</i>. The new work sees Martin investigating mysterious events at a ski resort in the French Alps.</p><p>Darr's storytelling has come a long way since readers first met Charles Martin in <i>The Doorbell</i>, and this installment is Darr's strongest work to date. Fans of the stories will welcome the return of Darr's wit after a three-year wait, and newcomers to the Martin series are sure to find themselves captivated.</p><p>The story includes the right balance of suspense and humour, with an ending that is unpredictable, even to the most devoted Darr reader. I highly recommend this book to all mystery fans. You won't be disappointed.</p>"],"vi":"Lịch trình tour ra mắt sách của Andrew Darr\n\nTại mỗi buổi xuất hiện, ông Darr sẽ đọc một đoạn trích từ cuốn tiểu thuyết mới của mình, Down the Mountainside, sau đó là phần hỏi đáp. Sau đó, ông Darr sẽ ký tặng lên các cuốn sách của ông.\n\nĐịa điểm – Thành phố – Ngày – Giờ\nNeighbourhood Books – Toronto, Ontario – 18/5 – 6:00 chiều\nWeinstock Books and Stationery – Ottawa, Ontario – 27/5 – 7:00 tối\nPortage Avenue Books – Winnipeg, Manitoba – 6/6 – 6:30 chiều\nDowntown Books and Café – Regina, Saskatchewan – 15/6 – 7:00 tối\n\n---\n\nĐiểm sách: Down the Mountainside\nNgười viết: Camile Lin\nNgày: 15/5\n\nAndrew Darr, tác giả của loạt truyện bán chạy về thám tử Charles Martin, sẽ đến thăm thành phố chúng ta trong tuần này, xuất hiện tại Neighbourhood Books để quảng bá cuốn tiểu thuyết mới, Down the Mountainside. Trong tác phẩm mới, Martin điều tra những sự việc bí ẩn tại một khu nghỉ dưỡng trượt tuyết ở dãy Alps của Pháp.\n\nTài kể chuyện của Darr đã tiến bộ rất nhiều kể từ khi độc giả lần đầu gặp Charles Martin trong The Doorbell, và phần truyện này là tác phẩm hay nhất của Darr cho đến nay. Người hâm mộ loạt truyện sẽ chào đón sự trở lại của lối dí dỏm của Darr sau ba năm chờ đợi, và những người mới đến với loạt truyện Martin chắc chắn sẽ bị cuốn hút.\n\nCâu chuyện có sự cân bằng vừa phải giữa hồi hộp và hài hước, với một cái kết không thể đoán trước, kể cả với độc giả trung thành nhất của Darr. Tôi rất khuyến khích tất cả những người yêu thích truyện trinh thám đọc cuốn sách này. Bạn sẽ không thất vọng.","qs":[{"n":181,"q":"According to the schedule, what is NOT mentioned as an activity for Mr. Darr?","qvi":"Theo lịch trình, hoạt động nào KHÔNG được nhắc đến cho ông Darr?","opts":["Reading from his book","Answering questions","Signing books for individuals","Taking photos with participants"],"ans":"D","xp":"Câu hỏi NOT. Lịch trình: \"Mr. Darr will read an excerpt from his new novel\" → (A) có; \"followed by a question-and-answer session\" → (B) có; \"available to autograph copies of his books\" → (C) có (autograph = ký tặng). Không hề nhắc đến chụp ảnh với người tham dự → chọn (D).\n(A) Đọc trích đoạn sách của mình\n(B) Trả lời câu hỏi\n(C) Ký tặng sách cho từng người\n(D) Chụp ảnh với người tham dự"},{"n":182,"q":"What city is the book reviewer from?","qvi":"Người viết bài điểm sách đến từ thành phố nào?","opts":["Toronto","Ottawa","Winnipeg","Regina"],"ans":"A","xp":"Câu hỏi liên kết 2 bài. Bài điểm sách: Darr \"will be visiting our city this week, appearing at Neighbourhood Books\" (sẽ đến thành phố chúng ta, xuất hiện tại Neighbourhood Books). Theo lịch trình, Neighbourhood Books ở Toronto, Ontario (ngày 18/5 – đúng tuần của bài viết 15/5) → người viết ở Toronto → (A).\n(A) Toronto\n(B) Ottawa\n(C) Winnipeg\n(D) Regina"},{"n":183,"q":"What is most likely true about Down the Mountainside?","qvi":"Điều gì nhiều khả năng đúng về cuốn Down the Mountainside?","opts":["It is the author's first book.","It is a collection of short stories.","It is part of a series.","It is being translated into French."],"ans":"C","xp":"Câu hỏi suy luận. \"the author of the best-selling series about detective Charles Martin\", \"The new work sees Martin investigating...\", \"this installment is Darr's strongest work\", \"newcomers to the Martin series\" → cuốn sách là một phần (installment) của loạt truyện → (C). (A) sai vì độc giả đã gặp Martin trước đó trong The Doorbell. (D) sai: 'French Alps' chỉ là bối cảnh, không nói dịch sang tiếng Pháp.\n(A) Đây là cuốn sách đầu tiên của tác giả.\n(B) Đây là tuyển tập truyện ngắn.\n(C) Đây là một phần của một loạt truyện.\n(D) Nó đang được dịch sang tiếng Pháp."},{"n":184,"q":"Who is Mr. Martin?","qvi":"Ông Martin là ai?","opts":["A fan of the author's","A character in the book","The writer of the review","The owner of a bookstore"],"ans":"B","xp":"Câu hỏi chi tiết. \"the best-selling series about detective Charles Martin\" và \"The new work sees Martin investigating mysterious events at a ski resort\" → Martin là thám tử, nhân vật trong truyện → (B). Người viết bài điểm sách là Camile Lin, không phải Martin.\n(A) Một người hâm mộ tác giả\n(B) Một nhân vật trong sách\n(C) Người viết bài điểm sách\n(D) Chủ một hiệu sách"},{"n":185,"q":"According to the review, who would most likely read Down the Mountainside?","qvi":"Theo bài điểm sách, ai nhiều khả năng sẽ đọc Down the Mountainside?","opts":["People who like to read mysteries","People who enjoy novels based on true stories","People who travel frequently","People who prefer science fiction"],"ans":"A","xp":"Câu hỏi chi tiết. Cuối bài: \"I highly recommend this book to all mystery fans.\" → những người thích đọc truyện trinh thám/bí ẩn → (A). 'mystery fans' = 'people who like to read mysteries'.\n(A) Những người thích đọc truyện trinh thám\n(B) Những người thích tiểu thuyết dựa trên chuyện có thật\n(C) Những người hay đi du lịch\n(D) Những người thích khoa học viễn tưởng"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following report, letter, and article.","passages":["<h3>Annual Citrus Production in Yuma County</h3><ul><li>82 tons of citrus fruit</li><li>Over 120,000 boxes of lemons</li><li>15,000 boxes of oranges</li><li>9,000 boxes of grapefruit</li><li>$190 million in revenue</li></ul><p>Employing close to 3,000 workers and contributing nearly $2 million in taxes to fund public services for the county</p><p>—Arizona Agriculture Division</p>","<p>City West Bank<br>455 Canyon Avenue<br>Phoenix, Arizona 85007</p><p>March 21</p><p>Domingo Ramirez, Director<br>Arizona Agriculture Division<br>55 Sixth Avenue<br>Yuma, Arizona 85364</p><p>Dear Mr. Ramirez,</p><p>I read the recent report from the Arizona Agriculture Division summarizing Yuma County's success in the citrus industry. City West Bank wants to help the Arizona Agriculture Division you lead by expanding this industry further. We offer low-interest loans and provide expert advice through our connections to area chambers of commerce and to agricultural researchers at Arizona's state universities.</p><p>We recognize that agritourism in southwest Arizona is growing as a result of the popularity of farm tours, bird-watching, and scenic country lodging, but tourism is unlikely to surpass the strength of this region's agriculture production. We support farmers in many counties in Arizona and are poised to help the citrus growers in Yuma County. Together, we can accomplish great things.</p><p>Cordially,</p><p><i>Bianca Schreiber</i><br>Bianca Schreiber<br>Industry Investment Programs</p>","<h3>Schreiber Named Vice President of National Investment Strategies</h3><p>PHOENIX (January 19)—City West Bank announced today that Ms. Bianca Schreiber will be promoted to vice president of National Investment Strategies effective February 1. Ms. Schreiber currently oversees City West Bank's Industry Investment Programs, serving businesses throughout Arizona.</p><p>Bank President William Dolle cited Ms. Schreiber's record of successful investment in the agricultural sector. \"Ms. Schreiber's efforts in working with the director of the Arizona Agriculture Division have significantly boosted citrus production. Yuma County now produces as many grapefruit as it does oranges. Ms. Schreiber's keen insight will make her even more valuable to us in her new role,\" remarked Mr. Dolle.</p>"],"vi":"Sản lượng cây có múi hằng năm tại hạt Yuma\n\n- 82 tấn trái cây có múi\n- Hơn 120.000 thùng chanh vàng\n- 15.000 thùng cam\n- 9.000 thùng bưởi chùm\n- Doanh thu 190 triệu đô la\n\nSử dụng gần 3.000 lao động và đóng góp gần 2 triệu đô la tiền thuế để tài trợ các dịch vụ công của hạt\n\n—Sở Nông nghiệp Arizona\n\n---\n\nNgân hàng City West\n455 Canyon Avenue\nPhoenix, Arizona 85007\n\nNgày 21 tháng 3\n\nDomingo Ramirez, Giám đốc\nSở Nông nghiệp Arizona\n55 Sixth Avenue\nYuma, Arizona 85364\n\nKính gửi ông Ramirez,\n\nTôi đã đọc báo cáo gần đây của Sở Nông nghiệp Arizona tóm tắt thành công của hạt Yuma trong ngành cây có múi. Ngân hàng City West muốn giúp Sở Nông nghiệp Arizona do ông lãnh đạo mở rộng ngành này hơn nữa. Chúng tôi cung cấp các khoản vay lãi suất thấp và tư vấn chuyên môn thông qua mối quan hệ của chúng tôi với các phòng thương mại trong khu vực và với các nhà nghiên cứu nông nghiệp tại các trường đại học công lập của Arizona.\n\nChúng tôi nhận thấy rằng du lịch nông nghiệp ở tây nam Arizona đang phát triển nhờ sự phổ biến của các tour tham quan nông trại, hoạt động ngắm chim và chỗ nghỉ đồng quê có cảnh đẹp, nhưng du lịch khó có thể vượt qua thế mạnh sản xuất nông nghiệp của vùng này. Chúng tôi hỗ trợ nông dân ở nhiều hạt của Arizona và sẵn sàng giúp đỡ những người trồng cây có múi ở hạt Yuma. Cùng nhau, chúng ta có thể làm được những điều tuyệt vời.\n\nTrân trọng,\n\nBianca Schreiber\nBộ phận Chương trình Đầu tư Ngành\n\n---\n\nSchreiber được bổ nhiệm làm Phó chủ tịch phụ trách Chiến lược Đầu tư Quốc gia\n\nPHOENIX (19 tháng 1) — Ngân hàng City West hôm nay thông báo rằng bà Bianca Schreiber sẽ được thăng chức lên phó chủ tịch phụ trách Chiến lược Đầu tư Quốc gia, có hiệu lực từ ngày 1 tháng 2. Bà Schreiber hiện đang phụ trách các Chương trình Đầu tư Ngành của Ngân hàng City West, phục vụ các doanh nghiệp trên khắp Arizona.\n\nChủ tịch ngân hàng William Dolle nêu bật thành tích đầu tư thành công của bà Schreiber vào lĩnh vực nông nghiệp. \"Những nỗ lực của bà Schreiber trong việc hợp tác với giám đốc Sở Nông nghiệp Arizona đã thúc đẩy đáng kể sản lượng cây có múi. Hạt Yuma giờ đây sản xuất bưởi chùm nhiều bằng cam. Sự nhạy bén của bà Schreiber sẽ khiến bà càng có giá trị hơn với chúng tôi trong vai trò mới,\" ông Dolle nhận xét.","qs":[{"n":186,"q":"What does the report indicate about the Yuma County region?","qvi":"Báo cáo cho biết điều gì về vùng hạt Yuma?","opts":["It does not tax fruit that is sold there.","Several types of fruit are cultivated there.","More workers are needed for agricultural jobs.","New types of fruit are being produced there."],"ans":"B","xp":"Câu hỏi chi tiết. Báo cáo liệt kê \"boxes of lemons\", \"boxes of oranges\", \"boxes of grapefruit\" → vùng này trồng nhiều loại trái cây (chanh, cam, bưởi) → (B). (A) sai vì có nhắc đến thuế (\"contributing nearly $2 million in taxes\"); (C), (D) không được đề cập.\n(A) Vùng này không đánh thuế trái cây bán ở đó.\n(B) Nhiều loại trái cây được trồng ở đó.\n(C) Cần thêm lao động cho các công việc nông nghiệp.\n(D) Những loại trái cây mới đang được sản xuất ở đó."},{"n":187,"q":"What is one reason Ms. Schreiber writes to Mr. Ramirez?","qvi":"Một lý do bà Schreiber viết thư cho ông Ramirez là gì?","opts":["To explain the benefits of doing business together","To clarify information in the report","To remind him to make a loan payment","To offer him advice from university agricultural researchers"],"ans":"A","xp":"Câu hỏi mục đích. Bức thư: \"City West Bank wants to help the Arizona Agriculture Division ... We offer low-interest loans and provide expert advice ...\" và \"Together, we can accomplish great things.\" → bà giới thiệu lợi ích khi hợp tác kinh doanh với ngân hàng → (A). (D) chưa chính xác: ngân hàng đưa ra lời khuyên chuyên môn 'thông qua mối quan hệ' với các nhà nghiên cứu, chứ thư không trực tiếp đưa lời khuyên của họ; (B), (C) không có.\n(A) Để giải thích lợi ích của việc hợp tác kinh doanh với nhau\n(B) Để làm rõ thông tin trong báo cáo\n(C) Để nhắc ông ấy trả khoản vay\n(D) Để đưa cho ông ấy lời khuyên từ các nhà nghiên cứu nông nghiệp ở đại học"},{"n":188,"q":"According to the letter, why do tourists visit Yuma County?","qvi":"Theo bức thư, vì sao du khách đến thăm hạt Yuma?","opts":["To shop at farmers markets","To take pictures","To enjoy theme parks","To observe wildlife"],"ans":"D","xp":"Câu hỏi chi tiết. Thư: \"agritourism in southwest Arizona is growing as a result of the popularity of farm tours, bird-watching, and scenic country lodging\" → bird-watching (ngắm chim) được diễn đạt lại thành 'observe wildlife' (quan sát động vật hoang dã) → (D).\n(A) Để mua sắm ở chợ nông sản\n(B) Để chụp ảnh\n(C) Để vui chơi ở công viên giải trí\n(D) Để quan sát động vật hoang dã"},{"n":189,"q":"What is suggested about Mr. Ramirez?","qvi":"Điều gì được gợi ý về ông Ramirez?","opts":["He accepted Ms. Schreiber's proposal.","He used to be employed by City West Bank.","He is a member of the Yuma Chamber of Commerce.","He recently bought a citrus farm."],"ans":"A","xp":"Câu hỏi suy luận, liên kết 3 bài. Thư cho thấy ông Ramirez là giám đốc Sở Nông nghiệp Arizona (\"Domingo Ramirez, Director, Arizona Agriculture Division\") và bà Schreiber đề nghị hợp tác. Bài báo: \"Ms. Schreiber's efforts in working with the director of the Arizona Agriculture Division have significantly boosted citrus production\" → hai bên đã hợp tác, tức ông Ramirez đã chấp nhận đề xuất của bà → (A).\n(A) Ông ấy đã chấp nhận đề xuất của bà Schreiber.\n(B) Ông ấy từng làm việc cho Ngân hàng City West.\n(C) Ông ấy là thành viên Phòng Thương mại Yuma.\n(D) Ông ấy vừa mua một trang trại cây có múi."},{"n":190,"q":"For what accomplishment does Mr. Dolle praise Ms. Schreiber?","qvi":"Ông Dolle khen ngợi bà Schreiber về thành tích nào?","opts":["Arranging the shipping of agricultural products","Opening many City West Bank branch offices","Helping to increase grapefruit production to 15,000 boxes","Promoting Yuma County as a vacation destination"],"ans":"C","xp":"Câu hỏi liên kết 2 bài. Bài báo: \"Ms. Schreiber's efforts ... have significantly boosted citrus production. Yuma County now produces as many grapefruit as it does oranges.\" Báo cáo cho biết hạt Yuma sản xuất \"15,000 boxes of oranges\" (và trước đây chỉ có 9,000 thùng bưởi) → nay bưởi cũng đạt 15.000 thùng → bà được khen vì giúp tăng sản lượng bưởi lên 15.000 thùng → (C).\n(A) Sắp xếp vận chuyển nông sản\n(B) Mở nhiều chi nhánh Ngân hàng City West\n(C) Giúp tăng sản lượng bưởi lên 15.000 thùng\n(D) Quảng bá hạt Yuma như một điểm du lịch nghỉ dưỡng"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following invitation, Web page, and e-mail.","passages":["<p>https://www.unetcon.org/messages_audreysmith80</p><h3>Unetcon – Message Center</h3><p>Pending Invitations</p><p><b>From: Don Fitzpatrick</b><br>Branch Manager, Wilsonville Financial</p><p><b>To: Audrey Smith</b></p><p>Dear Audrey,</p><p>Please accept this invitation to connect professionally on Unetcon. I am a fellow Stonerook University graduate and am always looking to expand my network. In this case, I am also reaching out to see if you would be interested in joining the private Stonerook alumni group page to stay current with everything that our fellow graduates are up to. https://www.unetcon.org/private/stonerookugrads.</p><p>Kind regards,<br>Don Fitzpatrick</p><p>[Accept Invitation] [Ignore Invitation] [Reply to Don]</p>","<p>https://www.unetcon.org/private/stonerookugrads</p><h3>Stonerook University Graduates</h3><p>Check out the continued success and latest updates from Stonerook graduate Jonah Hilliard.</p><table><tr><th>Current</th><th>Education</th><th>Professional</th></tr><tr><td>Director,<br>Albright School of Business<br><br>Founder and Director,<br>Clear Path<br><br><u>Contact</u><br>Phone: 843-555-0139<br>E-mail: jhilliard@mccleese.edu<br>Office: 403 Cordon Hall<br>530 N Kensington St.<br>Charleston, SC 29425</td><td>Master of Business Administration – Turnbull University<br><br>Bachelor of Arts in Education Studies – Stonerook University</td><td>Mr. Hilliard has led the Albright School of Business since 2017. Between 2007 and 2017, he carried out extensive research on emerging markets in West Africa while teaching business management in Lagos, Nigeria. Two years ago, he founded Clear Path, a business that advises students from around the globe who wish to pursue studies in the United States.</td></tr></table>","<div class=\"hdr\"><p><b>From:</b> Audrey Smith &lt;audrey_smith80@rapidonet.co.uk&gt;</p><p><b>To:</b> Jonah Hilliard &lt;jhilliard@mccleese.edu&gt;</p><p><b>Date:</b> 19 September</p><p><b>Subject:</b> Referral</p></div><p>Dear Jonah,</p><p>It has been a long time since we last talked. I recently came across your profile on Unetcon and saw that you are now leading the business school at McCleese! My research in Lagos ended last year, when I accepted a position as lead consultant at Pryor and Martell. I have been based here in Manchester ever since.</p><p>Congratulations to you on your most recent business venture—Clear Path already has quite an impressive reputation! I have a nephew who is interested in pursuing a degree in management information systems in the United States, and I was hoping I could put you both in touch so that he can take advantage of your new company's expertise in this area.</p><p>Best,</p><p>Audrey Smith</p>"],"vi":"https://www.unetcon.org/messages_audreysmith80\n\nUnetcon – Trung tâm tin nhắn\nLời mời đang chờ\n\nTừ: Don Fitzpatrick\nQuản lý chi nhánh, Wilsonville Financial\n\nGửi: Audrey Smith\n\nAudrey thân mến,\n\nVui lòng chấp nhận lời mời kết nối nghề nghiệp này trên Unetcon. Tôi cũng là cựu sinh viên Đại học Stonerook và luôn tìm cách mở rộng mạng lưới quan hệ của mình. Lần này, tôi cũng liên hệ để xem bạn có muốn tham gia trang nhóm cựu sinh viên Stonerook riêng tư để cập nhật mọi hoạt động của các bạn đồng môn hay không. https://www.unetcon.org/private/stonerookugrads.\n\nTrân trọng,\nDon Fitzpatrick\n\n[Chấp nhận lời mời] [Bỏ qua lời mời] [Trả lời Don]\n\n---\n\nhttps://www.unetcon.org/private/stonerookugrads\n\nCựu sinh viên Đại học Stonerook\n\nHãy xem những thành công liên tục và cập nhật mới nhất từ cựu sinh viên Stonerook Jonah Hilliard.\n\nHiện tại: Giám đốc, Trường Kinh doanh Albright; Nhà sáng lập kiêm Giám đốc, Clear Path. Liên hệ: Điện thoại: 843-555-0139; E-mail: jhilliard@mccleese.edu; Văn phòng: 403 Cordon Hall, 530 N Kensington St., Charleston, SC 29425\n\nHọc vấn: Thạc sĩ Quản trị Kinh doanh – Đại học Turnbull; Cử nhân Nghệ thuật ngành Nghiên cứu Giáo dục – Đại học Stonerook\n\nNghề nghiệp: Ông Hilliard đã lãnh đạo Trường Kinh doanh Albright từ năm 2017. Từ năm 2007 đến 2017, ông đã thực hiện nghiên cứu sâu rộng về các thị trường mới nổi ở Tây Phi trong khi giảng dạy quản trị kinh doanh tại Lagos, Nigeria. Hai năm trước, ông thành lập Clear Path, một doanh nghiệp tư vấn cho sinh viên khắp thế giới muốn theo học tại Hoa Kỳ.\n\n---\n\nTừ: Audrey Smith <audrey_smith80@rapidonet.co.uk>\nGửi: Jonah Hilliard <jhilliard@mccleese.edu>\nNgày: 19 tháng 9\nTiêu đề: Giới thiệu\n\nJonah thân mến,\n\nĐã lâu rồi chúng ta không nói chuyện. Gần đây tôi tình cờ thấy hồ sơ của anh trên Unetcon và biết rằng anh hiện đang lãnh đạo trường kinh doanh ở McCleese! Công việc nghiên cứu của tôi ở Lagos đã kết thúc vào năm ngoái, khi tôi nhận vị trí trưởng nhóm tư vấn tại Pryor and Martell. Từ đó tôi làm việc ở Manchester.\n\nChúc mừng anh về dự án kinh doanh gần đây nhất — Clear Path đã có danh tiếng khá ấn tượng rồi! Tôi có một người cháu trai muốn theo học bằng hệ thống thông tin quản lý tại Hoa Kỳ, và tôi hy vọng có thể kết nối hai người với nhau để cháu có thể tận dụng chuyên môn của công ty mới của anh trong lĩnh vực này.\n\nThân,\n\nAudrey Smith","qs":[{"n":191,"q":"What does the invitation indicate about Unetcon?","qvi":"Lời mời cho biết điều gì về Unetcon?","opts":["It is a business consulting firm.","It is a financial services company.","It is an employment agency.","It is a professional networking Web site."],"ans":"D","xp":"Câu hỏi chi tiết. Lời mời: \"Please accept this invitation to connect professionally on Unetcon ... always looking to expand my network\" và có địa chỉ web www.unetcon.org → Unetcon là trang web kết nối nghề nghiệp → (D). (B) dễ nhầm vì Don làm ở Wilsonville Financial, nhưng đó là công ty của Don, không phải Unetcon.\n(A) Đó là công ty tư vấn kinh doanh.\n(B) Đó là công ty dịch vụ tài chính.\n(C) Đó là công ty giới thiệu việc làm.\n(D) Đó là trang web kết nối nghề nghiệp."},{"n":192,"q":"According to the Web page, where is Mr. Hilliard currently working?","qvi":"Theo trang web, ông Hilliard hiện đang làm việc ở đâu?","opts":["In Lagos","In Charleston","In Wilsonville","In Manchester"],"ans":"B","xp":"Câu hỏi chi tiết. Phần Contact trên trang web: \"Office: 403 Cordon Hall, 530 N Kensington St., Charleston, SC 29425\" → văn phòng hiện tại ở Charleston → (B). (A) Lagos là nơi ông làm việc trong quá khứ (2007–2017); (D) Manchester là nơi bà Smith làm việc; (C) Wilsonville là tên công ty của Don.\n(A) Ở Lagos\n(B) Ở Charleston\n(C) Ở Wilsonville\n(D) Ở Manchester"},{"n":193,"q":"What is suggested about Ms. Smith?","qvi":"Điều gì được gợi ý về bà Smith?","opts":["She taught at Stonerook University.","She works at Wilsonville Financial.","She accepted Mr. Fitzpatrick's invitation.","She plans to visit Lagos this year."],"ans":"C","xp":"Câu hỏi suy luận, liên kết 3 bài. Ông Fitzpatrick mời bà Smith tham gia trang nhóm riêng tư (private) của cựu sinh viên Stonerook. Thông tin về ông Hilliard nằm trên trang riêng tư đó, và trong e-mail bà Smith viết: \"I recently came across your profile on Unetcon\" → bà đã vào được trang nhóm, tức là đã chấp nhận lời mời → (C). (B) sai: bà làm ở Pryor and Martell; (D) sai: nghiên cứu ở Lagos đã kết thúc năm ngoái.\n(A) Bà ấy từng dạy ở Đại học Stonerook.\n(B) Bà ấy làm việc tại Wilsonville Financial.\n(C) Bà ấy đã chấp nhận lời mời của ông Fitzpatrick.\n(D) Bà ấy dự định thăm Lagos năm nay."},{"n":194,"q":"What do Ms. Smith and Mr. Hilliard have in common?","qvi":"Bà Smith và ông Hilliard có điểm gì chung?","opts":["They cofounded Clear Path.","They are colleagues at Pryor and Martell.","They were classmates at Turnbull University.","They both conducted research in Nigeria."],"ans":"D","xp":"Câu hỏi liên kết 2 bài. Trang web: Hilliard \"carried out extensive research on emerging markets in West Africa while teaching business management in Lagos, Nigeria\". E-mail: \"My research in Lagos ended last year\" → cả hai đều từng nghiên cứu ở Lagos, Nigeria → (D). (A) sai: Hilliard tự lập Clear Path; (B) sai: chỉ Smith làm ở Pryor and Martell; (C) không có thông tin.\n(A) Họ đồng sáng lập Clear Path.\n(B) Họ là đồng nghiệp ở Pryor and Martell.\n(C) Họ từng là bạn cùng lớp ở Đại học Turnbull.\n(D) Cả hai đều từng nghiên cứu ở Nigeria."},{"n":195,"q":"What is one purpose of Ms. Smith's e-mail to Mr. Hilliard?","qvi":"Một mục đích của e-mail bà Smith gửi ông Hilliard là gì?","opts":["To request his professional services","To provide a professional reference","To conduct an informational interview","To apply for a position at Albright School of Business"],"ans":"A","xp":"Câu hỏi mục đích. E-mail: \"I have a nephew who is interested in pursuing a degree ... in the United States, and I was hoping I could put you both in touch so that he can take advantage of your new company's expertise\" → bà muốn nhờ dịch vụ tư vấn du học của công ty Clear Path của ông cho cháu mình → yêu cầu dịch vụ chuyên môn của ông → (A). (B) dễ nhầm vì tiêu đề 'Referral' (giới thiệu người), nhưng 'professional reference' là thư/lời giới thiệu xác nhận năng lực, không phải mục đích ở đây.\n(A) Để yêu cầu dịch vụ chuyên môn của ông ấy\n(B) Để cung cấp thư giới thiệu nghề nghiệp\n(C) Để thực hiện một buổi phỏng vấn tìm hiểu thông tin\n(D) Để ứng tuyển vào một vị trí ở Trường Kinh doanh Albright"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following brochure, article, and e-mail.","passages":["<h3>Modern Salon Academy</h3><p>www.modernsalonacademy.ca</p><p>Established more than twenty years ago, Modern Salon Academy is Toronto's most recognized beauty school. The school offers hands-on training, small class sizes, and individualized instruction from leading industry professionals in the following programs.</p><ul><li>Cosmetology I: Gain foundational knowledge of haircutting and styling.</li><li>Cosmetology II: Learn techniques in haircutting, styling, and colouring.</li><li>Skin Care: Learn techniques in providing advanced skin-care treatments.</li><li>Leadership: Study salon management, business operations, and compliance.</li></ul><p>Modern Salon Academy is a winner of the International Cosmetology Society's prestigious Award of Excellence. It is no surprise, then, that over 95 percent of our graduates have gone on to successful careers in both the beauty and fashion industries.</p>","<h3>Modern Salon Academy Expands in Ontario</h3><p>TORONTO (23 August)—Modern Salon Academy, a highly regarded beauty school here in Toronto, is opening a regional campus in Oshawa. The school is already admitting students for classes that are scheduled to begin on 4 October.</p><p>Modern Salon Academy has had a substantial rise in enrollment over the past few years. Francine Dupuis, educational director of Modern Salon Academy, notes, \"More than half our students live outside the city limits, so having a satellite campus makes perfect sense.\"</p><p>Modern Salon Academy offers professional training and certification for careers in a variety of areas, including hair care, skin care, and makeup. For more information about Modern Salon Academy, including admission requirements, fees, and academic calendars, visit www.modernsalonacademy.ca.</p><p>—Chrissy Jellen for the <i>Ontario Daily Times</i></p>","<div class=\"hdr\"><p><b>To:</b> Francine Dupuis &lt;francine.dupuis@modernsalonacademy.ca&gt;</p><p><b>From:</b> Amit Persaud &lt;amit@shorelinebarbers.ca&gt;</p><p><b>Subject:</b> Entry-level job opportunities</p><p><b>Date:</b> 19 November</p></div><p>Dear Ms. Dupuis,</p><p>My name is Amit Persaud, and I am the owner and operator of Shoreline Barbers. I am interested in recruiting some of your graduating students to work at my barbershop, which is just around the corner from your newly established regional campus. I am seeking highly qualified, entry-level employees who can provide both haircutting and hair-colouring services.</p><p>Would it be possible for me to visit the nearby campus to give interested students an opportunity to talk with me? This would be a convenient way for me to evaluate them for the positions I am seeking to fill, and then I can also answer any questions they may have. Please let me know if an arrangement can be made.</p><p>Sincerely,</p><p>Amit Persaud</p>"],"vi":"Học viện Modern Salon\nwww.modernsalonacademy.ca\n\nĐược thành lập cách đây hơn hai mươi năm, Học viện Modern Salon là trường dạy làm đẹp được công nhận nhiều nhất ở Toronto. Trường cung cấp đào tạo thực hành, lớp học sĩ số nhỏ và hướng dẫn riêng cho từng học viên bởi các chuyên gia hàng đầu trong ngành, với các chương trình sau.\n\n- Thẩm mỹ I: Nắm kiến thức nền tảng về cắt và tạo kiểu tóc.\n- Thẩm mỹ II: Học các kỹ thuật cắt, tạo kiểu và nhuộm tóc.\n- Chăm sóc da: Học các kỹ thuật thực hiện liệu trình chăm sóc da nâng cao.\n- Lãnh đạo: Học quản lý salon, vận hành kinh doanh và tuân thủ quy định.\n\nHọc viện Modern Salon là đơn vị đoạt Giải thưởng Xuất sắc danh giá của Hiệp hội Thẩm mỹ Quốc tế. Vì vậy, không có gì ngạc nhiên khi hơn 95 phần trăm học viên tốt nghiệp của chúng tôi đã có sự nghiệp thành công trong cả ngành làm đẹp và thời trang.\n\n---\n\nHọc viện Modern Salon mở rộng tại Ontario\n\nTORONTO (23 tháng 8) — Học viện Modern Salon, một trường dạy làm đẹp được đánh giá cao tại Toronto, đang mở một cơ sở khu vực ở Oshawa. Trường đã bắt đầu nhận học viên cho các lớp dự kiến khai giảng vào ngày 4 tháng 10.\n\nHọc viện Modern Salon đã có mức tăng đáng kể về số lượng học viên đăng ký trong vài năm qua. Francine Dupuis, giám đốc đào tạo của Học viện Modern Salon, cho biết: \"Hơn một nửa học viên của chúng tôi sống bên ngoài ranh giới thành phố, vì vậy việc có một cơ sở vệ tinh là hoàn toàn hợp lý.\"\n\nHọc viện Modern Salon cung cấp đào tạo chuyên nghiệp và cấp chứng chỉ cho các nghề thuộc nhiều lĩnh vực, bao gồm chăm sóc tóc, chăm sóc da và trang điểm. Để biết thêm thông tin về Học viện Modern Salon, bao gồm điều kiện tuyển sinh, học phí và lịch học, hãy truy cập www.modernsalonacademy.ca.\n\n—Chrissy Jellen viết cho tờ Ontario Daily Times\n\n---\n\nGửi: Francine Dupuis <francine.dupuis@modernsalonacademy.ca>\nTừ: Amit Persaud <amit@shorelinebarbers.ca>\nTiêu đề: Cơ hội việc làm cho người mới vào nghề\nNgày: 19 tháng 11\n\nKính gửi bà Dupuis,\n\nTôi tên là Amit Persaud, chủ sở hữu và người điều hành tiệm Shoreline Barbers. Tôi muốn tuyển một số học viên sắp tốt nghiệp của quý trường đến làm việc tại tiệm cắt tóc của tôi, nằm ngay gần cơ sở khu vực mới thành lập của quý trường. Tôi đang tìm những nhân viên mới vào nghề có trình độ cao, có thể làm cả dịch vụ cắt tóc và nhuộm tóc.\n\nLiệu tôi có thể đến thăm cơ sở gần đó để tạo cơ hội cho các học viên quan tâm trò chuyện với tôi không? Đây sẽ là cách thuận tiện để tôi đánh giá họ cho các vị trí tôi đang muốn tuyển, đồng thời tôi cũng có thể trả lời bất kỳ câu hỏi nào của họ. Xin bà cho tôi biết liệu có thể sắp xếp được không.\n\nTrân trọng,\n\nAmit Persaud","qs":[{"n":196,"q":"How does Modern Salon Academy teach its students?","qvi":"Học viện Modern Salon dạy học viên bằng cách nào?","opts":["Through online courses","Through academic lectures","Through individualized training","Through large-group discussions"],"ans":"C","xp":"Câu hỏi chi tiết. Tờ giới thiệu: \"The school offers hands-on training, small class sizes, and individualized instruction\" → 'individualized instruction' = 'individualized training' (đào tạo riêng cho từng người) → (C). (D) trái ngược với 'small class sizes'.\n(A) Qua các khóa học trực tuyến\n(B) Qua các bài giảng lý thuyết\n(C) Qua đào tạo riêng cho từng người\n(D) Qua thảo luận nhóm lớn"},{"n":197,"q":"According to the article, what has increased at Modern Salon Academy?","qvi":"Theo bài báo, điều gì đã tăng lên ở Học viện Modern Salon?","opts":["The cost of tuition","The number of students","The requirements for admission","The hours needed for certification"],"ans":"B","xp":"Câu hỏi chi tiết. Bài báo: \"Modern Salon Academy has had a substantial rise in enrollment over the past few years.\" → 'rise in enrollment' (tăng số người đăng ký học) = số lượng học viên tăng → (B). Học phí và điều kiện tuyển sinh chỉ được nhắc khi giới thiệu trang web, không nói là tăng.\n(A) Học phí\n(B) Số lượng học viên\n(C) Điều kiện tuyển sinh\n(D) Số giờ học cần để lấy chứng chỉ"},{"n":198,"q":"What is most likely true about Shoreline Barbers?","qvi":"Điều gì nhiều khả năng đúng về tiệm Shoreline Barbers?","opts":["It is located in Oshawa.","It is opening a shop in Toronto.","It was sold to Francine Dupuis.","It has very affordable services."],"ans":"A","xp":"Câu hỏi suy luận, liên kết 2 bài. E-mail: tiệm \"is just around the corner from your newly established regional campus\" (ngay gần cơ sở khu vực mới thành lập). Bài báo: trường \"is opening a regional campus in Oshawa\" → tiệm Shoreline Barbers nằm ở Oshawa → (A).\n(A) Tiệm nằm ở Oshawa.\n(B) Tiệm sắp mở cửa hàng ở Toronto.\n(C) Tiệm đã được bán cho Francine Dupuis.\n(D) Tiệm có dịch vụ rất rẻ."},{"n":199,"q":"Who would best meet Mr. Persaud's needs?","qvi":"Ai đáp ứng tốt nhất nhu cầu của ông Persaud?","opts":["Students in Cosmetology I","Students in Cosmetology II","Students in Skin Care","Students in Leadership"],"ans":"B","xp":"Câu hỏi liên kết 2 bài. E-mail: ông cần nhân viên \"who can provide both haircutting and hair-colouring services\" (cả cắt và nhuộm tóc). Tờ giới thiệu: \"Cosmetology II: Learn techniques in haircutting, styling, and colouring.\" → chỉ Cosmetology II dạy cả cắt và nhuộm → (B). Cosmetology I chỉ có cắt và tạo kiểu, không có nhuộm.\n(A) Học viên lớp Thẩm mỹ I\n(B) Học viên lớp Thẩm mỹ II\n(C) Học viên lớp Chăm sóc da\n(D) Học viên lớp Lãnh đạo"},{"n":200,"q":"According to the e-mail, what does Mr. Persaud want to do?","qvi":"Theo e-mail, ông Persaud muốn làm gì?","opts":["Establish another business","Retrain staff members","Teach some classes","Interview some students"],"ans":"D","xp":"Câu hỏi chi tiết. E-mail: \"Would it be possible for me to visit the nearby campus to give interested students an opportunity to talk with me? This would be a convenient way for me to evaluate them for the positions\" → đến trường nói chuyện và đánh giá học viên cho vị trí tuyển dụng = phỏng vấn học viên → (D).\n(A) Thành lập một doanh nghiệp khác\n(B) Đào tạo lại nhân viên\n(C) Dạy một số lớp học\n(D) Phỏng vấn một số học viên"}]}]}};
